    } else if !std::env::args().any(|x| x == "--c1-only") {
        masks(&a, &z, &sets[0].1);
    }
}

//! Z5: enumeration and cached observations around Z4c's unchanged Ech rank machinery.
use super::*;
use std::collections::BTreeMap;
use std::sync::OnceLock;
static SELECTED: OnceLock<[u16; N]> = OnceLock::new();
pub(super) fn transport() -> &'static [u16; N] {
    SELECTED.get().unwrap_or(&r0::transport::ROW_TO_COEFFICIENT)
}
pub(super) fn is_selected() -> bool { SELECTED.get().is_some() }
/// Z9: select a row-to-coefficient transport (D18 for R1) before first use.
pub(super) fn set_transport(pi: [u16; N]) {
    SELECTED.set(pi).expect("a row-to-coefficient transport is already selected");
}
const MASTER: u64 = 0x5348f0b9a87835d0;
const SEARCH_SEED: u64 = 0x5a35d16120261010;
#[derive(Clone, Debug)]
struct Candidate { tau: [usize; 5], sigma: [[usize; 4]; 5] }
impl Candidate {
    fn map(&self) -> [u16; N] {
        std::array::from_fn(|r| (0..5).map(|d| self.sigma[d][(r >> (2*self.tau[d])) & 3] << (2*d)).sum::<usize>() as u16)
    }
}
fn permutations<const D: usize>() -> Vec<[usize; D]> {
    fn visit<const D: usize>(v: &mut [usize; D], i: usize, out: &mut Vec<[usize; D]>) {
        if i == D { out.push(*v); return; }
        for j in i..D { v.swap(i,j); visit(v,i+1,out); v.swap(i,j); }
    }
    let mut out = vec![];
    visit(&mut std::array::from_fn(|i| i),0,&mut out);
    out.sort(); out
}
// Rejection sampling avoids modulo bias for every Fisher-Yates choice.
fn uniform(rng: &mut Rng, n: u64) -> usize {
    let bound = u64::MAX - u64::MAX % n;
    loop { let x = rng.next(); if x < bound { return (x % n) as usize; } }
}
fn random_perm<const D: usize>(rng: &mut Rng) -> [usize; D] {
    let mut p = std::array::from_fn(|i| i);
    for i in (1..D).rev() { p.swap(i, uniform(rng,(i+1) as u64)); }
    p
}
fn challenge(trial: usize) -> ([QM31;10], [Point<QM31>;2], Vec<usize>) {
    let mut rng = Rng(MASTER.wrapping_add((trial as u64+1).wrapping_mul(0x9e3779b97f4a7c15)));
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()),circle(rng.q())];
    let qs = query_sets(&mut rng).remove(0).1;
    (a,z,qs)
}
struct Tables {
    claim: Vec<Vec<M31>>,
    coefficient: Vec<Vec<M31>>,
    allowed: Vec<Vec<usize>>,
    group: [usize;16],
}
impl Tables {
    fn new(a: &[QM31;10], z: &[Point<QM31>;2], qs: &[usize]) -> Self {
        let id = std::array::from_fn(|r| r as u16);
        let (raw,_) = raw_c_with_transport(a,z,qs,&id);
        let mut allowed: Vec<Vec<usize>> = vec![];
        let group = std::array::from_fn(|c| {
            let rows: Vec<_> = (0..N).filter(|&r| r!=1023 && eligible(c,r)).collect();
            if let Some(i) = allowed.iter().position(|old| *old == rows) { i }
            else { allowed.push(rows); allowed.len()-1 }
        });
        Self { claim: raw.iter().map(|r|r[1..13].to_vec()).collect(),
            coefficient: raw.iter().map(|r|r[13..].to_vec()).collect(), allowed, group }
    }
    fn row(&self, pi: &[u16;N], r: usize) -> Vec<M31> {
        let mut v = self.claim[r].clone();
        v.extend_from_slice(&self.coefficient[usize::from(pi[r])]);
        if inactive(r) {
            for i in 0..12 { v[i] = v[i].sub(self.claim[1023][i]); }
            for i in 12..112 { v[i] = v[i].sub(self.coefficient[usize::from(pi[1023])][i-12]); }
        }
        v
    }
    fn rank(&self, pi: &[u16;N], group: usize) -> usize {
        let mut e = Ech::new(112);
        for &r in &self.allowed[group] {
            e.insert(self.row(pi,r));
            if e.rank == 112 { break; }
        }
        e.rank
    }
    fn ranks(&self, pi: &[u16;N]) -> [usize;16] {
        let gr: Vec<_> = (0..self.allowed.len()).map(|g|self.rank(pi,g)).collect();
        std::array::from_fn(|c|gr[self.group[c]])
    }
    fn audit(&self, pi: &[u16;N], a: &[QM31;10], z: &[Point<QM31>;2], qs: &[usize]) {
        let (raw,_) = raw_c_with_transport(a,z,qs,pi);
        for r in 0..N {
            let expected: Vec<_> = raw[r][1..].iter().zip(&raw[1023][1..])
                .map(|(x,d)|if inactive(r){x.sub(*d)}else{*x}).collect();
            assert_eq!(self.row(pi,r),expected);
        }
        // Original C1 loop: no caching, grouping or full-rank short circuit.
        let direct: [usize;16] = std::array::from_fn(|c| {
            let mut e=Ech::new(112);
            for r in 0..N {
                if r==1023 || !eligible(c,r) {continue;}
                e.insert(raw[r][1..].iter().zip(&raw[1023][1..])
                    .map(|(x,d)|if inactive(r){x.sub(*d)}else{*x}).collect());
            }
            e.rank
        });
        assert_eq!(self.ranks(pi),direct);
    }
}
fn arg(name: &str) -> Option<String> {
    std::env::args().collect::<Vec<_>>().windows(2).find(|x|x[0]==name).map(|x|x[1].clone())
}
fn report_full(label: &str, pi: &[u16;N], tables: &[Tables;2]) -> bool {
    let random=tables[0].ranks(pi); let consecutive=tables[1].ranks(pi);
    let pass=random.iter().chain(&consecutive).all(|&r|r==112);
    println!("Z5_RANKS label={label} random={random:?} consecutive={consecutive:?} pass={pass}");
    pass
}
pub(super) fn search() {
    let start=Instant::now();
    let (a,z,qs)=challenge(0);
    let consecutive: Vec<_>=(0..22).collect();
    let tables=[Tables::new(&a,&z,&qs),Tables::new(&a,&z,&consecutive)];
    println!("Z5_SEARCH base=600eb013878a0169cdab8f222e879cd395e3a1e2 challenge_seed={MASTER:#x} search_seed={SEARCH_SEED:#x} trial=0 alpha={a:?} circle={z:?} queries={qs:?} groups={:?}",tables[0].group);
    let id=std::array::from_fn(|r|r as u16);
    for (name,pi) in [("identity",id),("D13",r0::transport::ROW_TO_COEFFICIENT)] {
        tables[0].audit(&pi,&a,&z,&qs); tables[1].audit(&pi,&a,&z,&consecutive);
        report_full(name,&pi,&tables);
    }
    let mut audit_rng=Rng(SEARCH_SEED);
    let audit_candidate=Candidate{tau:random_perm(&mut audit_rng),sigma:std::array::from_fn(|_|random_perm(&mut audit_rng))};
    tables[0].audit(&audit_candidate.map(),&a,&z,&qs);
    tables[1].audit(&audit_candidate.map(),&a,&z,&consecutive);
    println!("Z5_AUDIT cached_rows_and_grouped_ranks_match_original=true transports=identity,D13,random_digit both_sets=true");
    if std::env::args().any(|x|x=="--preflight") {return;}
    let tau=permutations::<5>();let sigma=permutations::<4>();
    let random_count=arg("--random-count").map(|x|x.parse().unwrap()).unwrap_or(100000usize);
    assert!(random_count<=100000);
    let mut rng=Rng(SEARCH_SEED);
    let mut first: Option<(usize,Candidate)>=None;
    let mut passed=0; let mut failures=0; let mut checked=0;
    let exhaustive=std::env::args().any(|x|x=="--exhaustive");
    println!("Z5_POLICY exhaustive={exhaustive} stop_after_first_successful_stage={} all_passing_candidates_checked_on_20_z4c_vectors=true",!exhaustive);
    let mut later=Vec::new();
    for trial in 1..20 {
        let (a,z,qs)=challenge(trial);
        println!("Z5_CHALLENGE trial={trial} alpha={a:?} circle={z:?} queries={qs:?}");
        later.push([Tables::new(&a,&z,&qs),Tables::new(&a,&z,&consecutive)]);
    }
    let mut distribution=BTreeMap::<(usize,usize,usize,usize,usize),usize>::new();
    for stage in 1..=3 {
        let count=match stage {1=>tau.len(),2=>tau.len()*sigma.len(),_=>random_count};
        for index in 0..count {
            let candidate=match stage {
                1=>Candidate{tau:tau[index],sigma:[[0,1,2,3];5]},
                2=>{let mut s=[[0,1,2,3];5];s[0]=sigma[index%sigma.len()];Candidate{tau:tau[index/sigma.len()],sigma:s}},
                _=>Candidate{tau:random_perm(&mut rng),sigma:std::array::from_fn(|_|random_perm(&mut rng))},
            };
            let pi=candidate.map();
            let mut failure=None;
            // Reject on the first failing semantic column; test consecutive first.
            // Distinct semantic columns with identical source row lists share a rank.
            for (trial,tables) in std::iter::once(&tables).chain(later.iter()).enumerate() {
                for group in 0..tables[0].allowed.len() {
                    let column=tables[0].group.iter().position(|&g|g==group).unwrap();
                    for set in [1,0] {
                        let rank=tables[set].rank(&pi,group);
                        if rank<112 {failure=Some((trial,set,column,rank));break;}
                    }
                    if failure.is_some(){break;}
                }
                if failure.is_some(){break;}
            }
            checked+=1;
            if let Some((trial,set,column,rank))=failure {
                failures+=1;*distribution.entry((stage,trial,set,column,rank)).or_default()+=1;
                if failures<=20 {
                    println!("Z5_FAILURE ordinal={checked} stage={stage} index={index} tau={:?} sigma={:?} first_trial={trial} first_set={} first_column={column} first_rank={rank}",candidate.tau,candidate.sigma,if set==0{"random"}else{"consecutive"});
                    report_full(&format!("failure_{failures}"),&pi,if trial==0{&tables}else{&later[trial-1]});
                }
            } else {
                passed+=1;
                println!("Z5_PASS ordinal={checked} stage={stage} index={index} tau={:?} sigma={:?}",candidate.tau,candidate.sigma);
                for (trial,tables) in std::iter::once(&tables).chain(later.iter()).enumerate() {
                    assert!(report_full(&format!("pass_{passed}_trial_{trial}"),&pi,tables));
                }
                if first.is_none(){first=Some((checked,candidate));}
            }
            if checked%100==0 {println!("Z5_PROGRESS checked={checked} passed={passed} failures={failures} wall_seconds={:.3}",start.elapsed().as_secs_f64());}
        }
        println!("Z5_STAGE_DONE stage={stage} tested={count} cumulative_passed={passed} wall_seconds={:.3}",start.elapsed().as_secs_f64());
        if passed>0 && !exhaustive { break; }
    }
    for ((stage,trial,set,column,rank),count) in distribution {
        println!("Z5_DISTRIBUTION stage={stage} first_trial={trial} first_set={} first_column={column} rank={rank} count={count}",if set==0{"random"}else{"consecutive"});
    }
    if let Some((ordinal,candidate))=first {
        println!("Z5_FIRST ordinal={ordinal} tau={:?} sigma={:?}",candidate.tau,candidate.sigma);
        let mut values=candidate.tau.to_vec();values.extend(candidate.sigma.iter().flatten());
        std::fs::write(arg("--candidate-out").unwrap_or_else(||"first-candidate.txt".into()),values.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(",")+"\n").unwrap();
    }
    println!("Z5_SEARCH_DONE checked={checked} passed={passed} failures={failures} wall_seconds={:.3}",start.elapsed().as_secs_f64());
}
pub(super) fn gate() {
    let path=arg("--candidate").expect("--candidate required");
    let v:Vec<usize>=std::fs::read_to_string(path).unwrap().trim().split(',').map(|s|s.parse().unwrap()).collect();
    assert_eq!(v.len(),25);
    let c=Candidate{tau:std::array::from_fn(|i|v[i]),sigma:std::array::from_fn(|i|std::array::from_fn(|j|v[5+4*i+j]))};
    let mut t=c.tau;t.sort();assert_eq!(t,[0,1,2,3,4]);
    for s in c.sigma {let mut s=s;s.sort();assert_eq!(s,[0,1,2,3]);}
    SELECTED.set(c.map()).unwrap();
    println!("Z5_GATE tau={:?} sigma={:?} generic_trials=20 targets=100 fourth_claim_all_lanes=true",c.tau,c.sigma);
    if !std::env::args().any(|x|x=="--preflight") {
        for trial in 0..20 {
            let (a,z,qs)=challenge(trial);
            let tables=[Tables::new(&a,&z,&qs),Tables::new(&a,&z,&(0..22).collect::<Vec<_>>())];
            for (name,pi) in [("identity",std::array::from_fn(|r|r as u16)),("D13",r0::transport::ROW_TO_COEFFICIENT)] {
                report_full(&format!("control_{name}_trial_{trial}"),&pi,&tables);
            }
        }
    }
    z4c_main();
}

//! Z6: the original (eta-free) terminal at every Boolean row, with and without
//! eligible noise. Reuses Z4c's witnesses, challenge replay and tape draws.
//! No elimination routine is used or changed.
use super::*;
use aspis_statement::pool_v1::{
    pair_forest_hiding::{
        pool_v1_pair_forest_copy_active_row_masks_v1,
        pool_v1_pair_forest_relation_free_mask_cells_v1,
    },
    pair_forest_trace::build_pool_v1_pair_forest_copy_registry_v1,
    pair_trace::PoolV1PairTupleLimbV1,
};
use std::fmt::Write as _;

const MASTER: u64 = 0x5348f0b9a87835d0;
const THREADS: usize = 8;

fn bits(b: usize) -> [QM31; 10] {
    std::array::from_fn(|i| q(((b >> (9 - i)) & 1) as u32))
}
fn lane(c: usize) -> usize {
    if c == 16 { 26 } else { c }
}
/// Boolean-row claims: z at b, succ at b+1 (mod 1024), xor12 at b^12.
fn row_claims(t: &Trace, b: usize) -> [[QM31; 29]; 3] {
    let mut out = [[QM31::ZERO; 29]; 3];
    for c in 0..17 {
        out[0][lane(c)] = t[c][b];
        out[1][lane(c)] = t[c][(b + 1) % N];
        out[2][lane(c)] = t[c][b ^ 12];
    }
    out
}
fn term(public: Public<'_>, t: &Trace, ch: &Challenges, b: usize) -> Result<QM31, ()> {
    public.terminal_qm31(&row_claims(t, b), &bits(b), ch).map_err(|_| ())
}
fn rows_subset(public: Public<'_>, t: &Trace, ch: &Challenges, rows: &[usize]) -> Vec<Result<QM31, ()>> {
    let chunk = rows.len().div_ceil(THREADS).max(1);
    std::thread::scope(|s| {
        let hs: Vec<_> = rows
            .chunks(chunk)
            .map(|part| s.spawn(move || part.iter().map(|&b| term(public, t, ch, b)).collect::<Vec<_>>()))
            .collect();
        hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
    })
}
fn all_rows(public: Public<'_>, t: &Trace, ch: &Challenges) -> Vec<QM31> {
    let rows: Vec<usize> = (0..N).collect();
    rows_subset(public, t, ch, &rows).into_iter().map(|x| x.expect("honest terminal error")).collect()
}
fn total(v: &[QM31]) -> QM31 {
    v.iter().fold(QM31::ZERO, |s, x| s.add(*x))
}
fn l(x: QM31) -> [u32; 4] {
    limbs(x).map(|v| v.0)
}
fn fnv(v: &[QM31]) -> u64 {
    let mut h = 0xcbf2_9ce4_8422_2325u64;
    for x in v {
        for limb in l(*x) {
            for byte in limb.to_le_bytes() {
                h ^= byte as u64;
                h = h.wrapping_mul(0x100_0000_01b3);
            }
        }
    }
    h
}
/// Lean `balance`: overwrite `dep` with minus the sum over copyInactiveRows \ {dep}.
fn balance(col: &mut [QM31], dep: usize) {
    let sum = (0..N).filter(|&r| r != dep && inactive(r)).fold(QM31::ZERO, |s, r| s.add(col[r]));
    col[dep] = QM31::ZERO.sub(sum);
}
fn diff_report(label: &str, a: &[QM31], b: &[QM31]) -> (usize, String) {
    let rows: Vec<usize> = (0..N).filter(|&r| a[r] != b[r]).collect();
    let mut s = format!("{label} diff_count={} ", rows.len());
    if rows.len() <= 64 {
        write!(s, "rows={rows:?} values=[").unwrap();
        for (i, &r) in rows.iter().enumerate() {
            if i > 0 { s.push(','); }
            write!(s, "[{r},{:?},{:?}]", l(a[r]), l(b[r])).unwrap();
        }
        s.push_str("] ");
    } else {
        let mut m16 = [0usize; 16];
        let mut blk = [0usize; 64];
        for &r in &rows { m16[r % 16] += 1; blk[r / 16] += 1; }
        write!(s, "rows=omitted hist_mod16={m16:?} hist_block={blk:?} ").unwrap();
    }
    let (sa, sb) = (total(a), total(b));
    write!(s, "sum_a={:?} sum_b={:?} sum_diff={:?} hash_a={:#018x} hash_b={:#018x}", l(sa), l(sb), l(sb.sub(sa)), fnv(a), fnv(b)).unwrap();
    (rows.len(), s)
}

fn structural_checks() -> Vec<(usize, usize)> {
    assert_eq!(pool_v1_pair_forest_copy_active_row_masks_v1().unwrap(), ACTIVE);
    let cells = pool_v1_pair_forest_relation_free_mask_cells_v1().unwrap();
    let mut list = vec![];
    let mut on_active = vec![];
    for c in 0..16 {
        for r in 0..N {
            let e = eligible(c, r);
            assert_eq!(e, cells.iter().any(|x| x.column as usize == c && x.row as usize == r));
            if e {
                if !inactive(r) { on_active.push((c, r)); }
                list.push((c, r));
            }
        }
    }
    assert!(inactive(1023));
    let reg = build_pool_v1_pair_forest_copy_registry_v1().unwrap();
    let (mut tuples, mut read) = (0, 0);
    for link in &reg {
        for t in [link.producer, link.consumer] {
            tuples += 1;
            assert!(!inactive(t.row as usize));
            for limb in t.limbs {
                if let PoolV1PairTupleLimbV1::Cell { source, .. } = limb {
                    let (r, c) = (source.cell.row as usize, source.cell.column as usize);
                    read += 1;
                    assert!(c < 16 && !inactive(r) && r != 1023 && !eligible(c, r), "helper reads ({c},{r})");
                }
            }
        }
    }
    let rows_per_col: Vec<usize> = (0..16).map(|c| list.iter().filter(|x| x.0 == c).count()).collect();
    println!("Z6_STRUCT eligible_cells={} per_column={rows_per_col:?} eligible_on_copy_active_rows={on_active:?} row1023_inactive=true eligible_1023_columns={:?} registry_links={} tuples={tuples} helper_cell_reads={read} helper_reads_only_active_noneligible_non1023=true inactive_rows={}",
        list.len(), (0..16).filter(|&c| eligible(c, 1023)).collect::<Vec<_>>(), reg.len(), (0..N).filter(|&r| inactive(r)).count());
    list
}

struct Trial {
    a: [QM31; 10],
    ch: Challenges,
    tapes: Vec<Trace>,
}
/// Exact replay of z4c_main's RNG consumption (challenges, then five tapes).
fn trial(trial: usize, print: bool) -> Trial {
    let trial_seed = MASTER.wrapping_add((trial as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15));
    let mut rng = Rng(trial_seed);
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()), circle(rng.q())];
    let sets = query_sets(&mut rng);
    let ch = Challenges {
        lambda: rng.q(),
        chi: rng.q(),
        theta: rng.q(),
        zc: std::array::from_fn(|_| rng.q()),
        mu: rng.q(),
        eta: rng.q(),
    };
    if print { println!("TRIAL_SEED trial={trial} seed={trial_seed:#x}");
    println!("CHALLENGE trial={trial} alpha={a:?} semantic={ch:?} circle={z:?} queries={:?}", sets[0].1); }
    let tapes = (0..5)
        .map(|_| {
            (0..17)
                .map(|c| {
                    (0..N)
                        .map(|r| {
                            if c < 16 && eligible(c, r) {
                                QM31::from_m31(rng.m())
                            } else if c == 16 && inactive(r) {
                                rng.q()
                            } else {
                                QM31::ZERO
                            }
                        })
                        .collect()
                })
                .collect()
        })
        .collect();
    Trial { a, ch, tapes }
}

/// Part 3: perturb one cell (no balance) and record which Boolean rows change.
fn cell_rows(public: Public<'_>, base: &Trace, ch: &Challenges, c: usize, r: usize, deltas: &[QM31]) -> Vec<usize> {
    let mut readers = vec![r, (r + N - 1) % N, r ^ 12];
    readers.sort_unstable();
    readers.dedup();
    let before = rows_subset(public, base, ch, &readers);
    assert!(before.iter().all(|x| x.is_ok()), "terminal error before c={c} r={r}");
    let mut changed = vec![];
    for d in deltas {
        let mut t = base.clone();
        t[c][r] = t[c][r].add(*d);
        let after = rows_subset(public, &t, ch, &readers);
        assert!(after.iter().all(|x| x.is_ok()), "terminal error after c={c} r={r}");
        for (i, &b) in readers.iter().enumerate() {
            if before[i] != after[i] && !changed.contains(&b) {
                changed.push(b);
            }
        }
    }
    changed.sort_unstable();
    changed
}

pub(super) fn main() {
    let start = Instant::now();
    let preflight = std::env::args().any(|x| x == "--preflight");
    let trials = if preflight { 1 } else { 20 };
    let elig = structural_checks();
    let (pubdata, instances) = real::instances();
    for tr in 0..trials {
        let t0 = Instant::now();
        let Trial { a, ch, tapes } = trial(tr, true);
        assert!(a.iter().all(|x| *x != QM31::ZERO && *x != QM31::ONE));
        // (C) raw semantic C1 + helper; (A) = Lean prepare(applyEligible t 0).
        let mut raws = vec![];
        let mut preps = vec![];
        for (w, inst) in instances.iter().enumerate() {
            let mut t: Trace = inst.compilation.semantic_c1.c1.iter()
                .map(|col| col.iter().map(|x| QM31::from_m31(*x)).collect()).collect();
            let h = build_pool_v1_pair_forest_copy_helper_v1(
                &inst.compilation.trace,
                inst.compilation.public_statement.live_snapshot.next_pair_index,
                ch.lambda, ch.chi).expect("helper");
            let nz_inactive = (0..N).filter(|&r| inactive(r) && h[r] != QM31::ZERO).count();
            t.push(h);
            let mut p = t.clone();
            for c in 0..16 { balance(&mut p[c], 1023); }
            // Z4c's trace applies balance_trace also to H1 (dep row 0).
            let mut z4c = t.clone();
            balance_trace(&mut z4c);
            let changed_1023: Vec<usize> = (0..16).filter(|&c| p[c][1023] != t[c][1023]).collect();
            let other_changed = (0..16).any(|c| (0..1023).any(|r| p[c][r] != t[c][r]));
            println!("Z6_PREP trial={tr} witness={w} helper_nonzero_inactive_rows={nz_inactive} balance_changes_row1023_columns={changed_1023:?} balance_changes_other_rows={other_changed} lean_A_equals_z4c_trace={}", p == z4c);
            raws.push(t);
            preps.push(p);
        }
        if tr == 0 {
            // Boolean-row claims equal the eq-weighted claims at the Boolean point.
            for &b in &[0usize, 12, 13, 15, 911, 1007, 1011, 1022, 1023] {
                assert_eq!(row_claims(&preps[0], b), point_claims(&preps[0], &bits(b)), "row claims b={b}");
            }
            println!("Z6_PREFLIGHT row_claims_match_point_claims=true rows=[0,12,13,15,911,1007,1011,1022,1023]");
        }
        for (k, tape) in tapes.iter().enumerate() {
            let mut e = tape.clone();
            e[16] = vec![QM31::ZERO; N];
            let mut pad = vec![QM31::ZERO; N];
            pad.copy_from_slice(&tape[16]);
            balance(&mut pad, 0);
            let cells = (0..16).map(|c| (0..N).filter(|&r| e[c][r] != QM31::ZERO).count()).sum::<usize>();
            println!("Z6_TAPE trial={tr} tape={k} eligible_nonzero_cells={cells} hash_eligible={:#018x} hash_h1pad={:#018x}",
                fnv(&e[..16].concat()), fnv(&pad));
        }
        let mut done = 0;
        for w in 0..10 {
            let public = Public::Transfer(&pubdata, &instances[w].compilation.public_statement);
            let va = all_rows(public, &preps[w], &ch);
            let vc = all_rows(public, &raws[w], &ch);
            let (_, s) = diff_report(&format!("Z6_AC trial={tr} witness={w}"), &vc, &va);
            println!("{s}");
            if tr == 0 && w == 0 {
                println!("Z6_FULL_A trial=0 witness=0 values={:?}", va.iter().map(|x| l(*x)).collect::<Vec<_>>());
            }
            for (k, tape) in tapes.iter().enumerate() {
                // (B) Lean actual(0,n): balance1023(t + eligible noise); helper invariant (Z6_STRUCT).
                let mut tb = raws[w].clone();
                for c in 0..16 {
                    for r in 0..N {
                        if eligible(c, r) { tb[c][r] = tb[c][r].add(tape[c][r]); }
                    }
                    balance(&mut tb[c], 1023);
                }
                let vb = all_rows(public, &tb, &ch);
                let (_, s) = diff_report(&format!("Z6_AB trial={tr} witness={w} tape={k} own_pair={}", k == w / 2), &va, &vb);
                println!("{s}");
                // Supplementary: Z4c's full tape including its H1 padding (Lean affine tape lane 1).
                let mut tp = tb.clone();
                let mut pad = tape[16].clone();
                balance(&mut pad, 0);
                for r in 0..N { tp[16][r] = tp[16][r].add(pad[r]); }
                let vp = all_rows(public, &tp, &ch);
                let mm = ch.mu.add(ch.mu.mul(ch.mu));
                let formula = (0..N).all(|b| vp[b].sub(va[b]) == mm.mul(pad[b]));
                let pad_rows = (0..N).filter(|&b| pad[b] != QM31::ZERO).count();
                let (_, s) = diff_report(&format!("Z6_APAD trial={tr} witness={w} tape={k} own_pair={} diff_equals_mu_plus_mu2_times_pad={formula} pad_nonzero_rows={pad_rows}", k == w / 2), &va, &vp);
                println!("{s}");
                done += 1;
            }
        }
        println!("Z6_TRIAL_DONE trial={tr} combos={done} wall_seconds={:.3}", t0.elapsed().as_secs_f64());
        if tr == 0 {
            // Part 3 on trial 0 challenges (and trial 1 for the random base).
            let public = Public::Transfer(&pubdata, &instances[0].compilation.public_statement);
            let mut rng = Rng(0x2636_5a7e_2026_1011);
            let deltas: Vec<QM31> = (0..2).map(|_| QM31::from_m31(rng.m())).collect();
            let mut random: Trace = (0..16).map(|_| (0..N).map(|_| QM31::from_m31(rng.m())).collect()).collect();
            random.push(preps[0][16].clone());
            let ch1 = trial(1, false).ch;
            let mut summary: std::collections::BTreeMap<String, usize> = Default::default();
            let mut sel = elig.clone();
            for c in 0..16 { if !sel.contains(&(c, 1023)) { sel.push((c, 1023)); } }
            for &(c, r) in &sel {
                let h = cell_rows(public, &preps[0], &ch, c, r, &deltas);
                let x = cell_rows(public, &random, &ch, c, r, &deltas);
                let y = cell_rows(public, &random, &ch1, c, r, &deltas);
                let tag = if eligible(c, r) && r != 1023 { "eligible" } else { "row1023" };
                *summary.entry(format!("{tag} honest={h:?}_rel random={x:?}_rel", h = h.iter().map(|b| *b as i64 - r as i64).collect::<Vec<_>>(), x = x.iter().map(|b| *b as i64 - r as i64).collect::<Vec<_>>())).or_default() += 1;
                if !h.is_empty() || !x.is_empty() || !y.is_empty() || r == 1023 {
                    println!("Z6_CELL c={c} r={r} kind={tag} honest_trial0={h:?} random_trial0={x:?} random_trial1={y:?}");
                }
            }
            for (k, v) in summary { println!("Z6_CELL_CLASS {k} count={v}"); }
            println!("Z6_CELL_DONE cells={} deltas=2 bases=honest_w0_t0,random_t0,random_t1", sel.len());
        }
        if preflight { println!("Z6_PREFLIGHT_DONE"); }
    }
    println!("Z6_DONE trials={trials} wall_seconds={:.3}", start.elapsed().as_secs_f64());
}

//! Z7 (LOG D20): alpha-structure probe. Exact M31/QM31 arithmetic only.
//!
//! Every rank/elimination routine is Z4c's, called unchanged from the parent
//! module (`Ech`, `lane_eliminate`, `compensated_rows`, `pure_c`, `full_c`,
//! `copied_ech`, `initial_zero`, `summarize`, `raw_c`, `tail_row`, `round_row`,
//! `compute_targets`, `normalized`, `normalize_d`, `final_value`). The challenge
//! and tape replay below is z6.rs's `trial` (itself z4c_main's RNG order) with
//! `z` and the query set also returned. `pure_h` is `pure_c`'s body copied
//! verbatim except for one row filter on the mask-only lanes (structure H).
//! `round_polys` is `last_coeff`'s chain reconstruction, returning every round.
use super::*;

const MASTER: u64 = 0x5348f0b9a87835d0;
const STRUCT_SEED: u64 = 0x5a37_d20a_2026_1013;
const STRUCTURES: [&str; 8] = ["A", "B", "C", "D", "E", "F", "G", "H"];

struct Trial {
    a: [QM31; 10],
    z: [Point<QM31>; 2],
    qs: Vec<usize>,
    ch: Challenges,
    tapes: Vec<Trace>,
}
/// Exact replay of z4c_main's RNG consumption (challenges, then five tapes).
fn trial(trial: usize) -> Trial {
    let trial_seed = MASTER.wrapping_add((trial as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15));
    let mut rng = Rng(trial_seed);
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()), circle(rng.q())];
    let sets = query_sets(&mut rng);
    let ch = Challenges {
        lambda: rng.q(),
        chi: rng.q(),
        theta: rng.q(),
        zc: std::array::from_fn(|_| rng.q()),
        mu: rng.q(),
        eta: rng.q(),
    };
    println!("TRIAL_SEED trial={trial} seed={trial_seed:#x}");
    println!("CHALLENGE trial={trial} alpha={a:?} semantic={ch:?} circle={z:?} queries={:?}", sets[0].1);
    let tapes = (0..5)
        .map(|_| {
            (0..17)
                .map(|c| {
                    (0..N)
                        .map(|r| {
                            if c < 16 && eligible(c, r) {
                                QM31::from_m31(rng.m())
                            } else if c == 16 && inactive(r) {
                                rng.q()
                            } else {
                                QM31::ZERO
                            }
                        })
                        .collect()
                })
                .collect()
        })
        .collect();
    Trial { a, z, qs: sets[0].1.clone(), ch, tapes }
}

fn l4(x: QM31) -> [u32; 4] {
    limbs(x).map(|v| v.0)
}
fn unflat(v: &[M31]) -> Vec<QM31> {
    v.chunks(4)
        .map(|c| QM31 { c0: CM31::new(c[0], c[1]), c1: CM31::new(c[2], c[3]) })
        .collect()
}
fn f_rank(xs: &[QM31]) -> usize {
    let mut e = Ech::new(4);
    for x in xs {
        e.insert(limbs(*x).to_vec());
    }
    e.rank
}
fn half() -> QM31 {
    QM31::from_m31(M31(2).inv())
}
fn admissible(a: &[QM31; 10]) -> bool {
    a.iter().all(|x| *x != QM31::ZERO && *x != QM31::ONE) && a[9] != half()
}
fn f_elem(rng: &mut Rng) -> QM31 {
    QM31::from_m31(rng.m())
}
/// Random element of F \ {0,1} (and != 1/2 when `last`).
fn f_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = f_elem(rng);
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
/// Random element of W = span_F{1,x,y} outside {0,1}.
fn w_elem(rng: &mut Rng, w: &[QM31; 3]) -> QM31 {
    loop {
        let v = w[0].mul(f_elem(rng)).add(w[1].mul(f_elem(rng))).add(w[2].mul(f_elem(rng)));
        if v != QM31::ZERO && v != QM31::ONE {
            return v;
        }
    }
}
/// Alpha for a structure. Z4c's uniform coordinates are kept wherever the
/// structure leaves a coordinate uniform in K; structured ones come from a
/// separate per-(structure,vector) stream, so the Z4c stream is untouched.
fn alpha_for(s: &str, v: usize, base: &[QM31; 10]) -> ([QM31; 10], Option<[QM31; 3]>) {
    let si = STRUCTURES.iter().position(|x| *x == s).unwrap() as u64;
    let mut rng = Rng(STRUCT_SEED.wrapping_add((si * 64 + v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let mut a = *base;
    let mut w = None;
    match s {
        "A" | "H" => {}
        "B" => {
            for i in 0..10 {
                a[i] = f_nontrivial(&mut rng, i == 9);
            }
        }
        "C" | "D" | "E" => {
            let basis = loop {
                let b = [QM31::ONE, rng.q(), rng.q()];
                if f_rank(&b) == 3 {
                    break b;
                }
            };
            let k = match s { "C" => 5, "D" => 6, _ => 7 };
            for i in 0..k {
                a[i] = w_elem(&mut rng, &basis);
            }
            w = Some(basis);
        }
        "F" => loop {
            let x = QM31::ONE.mul(f_elem(&mut rng)).add(a[0].mul(f_elem(&mut rng)));
            if x != QM31::ZERO && x != QM31::ONE {
                a[1] = x;
                break;
            }
        },
        "G" => {
            for i in 5..10 {
                a[i] = f_nontrivial(&mut rng, i == 9);
            }
        }
        _ => panic!("unknown structure {s}"),
    }
    assert!(admissible(&a), "alpha admissibility");
    (a, w)
}

/// `last_coeff`'s chain reconstruction, returning all ten 28-coefficient polys.
fn round_polys(v: &[QM31], a: &[QM31; 10]) -> Vec<[QM31; 28]> {
    let mut prev = v[0];
    let mut out = vec![];
    for j in 0..10 {
        let mut co = [QM31::ZERO; 28];
        co[0] = v[1 + 27 * j];
        co[2..].copy_from_slice(&v[2 + 27 * j..28 + 27 * j]);
        co[1] = prev
            .sub(co[0].add(co[0]))
            .sub(co[2..].iter().fold(QM31::ZERO, |v, x| v.add(*x)));
        prev = co.iter().rev().fold(QM31::ZERO, |v, x| v.mul(a[j]).add(*x));
        out.push(co);
    }
    out
}
/// Per-round F-ranks: full 28-coefficient projection (max 112) and per tower
/// limb k (max 28), from a list of spanning vectors.
struct Proj {
    full: Vec<Ech<M31>>,
    limb: Vec<Vec<Ech<M31>>>,
}
impl Proj {
    fn new() -> Self {
        Proj {
            full: (0..10).map(|_| Ech::new(112)).collect(),
            limb: (0..10).map(|_| (0..4).map(|_| Ech::new(28)).collect()).collect(),
        }
    }
    fn add_poly(&mut self, j: usize, co: &[QM31; 28]) {
        self.full[j].insert(flatten(co));
        for k in 0..4 {
            self.limb[j][k].insert(co.iter().map(|x| limbs(*x)[k]).collect());
        }
    }
    fn add(&mut self, v: &[QM31], a: &[QM31; 10]) {
        for (j, co) in round_polys(v, a).iter().enumerate() {
            self.add_poly(j, co);
        }
    }
    fn of_ech(e: &Ech<M31>, a: &[QM31; 10]) -> Self {
        let mut p = Proj::new();
        for b in e.p.iter().flatten() {
            p.add(&unflat(b), a);
        }
        p
    }
    fn full_ranks(&self) -> Vec<usize> {
        self.full.iter().map(|e| e.rank).collect()
    }
    fn limb_ranks(&self) -> Vec<[usize; 4]> {
        self.limb.iter().map(|l| std::array::from_fn(|k| l[k].rank)).collect()
    }
}
/// Leading-degree pivots of an F-subspace of K[X]_{<=27}: coordinates ordered
/// (degree descending, limb ascending); returns per degree the number of
/// pivots (F-dimension of leading coefficients at that degree).
fn leading(polys: &[[QM31; 28]]) -> [usize; 28] {
    let mut e = Ech::new(112);
    let mut counts = [0usize; 28];
    for co in polys {
        let v: Vec<M31> = (0..28).rev().flat_map(|d| limbs(co[d])).collect();
        if let Some(i) = e.insert(v) {
            counts[27 - i / 4] += 1;
        }
    }
    counts
}
fn degree_set(c: &[usize; 28]) -> String {
    let d: Vec<usize> = (0..28).filter(|&d| c[d] > 0).collect();
    format!("{d:?}")
}

/// Lane generators of the unconstrained image: F-span for mask-only lanes
/// 0..9, K-span for G (c=10) and for D's own word (tail rows).
fn lane_generators(a: &[QM31; 10], tail: &[Vec<QM31>], lane: usize, rows: &[usize]) -> Vec<Vec<QM31>> {
    let mut out = vec![];
    for &r in rows {
        if lane < 10 {
            out.push(round_row(a, r, lane));
        } else {
            let v = if lane == 10 { round_row(a, r, 10) } else { tail[r].clone() };
            for k in 0..4 {
                out.push(v.iter().map(|x| x.mul(tower(k))).collect());
            }
        }
    }
    out
}

/// `pure_c` (libra=true) with mask-only lanes restricted to `keep` rows.
/// Copied from pure_c verbatim; the only change is the row filter on br/rr.
fn pure_h(
    a: &[QM31; 10],
    br: &[Vec<M31>],
    gr: &[Vec<QM31>],
    tail: &[Vec<QM31>],
    keep: &dyn Fn(usize) -> bool,
) -> Ech<M31> {
    let libra = true;
    let mut image = Ech::new(1084);
    let cols: Vec<_> = (0..11).collect();
    for (position, c) in cols.into_iter().enumerate() {
        let lane = if c == 10 { 27 } else { 16 + position };
        let rr = compensated_rows(a, Some(c), lane, tail, libra);
        if c == 10 {
            lane_eliminate(gr, &rr, &[], true, &mut image);
        } else {
            let rows: Vec<usize> = (0..N).filter(|&r| keep(r)).collect();
            let brs: Vec<Vec<M31>> = rows.iter().map(|&r| br[r].clone()).collect();
            let rrs: Vec<Vec<QM31>> = rows.iter().map(|&r| rr[r].clone()).collect();
            lane_eliminate(&brs, &rrs, &[], false, &mut image);
        }
    }
    image
}

fn tail_sum_counts() -> Vec<usize> {
    (0..10)
        .map(|j| {
            let w: Vec<u64> = (j + 1..10).map(|i| 3 + 22 * i as u64).collect();
            let mut s = std::collections::BTreeSet::new();
            for m in 0..1u64 << w.len() {
                s.insert((0..w.len()).filter(|&b| m >> b & 1 == 1).map(|b| w[b]).sum::<u64>());
            }
            s.len()
        })
        .collect()
}
fn lambda_dims(a: &[QM31; 10]) -> (Vec<usize>, Vec<usize>) {
    // Lambda_j = span_F{eqPrefix(alpha, l) : l in {0,1}^j}; S_j = span_F{1, alpha_0..alpha_{j-1}}.
    let mut lam = vec![];
    let mut spans = vec![];
    for j in 0..10 {
        let mut e = Ech::new(4);
        for l in 0..1usize << j {
            let x = (0..j).fold(QM31::ONE, |v, i| {
                v.mul(if l >> i & 1 == 1 { a[i] } else { QM31::ONE.sub(a[i]) })
            });
            e.insert(limbs(x).to_vec());
        }
        lam.push(e.rank);
        let mut s = vec![QM31::ONE];
        s.extend_from_slice(&a[..j]);
        spans.push(f_rank(&s));
    }
    (lam, spans)
}

fn report(label: &str, kind: &str, total: usize, p: &Proj) {
    println!(
        "Z7_RANKS {label} kind={kind} total={total} round_full={:?} round_limb={:?}",
        p.full_ranks(),
        p.limb_ranks()
    );
}

pub(super) fn main() {
    let args: Vec<_> = std::env::args().collect();
    let get = |k: &str| args.windows(2).find(|x| x[0] == k).map(|x| x[1].clone());
    let s = get("--structure").expect("--structure");
    let v: usize = get("--vector").expect("--vector").parse().unwrap();
    let preflight = args.iter().any(|x| x == "--preflight");
    let start = Instant::now();
    println!("Z7_START structure={s} vector={v} preflight={preflight} transport=D13 libra=true gamma=7");
    println!("Z7_TAILSUMS w=3+22i counts={:?}", tail_sum_counts());
    let t = trial(v);
    let (a, w) = alpha_for(&s, v, &t.a);
    let label = format!("structure={s} vector={v}");
    let (lam, spans) = lambda_dims(&a);
    println!(
        "Z7_ALPHA {label} alpha={:?} w_basis={:?} f_coordinates={:?} lambda_dims={lam:?} span_dims={spans:?} alpha9_half={}",
        a.map(l4),
        w.map(|b| b.map(l4)),
        (0..10).filter(|&i| limbs(a[i])[1..] == [M31::ZERO; 3]).collect::<Vec<_>>(),
        a[9] == half()
    );
    let (br, gr) = raw_c(&a, &t.z, &t.qs);
    let tail: Vec<_> = (0..N).map(|r| tail_row(&a, r)).collect();

    if s == "H" {
        // Round-j matrix: mask-only words restricted to rows whose prefix
        // coordinates r_0..r_{j-1} (round_row bit 9-i) are all zero.
        let mut silent_j = vec![];
        let mut unc_j = vec![];
        let mut silent_limb = vec![];
        let mut unc_limb = vec![];
        let mut totals = vec![];
        for j in 0..10 {
            let keep = move |r: usize| (r >> (10 - j)) == 0;
            let pure = pure_h(&a, &br, &gr, &tail, &keep);
            let silent = initial_zero(copied_ech(&pure));
            let ps = Proj::of_ech(&silent, &a);
            silent_j.push(ps.full_ranks()[j]);
            silent_limb.push(ps.limb_ranks()[j]);
            totals.push((silent.rank, pure.rank));
            let mut pu = Proj::new();
            let rows: Vec<usize> = (0..N).filter(|&r| keep(r)).collect();
            let all: Vec<usize> = (0..N).collect();
            for lane in 0..12 {
                let rs = if lane < 10 { &rows } else { &all };
                for g in lane_generators(&a, &tail, lane, rs) {
                    pu.add_poly(j, &round_polys(&g, &a)[j]);
                }
            }
            unc_j.push(pu.full_ranks()[j]);
            unc_limb.push(pu.limb_ranks()[j]);
            println!("Z7_H_PROGRESS {label} round={j} rows_per_mask_lane={} silent_total={} initial_retained_total={}", rows.len(), silent.rank, pure.rank);
        }
        println!("Z7_RANKS {label} kind=silent_H total_per_round_matrix={:?} round_full={silent_j:?} round_limb={silent_limb:?}", totals.iter().map(|x| x.0).collect::<Vec<_>>());
        println!("Z7_RANKS {label} kind=unconstrained_H round_full={unc_j:?} round_limb={unc_limb:?}");
        println!("Z7_TARGETS {label} computed=false reason=H_round_matrices_are_not_one_image_ranks_only");
        println!("Z7_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
        return;
    }

    let pure = pure_c(&a, &br, &gr, &tail, true);
    let silent = initial_zero(copied_ech(&pure));
    report(&label, "silent", silent.rank, &Proj::of_ech(&silent, &a));
    report(&label, "silent_initial_retained", pure.rank, &Proj::of_ech(&pure, &a));
    // Unconstrained pure image: every lane word free (mask-only F, G and D K).
    let all: Vec<usize> = (0..N).collect();
    let mut unc = Ech::new(1084);
    let mut unc_p = Proj::new();
    let mut lane_unc: Vec<Vec<Vec<[QM31; 28]>>> = vec![vec![vec![]; 10]; 12];
    for lane in 0..12 {
        for g in lane_generators(&a, &tail, lane, &all) {
            let polys = round_polys(&g, &a);
            for j in 0..10 {
                unc_p.add_poly(j, &polys[j]);
                if s == "A" && (5..8).contains(&j) {
                    lane_unc[lane][j].push(polys[j]);
                }
            }
            if unc.rank < 1084 {
                unc.insert(flatten(&g));
            }
        }
    }
    report(&label, "unconstrained", unc.rank, &unc_p);
    if s == "A" {
        assert_eq!(silent.rank, 1076, "stop rule: structure A silent rank");
        // Per-lane leading-degree pivots at rounds 5-7. Silent: each lane's own
        // lane_eliminate image (with its D compensation, initial retained).
        for lane in 0..12 {
            let name = match lane { 10 => "G".to_string(), 11 => "D".to_string(), c => format!("mask{c}_e{}", EXP[c]) };
            let mut own = Ech::new(1084);
            if lane < 11 {
                let lid = if lane == 10 { 27 } else { 16 + lane };
                let rr = compensated_rows(&a, Some(lane), lid, &tail, true);
                if lane == 10 {
                    lane_eliminate(&gr, &rr, &[], true, &mut own);
                } else {
                    lane_eliminate(&br, &rr, &[], false, &mut own);
                }
            }
            let own_polys: Vec<Vec<[QM31; 28]>> = {
                let mut x = vec![vec![]; 10];
                for b in own.p.iter().flatten() {
                    let ps = round_polys(&unflat(b), &a);
                    for j in 5..8 {
                        x[j].push(ps[j]);
                    }
                }
                x
            };
            for j in 5..8 {
                let cu = leading(&lane_unc[lane][j]);
                println!("Z7_PIVOTS {label} lane={name} round={j} kind=unconstrained degrees={} per_degree_dims={cu:?}", degree_set(&cu));
                if lane < 11 {
                    let cs = leading(&own_polys[j]);
                    println!("Z7_PIVOTS {label} lane={name} round={j} kind=silent_lane_own degrees={} per_degree_dims={cs:?} lane_rank={}", degree_set(&cs), own.rank);
                }
            }
        }
    }
    if preflight {
        println!("Z7_PREFLIGHT_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
        return;
    }
    // Chain0 basis: initial 0 and terminal value 0 (stored coordinates);
    // normalized units span the 1,076-dimensional upper-bound space.
    let chain0: Vec<Vec<M31>> = (4..1084)
        .map(|i| {
            let mut u = vec![M31::ZERO; 1084];
            u[i] = M31::ONE;
            let q = unflat(&u);
            let phi = final_value(&q, &a);
            flatten(&normalize_d(&q, phi, &a).expect("alpha9=1/2"))
        })
        .collect();
    summarize(&format!("{label} chain0_basis"), &silent, &chain0);
    // Z4c's honest targets (i', derivative diagnostic, ii') at this alpha.
    let (pubdata, instances) = real::instances();
    let ch = t.ch;
    let traces: Vec<Trace> = instances
        .iter()
        .map(|w| {
            let mut tr: Trace = w
                .compilation
                .semantic_c1
                .c1
                .iter()
                .map(|col| col.iter().map(|x| QM31::from_m31(*x)).collect())
                .collect();
            match build_pool_v1_pair_forest_copy_helper_v1(
                &w.compilation.trace,
                w.compilation.public_statement.live_snapshot.next_pair_index,
                ch.lambda,
                ch.chi,
            ) {
                Ok(h) => tr.push(h),
                Err(error) => {
                    println!("STOP reason=helper_pole_or_helper_abort {label} error={error:?}");
                    std::process::exit(22);
                }
            }
            balance_trace(&mut tr);
            tr
        })
        .collect();
    let mut targets = vec![];
    for pair in 0..5 {
        let mut noise = t.tapes[pair].clone();
        balance_trace(&mut noise);
        let public = Public::Transfer(&pubdata, &instances[2 * pair].compilation.public_statement);
        let original = compute_targets(public, &a, &ch, &traces[2 * pair], &traces[2 * pair + 1], &noise, pair);
        println!(
            "Z7_TERMINAL {label} pair={pair} pinned={:?} derivative={:?} ii={:?}",
            l4(original.terminal[0]),
            l4(original.terminal[1]),
            l4(original.terminal[2])
        );
        targets.push(normalized(&original, &a, &traces[2 * pair], &traces[2 * pair + 1], &ch, public));
    }
    let i: Vec<_> = targets.iter().map(|t| flatten(&t.pinned)).collect();
    let derivative: Vec<_> = targets.iter().map(|t| flatten(&t.derivative)).collect();
    let (full, ii) = full_c(&a, &br, &gr, &tail, &traces, &targets, &pure, true);
    summarize(&format!("{label} libra_i_prime"), &silent, &i);
    summarize(&format!("{label} libra_derivative_diagnostic"), &silent, &derivative);
    summarize(&format!("{label} libra_ii_prime"), &full, &ii);
    println!(
        "Z7_GATE {label} silent_rank={} initial_retained_rank={} full_conditioned_rank={} i_pass={} ii_pass={} attempted=5",
        silent.rank,
        pure.rank,
        full.rank,
        pass_count(&silent, &i),
        pass_count(&full, &ii)
    );
    println!("Z7_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
}

//! Z8 (LOG D20′.2 / D20″ "Z8"): the silent-rank gate with the proved
//! protocol's WideExact-batched opening payload (R0Z/HonestView.lean
//! `linearPayload`, lines 191–220). Exact M31/QM31/WideExact arithmetic.
//!
//! Silence = every non-semantic payload coordinate is zero:
//!   per lane (Z4c's raw_c rows minus its per-lane inactive entry):
//!     .pointClaim j c (3), .extraClaim c, .ood j c (2), .opened q s c (88);
//!   batched over the 29 lanes with gamma = ch.opening 0 in WideExact:
//!     .inactiveSum   = sum_c gamma^c sum_{inactive rows} t_c,
//!     .openingCoeff i = coefficient i of relationLinear(openingWeights)(batch),
//!     .finalCoeff d   = foldLinear(ch.opening 3)(batch)[d],
//!   batch = sum_c gamma^c quotientLinear(z0,z1)(coeffs_pi(t_c)).
//! Each WideExact value is eliminated over M31 as its 8 canonical limbs.
//! No zero-batched-word proxy and no D-lift: D (lane 28) is an ordinary
//! K4-valued lane with its own word, observations and Libra round tail.
//!
//! Opening-layer functions are aspis-core's R0 code, applied column-wise to
//! coefficient unit vectors (all are linear): `prover::quotient` (chord
//! quotient, per lane with that lane's two OOD values), `chord::quotient_weights`
//! + `FunctionalWeights::{e1,e2}` (Lean `totalWeights`), `prover::round_polynomial`
//! (Lean `relationLinear`), `fold::fold_message` (Lean `foldLinear`). The Rust
//! `OpeningData::weights` omits Lean's `kappa^4 • extraWeight` (libraWeight);
//! it is added here so the weights equal Lean's `weights`.
//!
//! Reused from probe.rs unchanged: Ech (and residual), summarize, raw_c,
//! tail_row, round_row, eq, points, h_weight, compute_targets, normalized,
//! normalize_d, final_value, balance_trace, real::instances, eligible,
//! inactive. Copied: z6/z7 `trial`, z7's alpha helpers, `round_polys`, `Proj`.
use super::*;
use aspis_core::field::WideExact as W;
use aspis_core::r0::{
    basis::{BasisSize, NaturalBasis},
    chord::{self, FunctionalWeights, Secant},
    encoder, fold, opening, prover,
    transport::ROW_TO_COEFFICIENT,
};

const MASTER: u64 = 0x5348f0b9a87835d0;
const STRUCT_SEED: u64 = 0x5a38_d20b_2026_1013;
const OPEN_SEED: u64 = 0x5a38_0be0_2026_1013;
const STRUCTURES: [&str; 4] = ["A", "B", "I", "J"];
const NB: usize = 264; // inactiveSum + 7 openingCoeff + 256 finalCoeff
const BW: usize = NB * 8; // batched M31 coordinates
const RW: usize = 1084; // round coordinates (Z4c layout)
const TW: usize = BW + RW;
const THREADS: usize = 4;

struct Trial {
    a: [QM31; 10],
    z: [Point<QM31>; 2],
    qs: Vec<usize>,
    ch: Challenges,
    tapes: Vec<Trace>,
}
/// Exact replay of z4c_main's RNG consumption (copied from z7.rs `trial`).
fn trial(trial: usize) -> Trial {
    let trial_seed = MASTER.wrapping_add((trial as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15));
    let mut rng = Rng(trial_seed);
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()), circle(rng.q())];
    let sets = query_sets(&mut rng);
    let ch = Challenges {
        lambda: rng.q(),
        chi: rng.q(),
        theta: rng.q(),
        zc: std::array::from_fn(|_| rng.q()),
        mu: rng.q(),
        eta: rng.q(),
    };
    println!("TRIAL_SEED trial={trial} seed={trial_seed:#x}");
    println!("CHALLENGE trial={trial} alpha={a:?} semantic={ch:?} circle={z:?} queries={:?}", sets[0].1);
    let tapes = (0..5)
        .map(|_| {
            (0..17)
                .map(|c| {
                    (0..N)
                        .map(|r| {
                            if c < 16 && eligible(c, r) {
                                QM31::from_m31(rng.m())
                            } else if c == 16 && inactive(r) {
                                rng.q()
                            } else {
                                QM31::ZERO
                            }
                        })
                        .collect()
                })
                .collect()
        })
        .collect();
    Trial { a, z, qs: sets[0].1.clone(), ch, tapes }
}

fn l4(x: QM31) -> [u32; 4] {
    limbs(x).map(|v| v.0)
}
fn unflat(v: &[M31]) -> Vec<QM31> {
    v.chunks(4)
        .map(|c| QM31 { c0: CM31::new(c[0], c[1]), c1: CM31::new(c[2], c[3]) })
        .collect()
}
fn half() -> QM31 {
    QM31::from_m31(M31(2).inv())
}
fn admissible(a: &[QM31; 10]) -> bool {
    a.iter().all(|x| *x != QM31::ZERO && *x != QM31::ONE) && a[9] != half()
}
fn f_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31::from_m31(rng.m());
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
fn k2_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31 { c0: CM31::new(rng.m(), rng.m()), c1: CM31::new(M31::ZERO, M31::ZERO) };
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
/// A: Z4c alpha. B: all alpha_i in F\{0,1}. I: all alpha_i in K2 = F(i)\{0,1}.
/// J: alpha_0 Z4c (uniform in QM31), alpha_1..6 in F\{0,1}, alpha_7..9 Z4c.
fn alpha_for(s: &str, v: usize, base: &[QM31; 10]) -> [QM31; 10] {
    let si = STRUCTURES.iter().position(|x| *x == s).unwrap() as u64;
    let mut rng = Rng(STRUCT_SEED.wrapping_add((si * 64 + v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let mut a = *base;
    match s {
        "A" => {}
        "B" => (0..10).for_each(|i| a[i] = f_nontrivial(&mut rng, i == 9)),
        "I" => (0..10).for_each(|i| a[i] = k2_nontrivial(&mut rng, i == 9)),
        "J" => (1..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        _ => panic!("unknown structure {s}"),
    }
    assert!(admissible(&a), "alpha admissibility");
    a
}
fn lambda_dims(a: &[QM31; 10]) -> Vec<usize> {
    (0..10)
        .map(|j| {
            let mut e = Ech::new(4);
            for l in 0..1usize << j {
                let x = (0..j).fold(QM31::ONE, |v, i| {
                    v.mul(if l >> i & 1 == 1 { a[i] } else { QM31::ONE.sub(a[i]) })
                });
                e.insert(limbs(x).to_vec());
            }
            e.rank
        })
        .collect()
}

/// `last_coeff`'s chain reconstruction, returning all ten polys (copied from z7.rs).
fn round_polys(v: &[QM31], a: &[QM31; 10]) -> Vec<[QM31; 28]> {
    let mut prev = v[0];
    let mut out = vec![];
    for j in 0..10 {
        let mut co = [QM31::ZERO; 28];
        co[0] = v[1 + 27 * j];
        co[2..].copy_from_slice(&v[2 + 27 * j..28 + 27 * j]);
        co[1] = prev
            .sub(co[0].add(co[0]))
            .sub(co[2..].iter().fold(QM31::ZERO, |v, x| v.add(*x)));
        prev = co.iter().rev().fold(QM31::ZERO, |v, x| v.mul(a[j]).add(*x));
        out.push(co);
    }
    out
}
/// Per-round projection ranks (copied from z7.rs).
struct Proj {
    full: Vec<Ech<M31>>,
    limb: Vec<Vec<Ech<M31>>>,
}
impl Proj {
    fn of(e: &Ech<M31>, a: &[QM31; 10]) -> Self {
        let mut p = Proj {
            full: (0..10).map(|_| Ech::new(112)).collect(),
            limb: (0..10).map(|_| (0..4).map(|_| Ech::new(28)).collect()).collect(),
        };
        for b in e.p.iter().flatten() {
            for (j, co) in round_polys(&unflat(b), a).iter().enumerate() {
                p.full[j].insert(flatten(co));
                for k in 0..4 {
                    p.limb[j][k].insert(co.iter().map(|x| limbs(*x)[k]).collect());
                }
            }
        }
        p
    }
    fn full_ranks(&self) -> Vec<usize> {
        self.full.iter().map(|e| e.rank).collect()
    }
    fn limb_ranks(&self) -> Vec<[usize; 4]> {
        self.limb.iter().map(|l| std::array::from_fn(|k| l[k].rank)).collect()
    }
}

fn wq(x: QM31) -> W {
    W::from_qm31(x)
}
fn wlimbs(x: W) -> [M31; 8] {
    x.to_limbs().map(M31)
}
fn wpt(p: Point<QM31>) -> Point<W> {
    Point { x: wq(p.x), y: wq(p.y) }
}
fn w_uniform(rng: &mut Rng) -> W {
    W::new(rng.q(), rng.q())
}
struct Opening {
    gamma: W,
    kappa: W,
    tau: W,
    fold: W,
}
/// ch.opening 0..3, uniform in WideExact; one stream per vector (shared by
/// all structures of that vector); gamma resampled at zero as the sampler does.
fn opening_challenges(v: usize) -> Opening {
    let mut rng = Rng(OPEN_SEED.wrapping_add((v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let gamma = loop {
        let g = w_uniform(&mut rng);
        if g != W::ZERO {
            break g;
        }
    };
    Opening { gamma, kappa: w_uniform(&mut rng), tau: w_uniform(&mut rng), fold: w_uniform(&mut rng) }
}

/// Lean `totalWeights` with Lean `weights` (Rust OpeningData::weights + kappa^4 libraWeight).
fn total_weights(basis: &NaturalBasis, a: &[QM31; 10], z: [Point<W>; 2], op: &Opening) -> [W; 1024] {
    let aw = a.map(wq);
    let pts = opening::points_from_alphas(&aw);
    // Orientation check: Rust row_eq_weight(points_from_alphas) == Z4c eq(points).
    let zp = points(a);
    for j in 0..3 {
        let rw = opening::row_eq_weight(&pts[j]);
        for r in 0..N {
            assert_eq!(rw[r], wq(eq(&zp[j], r)), "eq orientation j={j} r={r}");
        }
    }
    let eqs = pts.map(|p| opening::eq_weight(&p));
    let ind = opening::indicator();
    let k = opening::powers::<5>(op.kappa);
    let w: [W; 1024] = std::array::from_fn(|j| {
        ind[j]
            .add(k[1].mul(eqs[0][j]))
            .add(k[2].mul(eqs[1][j]))
            .add(k[3].mul(eqs[2][j]))
            .add(k[4].mul(wq(h_weight(a, j))))
    });
    let line = Secant::from_points(z[0], z[1]);
    let qw = chord::quotient_weights(basis, line, &w).expect("quotient_weights");
    let e1 = FunctionalWeights::e1::<W>(basis).expect("e1");
    let e2 = FunctionalWeights::e2(basis, line.b, line.c).expect("e2");
    std::array::from_fn(|j| qw[j].add(op.tau.mul(e1[j])).add(op.tau.mul(op.tau).mul(e2[j])))
}
fn ood_pair(m: &[W; 1024], z: [Point<W>; 2]) -> [W; 2] {
    [encoder::eval_message(m, z[0]), encoder::eval_message(m, z[1])]
}
/// phi[k] = (round_polynomial(Q e_k, total) [7], fold_message(op.fold, Q e_k) [256])
/// for every natural coefficient unit e_k (Q = prover::quotient, column-wise).
fn unit_functionals(basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening) -> Vec<[W; NB - 1]> {
    let ks: Vec<usize> = (0..1024).collect();
    let chunk = ks.len().div_ceil(THREADS);
    std::thread::scope(|s| {
        let hs: Vec<_> = ks
            .chunks(chunk)
            .map(|part| {
                s.spawn(move || {
                    part.iter()
                        .map(|&k| {
                            let mut e = [W::ZERO; 1024];
                            e[k] = W::ONE;
                            let q = prover::quotient(basis, z, &e, ood_pair(&e, z))
                                .unwrap_or_else(|err| panic!("STOP quotient unit k={k} error={err:?}"));
                            let rp = prover::round_polynomial(&q, total);
                            let f = fold::fold_message(op.fold, &q);
                            let mut out = [W::ZERO; NB - 1];
                            out[..7].copy_from_slice(&rp);
                            out[7..].copy_from_slice(&f);
                            out
                        })
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
    })
}

struct Ctx {
    a: [QM31; 10],
    br: Vec<Vec<M31>>,
    gr: Vec<Vec<QM31>>,
    tail: Vec<Vec<QM31>>,
    beta: Vec<[W; NB]>, // row-indexed
    gpow: Vec<W>,       // gamma^lane, lane 0..28
}
impl Ctx {
    /// Batched payload of x at row r of physical lane `lane`.
    fn batched(&self, lane: usize, x: W, r: usize) -> Vec<W> {
        let g = self.gpow[lane].mul(x);
        self.beta[r].iter().map(|b| g.mul(*b)).collect()
    }
}
fn wflat(v: &[W]) -> Vec<M31> {
    v.iter().flat_map(|x| wlimbs(*x)).collect()
}
fn sub_vec<T: Copy>(a: &[T], b: &[T], f: impl Fn(T, T) -> T) -> Vec<T> {
    a.iter().zip(b).map(|(x, y)| f(*x, *y)).collect()
}

/// One lane's sources, eliminated on its own per-lane coordinates (as Z4c's
/// lane_eliminate does), carrying [batched (2112) | round (1084)] in M31.
/// Kernel carries are inserted into `global`; returns the carried particular
/// solution for each per-lane target (which must lie in the lane's coordinate span).
fn lane_stage(
    count: usize,
    mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>),
    targets: &[Vec<M31>],
    global: &mut Ech<M31>,
) -> Vec<Vec<M31>> {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => {
                global.insert(c);
            }
        }
    }
    targets
        .iter()
        .map(|t| {
            let mut v = t.clone();
            let mut out = vec![M31::ZERO; TW];
            for i in 0..v.len() {
                if v[i] == M31::ZERO {
                    continue;
                }
                let (b, bc) = piv[i].as_ref().expect("per-lane target outside lane coordinate span");
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    out[j] = out[j].add(s.mul(bc[j]));
                }
            }
            out
        })
        .collect()
}
fn carry(batched: Vec<W>, round: &[QM31]) -> Vec<M31> {
    let mut c = wflat(&batched);
    c.extend(flatten(round));
    debug_assert_eq!(c.len(), TW);
    c
}
fn scale(v: &[QM31], x: QM31) -> Vec<QM31> {
    v.iter().map(|y| y.mul(x)).collect()
}
/// Mask-only lanes (F, all rows), G (K4, all rows) and D (K4, all rows).
fn pure_sources(cx: &Ctx, global: &mut Ech<M31>) {
    let a = &cx.a;
    for c in 0..10 {
        let lane = 16 + c;
        lane_stage(N, |r| (cx.br[r][1..].to_vec(), carry(cx.batched(lane, W::ONE, r), &round_row(a, r, c))), &[], global);
    }
    for (lane, g) in [(27usize, true), (28, false)] {
        lane_stage(
            4 * N,
            |i| {
                let (r, k) = (i / 4, i % 4);
                let x = tower(k);
                let rr = if g { round_row(a, r, 10) } else { cx.tail[r].clone() };
                (flatten(&scale(&cx.gr[r][1..], x)), carry(cx.batched(lane, wq(x), r), &scale(&rr, x)))
            },
            &[],
            global,
        );
    }
}
/// Semantic eligible sources (balanced vs row 1023) and H1 padding (inactive
/// rows, balanced vs row 0), with the per-pair witness-difference targets.
fn conditioned_sources(cx: &Ctx, traces: &[Trace], pairs: usize, global: &mut Ech<M31>) -> Vec<Vec<M31>> {
    let a = &cx.a;
    let mut sol = vec![vec![M31::ZERO; TW]; pairs];
    for c in 0..16 {
        let rows: Vec<usize> = (0..N).filter(|&r| r != 1023 && eligible(c, r)).collect();
        let tg: Vec<Vec<M31>> = (0..pairs)
            .map(|p| {
                let d: Vec<M31> = (0..N).map(|r| traces[2 * p][c][r].c0.a.sub(traces[2 * p + 1][c][r].c0.a)).collect();
                (1..113).map(|i| (0..N).fold(M31::ZERO, |s, r| s.add(d[r].mul(cx.br[r][i])))).collect()
            })
            .collect();
        let rd = round_row(a, 1023, 38 + c);
        let bd = cx.batched(c, W::ONE, 1023);
        let s = lane_stage(
            rows.len(),
            |i| {
                let r = rows[i];
                let rr = round_row(a, r, 38 + c);
                let bb = cx.batched(c, W::ONE, r);
                if inactive(r) {
                    (
                        sub_vec(&cx.br[r][1..], &cx.br[1023][1..], |x, y| x.sub(y)),
                        carry(sub_vec(&bb, &bd, |x, y| x.sub(y)), &sub_vec(&rr, &rd, |x, y| x.sub(y))),
                    )
                } else {
                    (cx.br[r][1..].to_vec(), carry(bb, &rr))
                }
            },
            &tg,
            global,
        );
        for p in 0..pairs {
            for j in 0..TW {
                sol[p][j] = sol[p][j].add(s[p][j]);
            }
        }
    }
    let rows: Vec<usize> = (1..N).filter(|&r| inactive(r)).collect();
    let tg: Vec<Vec<M31>> = (0..pairs)
        .map(|p| {
            let d: Vec<QM31> = (0..N).map(|r| traces[2 * p][16][r].sub(traces[2 * p + 1][16][r])).collect();
            flatten(&(1..95).map(|i| (0..N).fold(QM31::ZERO, |s, r| s.add(d[r].mul(cx.gr[r][i])))).collect::<Vec<_>>())
        })
        .collect();
    let zero = vec![QM31::ZERO; 271];
    let s = lane_stage(
        4 * rows.len(),
        |i| {
            let (r, k) = (rows[i / 4], i % 4);
            let x = tower(k);
            let b = sub_vec(&cx.batched(26, wq(x), r), &cx.batched(26, wq(x), 0), |p, q| p.sub(q));
            (flatten(&scale(&sub_vec(&cx.gr[r][1..], &cx.gr[0][1..], |p, q| p.sub(q)), x)), carry(b, &zero))
        },
        &tg,
        global,
    );
    for p in 0..pairs {
        for j in 0..TW {
            sol[p][j] = sol[p][j].add(s[p][j]);
        }
    }
    sol
}
/// Rows of `e` with pivot >= from, sliced to the round part [BW..].
fn slice_image(e: &Ech<M31>, from: usize) -> Ech<M31> {
    let mut out = Ech::new(RW);
    for (i, row) in e.p.iter().enumerate() {
        if let Some(v) = row {
            if i >= from {
                out.insert(v[BW..].to_vec());
            }
        }
    }
    out
}
/// Reduce by pivots < BW only (the batched coordinates).
fn batched_reduce(e: &Ech<M31>, mut v: Vec<M31>) -> Vec<M31> {
    for i in 0..BW {
        if v[i] == M31::ZERO {
            continue;
        }
        if let Some(b) = &e.p[i] {
            let s = v[i];
            for j in i..v.len() {
                v[j] = v[j].sub(s.mul(b[j]));
            }
        }
    }
    v
}
fn report(label: &str, kind: &str, total: usize, p: &Proj) {
    println!(
        "Z8_RANKS {label} kind={kind} total={total} round_full={:?} round_limb={:?}",
        p.full_ranks(),
        p.limb_ranks()
    );
}

/// Direct check of the column-wise decomposition: for random words on lanes
/// 16 (F) and 27, 28 (K4), the Rust pipeline on whole columns (quotient per
/// lane, gamma-batched, round_polynomial with total weights, fold_message,
/// v_honest-style inactive sum) equals the sum of per-row batched vectors.
fn decomposition_check(cx: &Ctx, basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening, seed: u64) {
    let mut rng = Rng(seed);
    let mut q = [W::ZERO; 1024];
    let mut inactive_sum = W::ZERO;
    let mut expected = vec![W::ZERO; NB];
    for lane in [16usize, 27, 28] {
        let rows: [W; 1024] = std::array::from_fn(|_| if lane == 16 { wq(QM31::from_m31(rng.m())) } else { wq(rng.q()) });
        let coeffs = aspis_core::r0::transport::to_coefficients(&rows);
        let ql = prover::quotient(basis, z, &coeffs, ood_pair(&coeffs, z)).expect("column quotient");
        for i in 0..1024 {
            q[i] = q[i].add(cx.gpow[lane].mul(ql[i]));
        }
        for r in 0..N {
            if inactive(r) {
                inactive_sum = inactive_sum.add(cx.gpow[lane].mul(rows[r]));
            }
            for (e, b) in expected.iter_mut().zip(cx.batched(lane, rows[r], r)) {
                *e = e.add(b);
            }
        }
    }
    let rp = prover::round_polynomial(&q, total);
    let f = fold::fold_message(op.fold, &q);
    let mut direct = vec![inactive_sum];
    direct.extend_from_slice(&rp);
    direct.extend_from_slice(&f);
    assert_eq!(direct, expected, "column-wise decomposition");
    println!("Z8_CHECK decomposition lanes=[16,27,28] whole_column_pipeline_equals_rowwise_sum=true coordinates={NB}");
}

pub(super) fn main() {
    let args: Vec<_> = std::env::args().collect();
    let get = |k: &str| args.windows(2).find(|x| x[0] == k).map(|x| x[1].clone());
    let s = get("--structure").expect("--structure");
    let v: usize = get("--vector").expect("--vector").parse().unwrap();
    let preflight = args.iter().any(|x| x == "--preflight");
    let start = Instant::now();
    println!("Z8_START structure={s} vector={v} preflight={preflight} transport=D13 batching=WideExact dlift=false proxy=false");
    let t = trial(v);
    let a = alpha_for(&s, v, &t.a);
    let label = format!("structure={s} vector={v}");
    let op = opening_challenges(v);
    println!(
        "Z8_ALPHA {label} alpha={:?} lambda_dims={:?}",
        a.map(l4),
        lambda_dims(&a)
    );
    println!(
        "Z8_OPENING {label} gamma={:?} kappa={:?} tau={:?} fold={:?}",
        op.gamma.to_limbs(),
        op.kappa.to_limbs(),
        op.tau.to_limbs(),
        op.fold.to_limbs()
    );
    let basis = NaturalBasis::new(BasisSize::Initial).expect("basis");
    let z = [wpt(t.z[0]), wpt(t.z[1])];
    let total = total_weights(&basis, &a, z, &op);
    let phi = unit_functionals(&basis, z, &total, &op);
    println!("Z8_CHECK unit_quotients=1024 ok=true eq_orientation=true seconds={:.3}", start.elapsed().as_secs_f64());
    let beta: Vec<[W; NB]> = (0..N)
        .map(|r| {
            let mut b = [W::ZERO; NB];
            b[0] = if inactive(r) { W::ONE } else { W::ZERO };
            b[1..].copy_from_slice(&phi[usize::from(ROW_TO_COEFFICIENT[r])]);
            b
        })
        .collect();
    let gpow = (0..29).map(|l| op.gamma.pow(l as u64)).collect();
    let (br, gr) = raw_c(&a, &t.z, &t.qs);
    let tail: Vec<_> = (0..N).map(|r| tail_row(&a, r)).collect();
    let cx = Ctx { a, br, gr, tail, beta, gpow };
    decomposition_check(&cx, &basis, z, &total, &op, 0x5a38_c0de ^ v as u64);

    let mut pure = Ech::new(TW);
    pure_sources(&cx, &mut pure);
    let batched_rank = (0..BW).filter(|&i| pure.p[i].is_some()).count();
    let retained = slice_image(&pure, BW);
    let silent = slice_image(&pure, BW + 4);
    println!(
        "Z8_PURE {label} span_rank={} batched_pivots={batched_rank} initial_retained_rank={} silent_rank={} upper_bound=1076 seconds={:.3}",
        pure.rank,
        retained.rank,
        silent.rank,
        start.elapsed().as_secs_f64()
    );
    report(&label, "silent", silent.rank, &Proj::of(&silent, &a));
    report(&label, "silent_initial_retained", retained.rank, &Proj::of(&retained, &a));
    if s == "A" && silent.rank < 1076 {
        println!("Z8_FINDING {label} structure_A_silent_rank={} below=1076", silent.rank);
    }
    let chain0: Vec<Vec<M31>> = (4..RW)
        .map(|i| {
            let mut u = vec![M31::ZERO; RW];
            u[i] = M31::ONE;
            let q = unflat(&u);
            let phi = final_value(&q, &a);
            flatten(&normalize_d(&q, phi, &a).expect("alpha9=1/2"))
        })
        .collect();
    summarize(&format!("{label} chain0_basis"), &silent, &chain0);
    if preflight {
        println!("Z8_PREFLIGHT_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
        return;
    }
    // Z4c's honest targets at this alpha.
    let (pubdata, instances) = real::instances();
    let ch = t.ch;
    let traces: Vec<Trace> = instances
        .iter()
        .map(|w| {
            let mut tr: Trace = w
                .compilation
                .semantic_c1
                .c1
                .iter()
                .map(|col| col.iter().map(|x| QM31::from_m31(*x)).collect())
                .collect();
            match build_pool_v1_pair_forest_copy_helper_v1(
                &w.compilation.trace,
                w.compilation.public_statement.live_snapshot.next_pair_index,
                ch.lambda,
                ch.chi,
            ) {
                Ok(h) => tr.push(h),
                Err(error) => {
                    println!("STOP reason=helper_pole_or_helper_abort {label} error={error:?}");
                    std::process::exit(22);
                }
            }
            balance_trace(&mut tr);
            tr
        })
        .collect();
    let mut targets = vec![];
    for pair in 0..5 {
        let mut noise = t.tapes[pair].clone();
        balance_trace(&mut noise);
        let public = Public::Transfer(&pubdata, &instances[2 * pair].compilation.public_statement);
        let original = compute_targets(public, &a, &ch, &traces[2 * pair], &traces[2 * pair + 1], &noise, pair);
        println!(
            "Z8_TERMINAL {label} pair={pair} pinned={:?} derivative={:?} ii={:?}",
            l4(original.terminal[0]),
            l4(original.terminal[1]),
            l4(original.terminal[2])
        );
        targets.push(normalized(&original, &a, &traces[2 * pair], &traces[2 * pair + 1], &ch, public));
    }
    let i: Vec<_> = targets.iter().map(|t| flatten(&t.pinned)).collect();
    let derivative: Vec<_> = targets.iter().map(|t| flatten(&t.derivative)).collect();
    summarize(&format!("{label} wide_i_prime"), &silent, &i);
    summarize(&format!("{label} wide_derivative_diagnostic"), &silent, &derivative);
    // (ii'): witness-difference payload (per-lane + WideExact-batched) and rounds.
    let mut full = Ech { p: pure.p.clone(), rank: pure.rank };
    let sol = conditioned_sources(&cx, &traces, 5, &mut full);
    let conditioned = slice_image(&full, BW);
    let mut ii = vec![];
    let mut batched_unmatched = vec![];
    for p in 0..5 {
        // Witness difference's batched payload over semantic lanes 0..15 and H1 (lane 26).
        let mut b = vec![W::ZERO; NB];
        for c in 0..17 {
            let lane = if c == 16 { 26 } else { c };
            for r in 0..N {
                let d = traces[2 * p][c][r].sub(traces[2 * p + 1][c][r]);
                if d == QM31::ZERO {
                    continue;
                }
                for (e, x) in b.iter_mut().zip(cx.batched(lane, wq(d), r)) {
                    *e = e.add(x);
                }
            }
        }
        let target = carry(b, &targets[p].difference);
        let residual = batched_reduce(&full, sub_vec(&target, &sol[p], |x, y| x.sub(y)));
        let unmatched = residual[..BW].iter().filter(|x| **x != M31::ZERO).count();
        batched_unmatched.push(unmatched);
        ii.push(residual[BW..].to_vec());
    }
    println!("Z8_II_BATCHED {label} batched_coordinates_unmatched_per_pair={batched_unmatched:?}");
    summarize(&format!("{label} wide_ii_prime"), &conditioned, &ii);
    let ip = pass_count(&silent, &i);
    let iip = (0..5).filter(|&p| batched_unmatched[p] == 0 && conditioned.residual(ii[p].clone()).iter().all(|x| *x == M31::ZERO)).count();
    println!(
        "Z8_GATE {label} silent_rank={} initial_retained_rank={} full_span_rank={} full_conditioned_rank={} i_pass={ip} ii_pass={iip} attempted=5",
        silent.rank,
        retained.rank,
        full.rank,
        conditioned.rank
    );
    println!("Z8_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
}

//! Z8b (LOG D20‴.3 "Z8b"): numeric check of the PCS-cancellation /
//! round-spanning decomposition on Z8's structure-(A) vectors, with Z8's
//! WideExact batching and real linearPayload silence coordinates.
//!
//! Everything above `// ---- Z8b ----` is copied verbatim from z8.rs (trial
//! replay, alpha helpers, round_polys, Proj, WideExact opening challenges,
//! Lean totalWeights, column-wise unit quotient functionals, Ctx, carry,
//! scale, report, decomposition_check). Rank routines: probe.rs's Ech,
//! initial_zero, copied_ech, summarize, pass_count (unchanged).
use super::*;
use aspis_core::field::WideExact as W;
use aspis_core::r0::{
    basis::{BasisSize, NaturalBasis},
    chord::{self, FunctionalWeights, Secant},
    encoder, fold, opening, prover,
    transport::ROW_TO_COEFFICIENT,
};

const MASTER: u64 = 0x5348f0b9a87835d0;
const STRUCT_SEED: u64 = 0x5a38_d20b_2026_1013;
const OPEN_SEED: u64 = 0x5a38_0be0_2026_1013;
const STRUCTURES: [&str; 4] = ["A", "B", "I", "J"];
const NB: usize = 264; // inactiveSum + 7 openingCoeff + 256 finalCoeff
const BW: usize = NB * 8; // batched M31 coordinates
const RW: usize = 1084; // round coordinates (Z4c layout)
const TW: usize = BW + RW;
const THREADS: usize = 4;

struct Trial {
    a: [QM31; 10],
    z: [Point<QM31>; 2],
    qs: Vec<usize>,
    ch: Challenges,
    tapes: Vec<Trace>,
}
/// Exact replay of z4c_main's RNG consumption (copied from z7.rs `trial`).
fn trial(trial: usize) -> Trial {
    let trial_seed = MASTER.wrapping_add((trial as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15));
    let mut rng = Rng(trial_seed);
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()), circle(rng.q())];
    let sets = query_sets(&mut rng);
    let ch = Challenges {
        lambda: rng.q(),
        chi: rng.q(),
        theta: rng.q(),
        zc: std::array::from_fn(|_| rng.q()),
        mu: rng.q(),
        eta: rng.q(),
    };
    println!("TRIAL_SEED trial={trial} seed={trial_seed:#x}");
    println!("CHALLENGE trial={trial} alpha={a:?} semantic={ch:?} circle={z:?} queries={:?}", sets[0].1);
    let tapes = (0..5)
        .map(|_| {
            (0..17)
                .map(|c| {
                    (0..N)
                        .map(|r| {
                            if c < 16 && eligible(c, r) {
                                QM31::from_m31(rng.m())
                            } else if c == 16 && inactive(r) {
                                rng.q()
                            } else {
                                QM31::ZERO
                            }
                        })
                        .collect()
                })
                .collect()
        })
        .collect();
    Trial { a, z, qs: sets[0].1.clone(), ch, tapes }
}

fn l4(x: QM31) -> [u32; 4] {
    limbs(x).map(|v| v.0)
}
fn unflat(v: &[M31]) -> Vec<QM31> {
    v.chunks(4)
        .map(|c| QM31 { c0: CM31::new(c[0], c[1]), c1: CM31::new(c[2], c[3]) })
        .collect()
}
fn half() -> QM31 {
    QM31::from_m31(M31(2).inv())
}
fn admissible(a: &[QM31; 10]) -> bool {
    a.iter().all(|x| *x != QM31::ZERO && *x != QM31::ONE) && a[9] != half()
}
fn f_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31::from_m31(rng.m());
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
fn k2_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31 { c0: CM31::new(rng.m(), rng.m()), c1: CM31::new(M31::ZERO, M31::ZERO) };
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
/// A: Z4c alpha. B: all alpha_i in F\{0,1}. I: all alpha_i in K2 = F(i)\{0,1}.
/// J: alpha_0 Z4c (uniform in QM31), alpha_1..6 in F\{0,1}, alpha_7..9 Z4c.
fn alpha_for(s: &str, v: usize, base: &[QM31; 10]) -> [QM31; 10] {
    let si = STRUCTURES.iter().position(|x| *x == s).unwrap() as u64;
    let mut rng = Rng(STRUCT_SEED.wrapping_add((si * 64 + v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let mut a = *base;
    match s {
        "A" => {}
        "B" => (0..10).for_each(|i| a[i] = f_nontrivial(&mut rng, i == 9)),
        "I" => (0..10).for_each(|i| a[i] = k2_nontrivial(&mut rng, i == 9)),
        "J" => (1..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        _ => panic!("unknown structure {s}"),
    }
    assert!(admissible(&a), "alpha admissibility");
    a
}
fn lambda_dims(a: &[QM31; 10]) -> Vec<usize> {
    (0..10)
        .map(|j| {
            let mut e = Ech::new(4);
            for l in 0..1usize << j {
                let x = (0..j).fold(QM31::ONE, |v, i| {
                    v.mul(if l >> i & 1 == 1 { a[i] } else { QM31::ONE.sub(a[i]) })
                });
                e.insert(limbs(x).to_vec());
            }
            e.rank
        })
        .collect()
}

/// `last_coeff`'s chain reconstruction, returning all ten polys (copied from z7.rs).
fn round_polys(v: &[QM31], a: &[QM31; 10]) -> Vec<[QM31; 28]> {
    let mut prev = v[0];
    let mut out = vec![];
    for j in 0..10 {
        let mut co = [QM31::ZERO; 28];
        co[0] = v[1 + 27 * j];
        co[2..].copy_from_slice(&v[2 + 27 * j..28 + 27 * j]);
        co[1] = prev
            .sub(co[0].add(co[0]))
            .sub(co[2..].iter().fold(QM31::ZERO, |v, x| v.add(*x)));
        prev = co.iter().rev().fold(QM31::ZERO, |v, x| v.mul(a[j]).add(*x));
        out.push(co);
    }
    out
}
/// Per-round projection ranks (copied from z7.rs).
struct Proj {
    full: Vec<Ech<M31>>,
    limb: Vec<Vec<Ech<M31>>>,
}
impl Proj {
    fn of(e: &Ech<M31>, a: &[QM31; 10]) -> Self {
        let mut p = Proj {
            full: (0..10).map(|_| Ech::new(112)).collect(),
            limb: (0..10).map(|_| (0..4).map(|_| Ech::new(28)).collect()).collect(),
        };
        for b in e.p.iter().flatten() {
            for (j, co) in round_polys(&unflat(b), a).iter().enumerate() {
                p.full[j].insert(flatten(co));
                for k in 0..4 {
                    p.limb[j][k].insert(co.iter().map(|x| limbs(*x)[k]).collect());
                }
            }
        }
        p
    }
    fn full_ranks(&self) -> Vec<usize> {
        self.full.iter().map(|e| e.rank).collect()
    }
    fn limb_ranks(&self) -> Vec<[usize; 4]> {
        self.limb.iter().map(|l| std::array::from_fn(|k| l[k].rank)).collect()
    }
}

fn wq(x: QM31) -> W {
    W::from_qm31(x)
}
fn wlimbs(x: W) -> [M31; 8] {
    x.to_limbs().map(M31)
}
fn wpt(p: Point<QM31>) -> Point<W> {
    Point { x: wq(p.x), y: wq(p.y) }
}
fn w_uniform(rng: &mut Rng) -> W {
    W::new(rng.q(), rng.q())
}
struct Opening {
    gamma: W,
    kappa: W,
    tau: W,
    fold: W,
}
/// ch.opening 0..3, uniform in WideExact; one stream per vector (shared by
/// all structures of that vector); gamma resampled at zero as the sampler does.
fn opening_challenges(v: usize) -> Opening {
    let mut rng = Rng(OPEN_SEED.wrapping_add((v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let gamma = loop {
        let g = w_uniform(&mut rng);
        if g != W::ZERO {
            break g;
        }
    };
    Opening { gamma, kappa: w_uniform(&mut rng), tau: w_uniform(&mut rng), fold: w_uniform(&mut rng) }
}

/// Lean `totalWeights` with Lean `weights` (Rust OpeningData::weights + kappa^4 libraWeight).
fn total_weights(basis: &NaturalBasis, a: &[QM31; 10], z: [Point<W>; 2], op: &Opening) -> [W; 1024] {
    let aw = a.map(wq);
    let pts = opening::points_from_alphas(&aw);
    // Orientation check: Rust row_eq_weight(points_from_alphas) == Z4c eq(points).
    let zp = points(a);
    for j in 0..3 {
        let rw = opening::row_eq_weight(&pts[j]);
        for r in 0..N {
            assert_eq!(rw[r], wq(eq(&zp[j], r)), "eq orientation j={j} r={r}");
        }
    }
    let eqs = pts.map(|p| opening::eq_weight(&p));
    let ind = opening::indicator();
    let k = opening::powers::<5>(op.kappa);
    let w: [W; 1024] = std::array::from_fn(|j| {
        ind[j]
            .add(k[1].mul(eqs[0][j]))
            .add(k[2].mul(eqs[1][j]))
            .add(k[3].mul(eqs[2][j]))
            .add(k[4].mul(wq(h_weight(a, j))))
    });
    let line = Secant::from_points(z[0], z[1]);
    let qw = chord::quotient_weights(basis, line, &w).expect("quotient_weights");
    let e1 = FunctionalWeights::e1::<W>(basis).expect("e1");
    let e2 = FunctionalWeights::e2(basis, line.b, line.c).expect("e2");
    std::array::from_fn(|j| qw[j].add(op.tau.mul(e1[j])).add(op.tau.mul(op.tau).mul(e2[j])))
}
fn ood_pair(m: &[W; 1024], z: [Point<W>; 2]) -> [W; 2] {
    [encoder::eval_message(m, z[0]), encoder::eval_message(m, z[1])]
}
/// phi[k] = (round_polynomial(Q e_k, total) [7], fold_message(op.fold, Q e_k) [256])
/// for every natural coefficient unit e_k (Q = prover::quotient, column-wise).
fn unit_functionals(basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening) -> Vec<[W; NB - 1]> {
    let ks: Vec<usize> = (0..1024).collect();
    let chunk = ks.len().div_ceil(THREADS);
    std::thread::scope(|s| {
        let hs: Vec<_> = ks
            .chunks(chunk)
            .map(|part| {
                s.spawn(move || {
                    part.iter()
                        .map(|&k| {
                            let mut e = [W::ZERO; 1024];
                            e[k] = W::ONE;
                            let q = prover::quotient(basis, z, &e, ood_pair(&e, z))
                                .unwrap_or_else(|err| panic!("STOP quotient unit k={k} error={err:?}"));
                            let rp = prover::round_polynomial(&q, total);
                            let f = fold::fold_message(op.fold, &q);
                            let mut out = [W::ZERO; NB - 1];
                            out[..7].copy_from_slice(&rp);
                            out[7..].copy_from_slice(&f);
                            out
                        })
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
    })
}

struct Ctx {
    a: [QM31; 10],
    br: Vec<Vec<M31>>,
    gr: Vec<Vec<QM31>>,
    tail: Vec<Vec<QM31>>,
    beta: Vec<[W; NB]>, // row-indexed
    gpow: Vec<W>,       // gamma^lane, lane 0..28
}
impl Ctx {
    /// Batched payload of x at row r of physical lane `lane`.
    fn batched(&self, lane: usize, x: W, r: usize) -> Vec<W> {
        let g = self.gpow[lane].mul(x);
        self.beta[r].iter().map(|b| g.mul(*b)).collect()
    }
}
fn wflat(v: &[W]) -> Vec<M31> {
    v.iter().flat_map(|x| wlimbs(*x)).collect()
}
fn sub_vec<T: Copy>(a: &[T], b: &[T], f: impl Fn(T, T) -> T) -> Vec<T> {
    a.iter().zip(b).map(|(x, y)| f(*x, *y)).collect()
}

fn carry(batched: Vec<W>, round: &[QM31]) -> Vec<M31> {
    let mut c = wflat(&batched);
    c.extend(flatten(round));
    debug_assert_eq!(c.len(), TW);
    c
}
fn scale(v: &[QM31], x: QM31) -> Vec<QM31> {
    v.iter().map(|y| y.mul(x)).collect()
}
fn report(label: &str, kind: &str, total: usize, p: &Proj) {
    println!(
        "Z8B_RANKS {label} kind={kind} total={total} round_full={:?} round_limb={:?}",
        p.full_ranks(),
        p.limb_ranks()
    );
}

/// Direct check of the column-wise decomposition: for random words on lanes
/// 16 (F) and 27, 28 (K4), the Rust pipeline on whole columns (quotient per
/// lane, gamma-batched, round_polynomial with total weights, fold_message,
/// v_honest-style inactive sum) equals the sum of per-row batched vectors.
fn decomposition_check(cx: &Ctx, basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening, seed: u64) {
    let mut rng = Rng(seed);
    let mut q = [W::ZERO; 1024];
    let mut inactive_sum = W::ZERO;
    let mut expected = vec![W::ZERO; NB];
    for lane in [16usize, 27, 28] {
        let rows: [W; 1024] = std::array::from_fn(|_| if lane == 16 { wq(QM31::from_m31(rng.m())) } else { wq(rng.q()) });
        let coeffs = aspis_core::r0::transport::to_coefficients(&rows);
        let ql = prover::quotient(basis, z, &coeffs, ood_pair(&coeffs, z)).expect("column quotient");
        for i in 0..1024 {
            q[i] = q[i].add(cx.gpow[lane].mul(ql[i]));
        }
        for r in 0..N {
            if inactive(r) {
                inactive_sum = inactive_sum.add(cx.gpow[lane].mul(rows[r]));
            }
            for (e, b) in expected.iter_mut().zip(cx.batched(lane, rows[r], r)) {
                *e = e.add(b);
            }
        }
    }
    let rp = prover::round_polynomial(&q, total);
    let f = fold::fold_message(op.fold, &q);
    let mut direct = vec![inactive_sum];
    direct.extend_from_slice(&rp);
    direct.extend_from_slice(&f);
    assert_eq!(direct, expected, "column-wise decomposition");
    println!("Z8B_CHECK decomposition lanes=[16,27,28] whole_column_pipeline_equals_rowwise_sum=true coordinates={NB}");
}


// ---- Z8b ----
use aspis_core::r0::transport::COEFFICIENT_TO_ROW;

const DW: usize = 376; // D's own-silence functionals: 94 K4-valued = 376 M31 limbs
const SW: usize = BW + DW + RW; // [batched | D own | round]

/// [batched limbs | D-own limbs | round limbs].
fn gen3(batched: Vec<W>, down: Vec<M31>, round: &[QM31]) -> Vec<M31> {
    let mut v = wflat(&batched);
    v.extend(down);
    v.extend(flatten(round));
    assert_eq!(v.len(), SW);
    v
}
fn d_own(cx: &Ctx, r: usize, x: QM31) -> Vec<M31> {
    flatten(&scale(&cx.gr[r][1..], x))
}
/// z8.rs `lane_stage` with the carry width taken from the source and the
/// kernel carries handed to `sink` (no targets).
fn lane_kernel(count: usize, mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>), mut sink: impl FnMut(Vec<M31>)) {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..c.len() {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => sink(c),
        }
    }
}
fn slice_from(e: &Ech<M31>, from: usize, offset: usize, width: usize) -> Ech<M31> {
    let mut out = Ech::new(width);
    for (i, row) in e.p.iter().enumerate() {
        if let (Some(v), true) = (row, i >= from) {
            out.insert(v[offset..].to_vec());
        }
    }
    out
}
fn rank_of(width: usize, vs: impl Iterator<Item = Vec<M31>>) -> usize {
    let mut e = Ech::new(width);
    for v in vs {
        e.insert(v);
    }
    e.rank
}
fn g_lane_coords(cx: &Ctx, r: usize, x: QM31, with_inactive: bool) -> Vec<M31> {
    let mut v = d_own(cx, r, x);
    if with_inactive {
        v.extend(if inactive(r) { limbs(x) } else { [M31::ZERO; 4] });
    }
    v
}

pub(super) fn main() {
    let args: Vec<_> = std::env::args().collect();
    let get = |k: &str| args.windows(2).find(|x| x[0] == k).map(|x| x[1].clone());
    let s = get("--structure").unwrap_or_else(|| "A".to_string());
    let v: usize = get("--vector").expect("--vector").parse().unwrap();
    let preflight = args.iter().any(|x| x == "--preflight");
    let start = Instant::now();
    println!("Z8B_START structure={s} vector={v} preflight={preflight} transport=D13 batching=WideExact");
    let t = trial(v);
    let a = alpha_for(&s, v, &t.a);
    let label = format!("structure={s} vector={v}");
    let op = opening_challenges(v);
    println!("Z8B_ALPHA {label} alpha={:?} lambda_dims={:?}", a.map(l4), lambda_dims(&a));
    println!(
        "Z8B_OPENING {label} gamma={:?} kappa={:?} tau={:?} fold={:?}",
        op.gamma.to_limbs(),
        op.kappa.to_limbs(),
        op.tau.to_limbs(),
        op.fold.to_limbs()
    );
    let basis = NaturalBasis::new(BasisSize::Initial).expect("basis");
    let z = [wpt(t.z[0]), wpt(t.z[1])];
    let total = total_weights(&basis, &a, z, &op);
    let phi = unit_functionals(&basis, z, &total, &op);
    let beta: Vec<[W; NB]> = (0..N)
        .map(|r| {
            let mut b = [W::ZERO; NB];
            b[0] = if inactive(r) { W::ONE } else { W::ZERO };
            b[1..].copy_from_slice(&phi[usize::from(ROW_TO_COEFFICIENT[r])]);
            b
        })
        .collect();
    let gpow = (0..29).map(|l| op.gamma.pow(l as u64)).collect();
    let (br, gr) = raw_c(&a, &t.z, &t.qs);
    let tail: Vec<_> = (0..N).map(|r| tail_row(&a, r)).collect();
    let cx = Ctx { a, br, gr, tail, beta, gpow };
    decomposition_check(&cx, &basis, z, &total, &op, 0x5a38_c0de ^ v as u64);
    let rows_lo: Vec<usize> = (0..56).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    let rows_hi: Vec<usize> = (56..1024).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    for &r in &rows_hi {
        assert!(cx.tail[r].iter().all(|x| *x == QM31::ZERO), "D coefficient >= 56 has a round contribution");
    }
    let xs: Vec<QM31> = (0..4).map(tower).collect();

    // Per-lane own-silence functional ranks (rows = all 1,024 sources).
    let mask_ranks: Vec<usize> = (0..10).map(|_| rank_of(112, (0..N).map(|r| cx.br[r][1..].to_vec()))).collect();
    let k4_rank = rank_of(DW, (0..N).flat_map(|r| xs.iter().map(move |&x| (r, x))).map(|(r, x)| d_own(&cx, r, x)));
    let g_inactive_rank = rank_of(DW + 4, (0..N).flat_map(|r| xs.iter().map(move |&x| (r, x))).map(|(r, x)| g_lane_coords(&cx, r, x, true)));
    let d_lo_rank = rank_of(DW, rows_lo.iter().flat_map(|&r| xs.iter().map(move |&x| (r, x))).map(|(r, x)| d_own(&cx, r, x)));
    let d_hi_rank = rank_of(DW, rows_hi.iter().flat_map(|&r| xs.iter().map(move |&x| (r, x))).map(|(r, x)| d_own(&cx, r, x)));
    println!(
        "Z8B_LANE_RANKS {label} mask_only={mask_ranks:?} mask_functionals=112 G={k4_rank} D={k4_rank} k4_functionals={DW} G_with_inactive_sum={g_inactive_rank} of={} D_coeff_0_55={d_lo_rank} D_coeff_56_1023={d_hi_rank}",
        DW + 4
    );

    // (1) PCS cancellation block: batched (2,112) + D own (376) on D's coefficients 56..1023.
    let hi_gens: Vec<Vec<M31>> = rows_hi
        .iter()
        .flat_map(|&r| xs.iter().map(move |&x| (r, x)))
        .map(|(r, x)| {
            let mut g = wflat(&cx.batched(28, wq(x), r));
            g.extend(d_own(&cx, r, x));
            g
        })
        .collect();
    let g_inact: Vec<Vec<M31>> = xs
        .iter()
        .map(|&x| {
            let mut b = vec![W::ZERO; NB];
            b[0] = cx.gpow[27].mul(wq(x));
            let mut g = wflat(&b);
            g.extend(vec![M31::ZERO; DW]);
            g
        })
        .collect();
    let block = |gs: &[Vec<M31>]| {
        (
            rank_of(BW + DW, gs.iter().cloned()),
            rank_of(BW, gs.iter().map(|g| g[..BW].to_vec())),
            rank_of(DW, gs.iter().map(|g| g[BW..].to_vec())),
            rank_of(8, gs.iter().map(|g| g[..8].to_vec())),
            rank_of(BW - 8, gs.iter().map(|g| g[8..BW].to_vec())),
        )
    };
    let (r1, rb, rd, ri, ro) = block(&hi_gens);
    println!("Z8B_P1 {label} variant=D_56_1023 columns={} rank={r1} batched_only={rb} d_own_only={rd} inactive_sum_only={ri} opening_final_only={ro} functionals={}", hi_gens.len(), BW + DW);
    let mut with_g = hi_gens.clone();
    with_g.extend(g_inact);
    let (r1g, rbg, rdg, rig, rog) = block(&with_g);
    println!("Z8B_P1 {label} variant=D_56_1023_plus_G_inactive_sum columns={} rank={r1g} batched_only={rbg} d_own_only={rdg} inactive_sum_only={rig} opening_final_only={rog} functionals={}", with_g.len(), BW + DW);

    // (2) round spanning and (3) assembled silent subspace.
    let mut e2 = Ech::new(RW);
    let mut e3 = Ech::new(SW);
    let mut count = [0usize; 3];
    for c in 0..10 {
        let lane = 16 + c;
        lane_kernel(
            N,
            |r| (cx.br[r][1..].to_vec(), gen3(cx.batched(lane, W::ONE, r), vec![M31::ZERO; DW], &round_row(&a, r, c))),
            |g| {
                count[0] += 1;
                e2.insert(g[BW + DW..].to_vec());
                e3.insert(g);
            },
        );
    }
    lane_kernel(
        4 * N,
        |i| {
            let (r, x) = (i / 4, tower(i % 4));
            (g_lane_coords(&cx, r, x, true), gen3(cx.batched(27, wq(x), r), vec![M31::ZERO; DW], &scale(&round_row(&a, r, 10), x)))
        },
        |g| {
            count[1] += 1;
            e2.insert(g[BW + DW..].to_vec());
            e3.insert(g);
        },
    );
    for &r in &rows_lo {
        for &x in &xs {
            let g = gen3(cx.batched(28, wq(x), r), d_own(&cx, r, x), &scale(&cx.tail[r], x));
            count[2] += 1;
            e2.insert(g[BW + DW..].to_vec());
            e3.insert(g);
        }
    }
    let e2z = initial_zero(copied_ech(&e2));
    println!(
        "Z8B_Q2 {label} generators_mask_kernel={} generators_G_kernel={} generators_D_0_55={} round_rank_initial_retained={} round_rank_initial_zero={} seconds={:.3}",
        count[0], count[1], count[2], e2.rank, e2z.rank, start.elapsed().as_secs_f64()
    );
    report(&label, "q2_round_image_initial_retained", e2.rank, &Proj::of(&e2, &a));
    report(&label, "q2_round_image_initial_zero", e2z.rank, &Proj::of(&e2z, &a));
    let q2_silent = slice_from(&e3, BW + DW + 4, BW + DW, RW);
    println!("Z8B_Q2_SILENT {label} span_rank={} silent_rank_of_q2_generators_alone={}", e3.rank, q2_silent.rank);
    for g in &hi_gens {
        let mut v = g.clone();
        v.extend(vec![M31::ZERO; RW]);
        e3.insert(v);
    }
    let retained3 = slice_from(&e3, BW + DW, BW + DW, RW);
    let silent3 = slice_from(&e3, BW + DW + 4, BW + DW, RW);
    let silence_pivots = (0..BW + DW).filter(|&i| e3.p[i].is_some()).count();
    println!(
        "Z8B_ASSEMBLED {label} span_rank={} silence_pivots={silence_pivots} initial_retained_rank={} silent_rank={} z8_silent_rank=1076 seconds={:.3}",
        e3.rank, retained3.rank, silent3.rank, start.elapsed().as_secs_f64()
    );
    report(&label, "assembled_silent", silent3.rank, &Proj::of(&silent3, &a));
    report(&label, "assembled_silent_initial_retained", retained3.rank, &Proj::of(&retained3, &a));
    let chain0: Vec<Vec<M31>> = (4..RW)
        .map(|i| {
            let mut u = vec![M31::ZERO; RW];
            u[i] = M31::ONE;
            let q = unflat(&u);
            let phi = final_value(&q, &a);
            flatten(&normalize_d(&q, phi, &a).expect("alpha9=1/2"))
        })
        .collect();
    summarize(&format!("{label} q2_round_image_initial_zero_chain0"), &e2z, &chain0);
    summarize(&format!("{label} assembled_chain0_basis"), &silent3, &chain0);
    if preflight {
        println!("Z8B_PREFLIGHT_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
        return;
    }
    let (pubdata, instances) = real::instances();
    let ch = t.ch;
    let traces: Vec<Trace> = instances
        .iter()
        .map(|w| {
            let mut tr: Trace = w
                .compilation
                .semantic_c1
                .c1
                .iter()
                .map(|col| col.iter().map(|x| QM31::from_m31(*x)).collect())
                .collect();
            match build_pool_v1_pair_forest_copy_helper_v1(
                &w.compilation.trace,
                w.compilation.public_statement.live_snapshot.next_pair_index,
                ch.lambda,
                ch.chi,
            ) {
                Ok(h) => tr.push(h),
                Err(error) => {
                    println!("STOP reason=helper_pole_or_helper_abort {label} error={error:?}");
                    std::process::exit(22);
                }
            }
            balance_trace(&mut tr);
            tr
        })
        .collect();
    let mut targets = vec![];
    for pair in 0..5 {
        let mut noise = t.tapes[pair].clone();
        balance_trace(&mut noise);
        let public = Public::Transfer(&pubdata, &instances[2 * pair].compilation.public_statement);
        let original = compute_targets(public, &a, &ch, &traces[2 * pair], &traces[2 * pair + 1], &noise, pair);
        println!(
            "Z8B_TERMINAL {label} pair={pair} pinned={:?} derivative={:?} ii={:?}",
            l4(original.terminal[0]),
            l4(original.terminal[1]),
            l4(original.terminal[2])
        );
        targets.push(normalized(&original, &a, &traces[2 * pair], &traces[2 * pair + 1], &ch, public));
    }
    let i: Vec<_> = targets.iter().map(|t| flatten(&t.pinned)).collect();
    let derivative: Vec<_> = targets.iter().map(|t| flatten(&t.derivative)).collect();
    summarize(&format!("{label} assembled_i_prime"), &silent3, &i);
    summarize(&format!("{label} assembled_derivative_diagnostic"), &silent3, &derivative);
    summarize(&format!("{label} q2_i_prime"), &e2z, &i);
    println!(
        "Z8B_GATE {label} assembled_silent_rank={} q2_round_rank_initial_zero={} i_pass_assembled={} i_pass_q2={} attempted=5",
        silent3.rank,
        e2z.rank,
        pass_count(&silent3, &i),
        pass_count(&e2z, &i)
    );
    println!("Z8B_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
}

//! Z8c (T2b-2b design §3.3, LOG "Lead acceptance of the T2b-2b design as a
//! proposal (2026-10-15)"): the silent-rank gate on the BALANCED Lean mask
//! space, with Z8's WideExact batching and real linearPayload silence
//! coordinates. Exact M31/QM31/WideExact arithmetic. Not a Lean proof.
//!
//! Balancing (R0Z/MaskLayout.lean `balance 0`, `maskOnlyColumns`, `dWord`,
//! and lane 27 in `applyAff`): row 0 of every mask lane (mask-only 16..25,
//! G = 27, D = 28; each limb of G and D) is minus the sum of the other
//! copy-inactive rows. The balanced word space of a lane is therefore spanned
//! by e_r for active r and e_r - e_0 for inactive r != 0 (one source per raw
//! tape coordinate r != 0; the raw row-0 coordinate is overwritten and has no
//! effect). No batched-.inactiveSum proxy: on these sources .inactiveSum is
//! identically 0 and is checked to be so.
//!
//! Everything between this header and `// ---- Z8b helpers ----` is copied
//! verbatim from z8.rs (print tags renamed Z8_ -> Z8C_, as z8b.rs did; STRUCTURES
//! and alpha_for extended by K, L, M, appended so that A, B, I, J keep their
//! seeds). `lane_kernel`, `slice_from`, `rank_of`, `d_own` are copied verbatim
//! from z8b.rs. Rank routines: probe.rs's Ech, initial_zero, copied_ech,
//! summarize, pass_count (unchanged). New code follows `// ---- Z8c ----`.
use super::*;
use aspis_core::field::WideExact as W;
use aspis_core::r0::{
    basis::{BasisSize, NaturalBasis},
    chord::{self, FunctionalWeights, Secant},
    encoder, fold, opening, prover,
    transport::ROW_TO_COEFFICIENT,
};

const MASTER: u64 = 0x5348f0b9a87835d0;
const STRUCT_SEED: u64 = 0x5a38_d20b_2026_1013;
const OPEN_SEED: u64 = 0x5a38_0be0_2026_1013;
const STRUCTURES: [&str; 7] = ["A", "B", "I", "J", "K", "L", "M"];
const NB: usize = 264; // inactiveSum + 7 openingCoeff + 256 finalCoeff
const BW: usize = NB * 8; // batched M31 coordinates
const RW: usize = 1084; // round coordinates (Z4c layout)
const TW: usize = BW + RW;
const THREADS: usize = 4;

struct Trial {
    a: [QM31; 10],
    z: [Point<QM31>; 2],
    qs: Vec<usize>,
    ch: Challenges,
    tapes: Vec<Trace>,
}
/// Exact replay of z4c_main's RNG consumption (copied from z7.rs `trial`).
fn trial(trial: usize) -> Trial {
    let trial_seed = MASTER.wrapping_add((trial as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15));
    let mut rng = Rng(trial_seed);
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()), circle(rng.q())];
    let sets = query_sets(&mut rng);
    let ch = Challenges {
        lambda: rng.q(),
        chi: rng.q(),
        theta: rng.q(),
        zc: std::array::from_fn(|_| rng.q()),
        mu: rng.q(),
        eta: rng.q(),
    };
    println!("TRIAL_SEED trial={trial} seed={trial_seed:#x}");
    println!("CHALLENGE trial={trial} alpha={a:?} semantic={ch:?} circle={z:?} queries={:?}", sets[0].1);
    let tapes = (0..5)
        .map(|_| {
            (0..17)
                .map(|c| {
                    (0..N)
                        .map(|r| {
                            if c < 16 && eligible(c, r) {
                                QM31::from_m31(rng.m())
                            } else if c == 16 && inactive(r) {
                                rng.q()
                            } else {
                                QM31::ZERO
                            }
                        })
                        .collect()
                })
                .collect()
        })
        .collect();
    Trial { a, z, qs: sets[0].1.clone(), ch, tapes }
}

fn l4(x: QM31) -> [u32; 4] {
    limbs(x).map(|v| v.0)
}
fn unflat(v: &[M31]) -> Vec<QM31> {
    v.chunks(4)
        .map(|c| QM31 { c0: CM31::new(c[0], c[1]), c1: CM31::new(c[2], c[3]) })
        .collect()
}
fn half() -> QM31 {
    QM31::from_m31(M31(2).inv())
}
fn admissible(a: &[QM31; 10]) -> bool {
    a.iter().all(|x| *x != QM31::ZERO && *x != QM31::ONE) && a[9] != half()
}
fn f_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31::from_m31(rng.m());
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
fn k2_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31 { c0: CM31::new(rng.m(), rng.m()), c1: CM31::new(M31::ZERO, M31::ZERO) };
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
/// A: Z4c alpha. B: all alpha_i in F\{0,1}. I: all alpha_i in K2 = F(i)\{0,1}.
/// J: alpha_0 Z4c (uniform in QM31), alpha_1..6 in F\{0,1}, alpha_7..9 Z4c.
/// Z8c additions (seeds of A, B, I, J unchanged: new structures are appended):
/// K: alpha_2, alpha_3 in F\{0,1}, others Z4c.  L: alpha_0..5 in F\{0,1},
/// alpha_6..9 Z4c (alpha_6 checked outside K2).  M: alpha_3..6 in F\{0,1}, others Z4c.
fn alpha_for(s: &str, v: usize, base: &[QM31; 10]) -> [QM31; 10] {
    let si = STRUCTURES.iter().position(|x| *x == s).unwrap() as u64;
    let mut rng = Rng(STRUCT_SEED.wrapping_add((si * 64 + v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let mut a = *base;
    match s {
        "A" => {}
        "B" => (0..10).for_each(|i| a[i] = f_nontrivial(&mut rng, i == 9)),
        "I" => (0..10).for_each(|i| a[i] = k2_nontrivial(&mut rng, i == 9)),
        "J" => (1..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        "K" => (2..4).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        "L" => {
            (0..6).for_each(|i| a[i] = f_nontrivial(&mut rng, false));
            assert!(!in_k2(a[6]), "structure L needs alpha_6 outside K2");
        }
        "M" => (3..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        _ => panic!("unknown structure {s}"),
    }
    assert!(admissible(&a), "alpha admissibility");
    a
}
fn lambda_dims(a: &[QM31; 10]) -> Vec<usize> {
    (0..10)
        .map(|j| {
            let mut e = Ech::new(4);
            for l in 0..1usize << j {
                let x = (0..j).fold(QM31::ONE, |v, i| {
                    v.mul(if l >> i & 1 == 1 { a[i] } else { QM31::ONE.sub(a[i]) })
                });
                e.insert(limbs(x).to_vec());
            }
            e.rank
        })
        .collect()
}

/// `last_coeff`'s chain reconstruction, returning all ten polys (copied from z7.rs).
fn round_polys(v: &[QM31], a: &[QM31; 10]) -> Vec<[QM31; 28]> {
    let mut prev = v[0];
    let mut out = vec![];
    for j in 0..10 {
        let mut co = [QM31::ZERO; 28];
        co[0] = v[1 + 27 * j];
        co[2..].copy_from_slice(&v[2 + 27 * j..28 + 27 * j]);
        co[1] = prev
            .sub(co[0].add(co[0]))
            .sub(co[2..].iter().fold(QM31::ZERO, |v, x| v.add(*x)));
        prev = co.iter().rev().fold(QM31::ZERO, |v, x| v.mul(a[j]).add(*x));
        out.push(co);
    }
    out
}
/// Per-round projection ranks (copied from z7.rs).
struct Proj {
    full: Vec<Ech<M31>>,
    limb: Vec<Vec<Ech<M31>>>,
}
impl Proj {
    fn of(e: &Ech<M31>, a: &[QM31; 10]) -> Self {
        let mut p = Proj {
            full: (0..10).map(|_| Ech::new(112)).collect(),
            limb: (0..10).map(|_| (0..4).map(|_| Ech::new(28)).collect()).collect(),
        };
        for b in e.p.iter().flatten() {
            for (j, co) in round_polys(&unflat(b), a).iter().enumerate() {
                p.full[j].insert(flatten(co));
                for k in 0..4 {
                    p.limb[j][k].insert(co.iter().map(|x| limbs(*x)[k]).collect());
                }
            }
        }
        p
    }
    fn full_ranks(&self) -> Vec<usize> {
        self.full.iter().map(|e| e.rank).collect()
    }
    fn limb_ranks(&self) -> Vec<[usize; 4]> {
        self.limb.iter().map(|l| std::array::from_fn(|k| l[k].rank)).collect()
    }
}

fn wq(x: QM31) -> W {
    W::from_qm31(x)
}
fn wlimbs(x: W) -> [M31; 8] {
    x.to_limbs().map(M31)
}
fn wpt(p: Point<QM31>) -> Point<W> {
    Point { x: wq(p.x), y: wq(p.y) }
}
fn w_uniform(rng: &mut Rng) -> W {
    W::new(rng.q(), rng.q())
}
struct Opening {
    gamma: W,
    kappa: W,
    tau: W,
    fold: W,
}
/// ch.opening 0..3, uniform in WideExact; one stream per vector (shared by
/// all structures of that vector); gamma resampled at zero as the sampler does.
fn opening_challenges(v: usize) -> Opening {
    let mut rng = Rng(OPEN_SEED.wrapping_add((v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let gamma = loop {
        let g = w_uniform(&mut rng);
        if g != W::ZERO {
            break g;
        }
    };
    Opening { gamma, kappa: w_uniform(&mut rng), tau: w_uniform(&mut rng), fold: w_uniform(&mut rng) }
}

/// Lean `totalWeights` with Lean `weights` (Rust OpeningData::weights + kappa^4 libraWeight).
fn total_weights(basis: &NaturalBasis, a: &[QM31; 10], z: [Point<W>; 2], op: &Opening) -> [W; 1024] {
    let aw = a.map(wq);
    let pts = opening::points_from_alphas(&aw);
    // Orientation check: Rust row_eq_weight(points_from_alphas) == Z4c eq(points).
    let zp = points(a);
    for j in 0..3 {
        let rw = opening::row_eq_weight(&pts[j]);
        for r in 0..N {
            assert_eq!(rw[r], wq(eq(&zp[j], r)), "eq orientation j={j} r={r}");
        }
    }
    let eqs = pts.map(|p| opening::eq_weight(&p));
    let ind = opening::indicator();
    let k = opening::powers::<5>(op.kappa);
    let w: [W; 1024] = std::array::from_fn(|j| {
        ind[j]
            .add(k[1].mul(eqs[0][j]))
            .add(k[2].mul(eqs[1][j]))
            .add(k[3].mul(eqs[2][j]))
            .add(k[4].mul(wq(h_weight(a, j))))
    });
    let line = Secant::from_points(z[0], z[1]);
    let qw = chord::quotient_weights(basis, line, &w).expect("quotient_weights");
    let e1 = FunctionalWeights::e1::<W>(basis).expect("e1");
    let e2 = FunctionalWeights::e2(basis, line.b, line.c).expect("e2");
    std::array::from_fn(|j| qw[j].add(op.tau.mul(e1[j])).add(op.tau.mul(op.tau).mul(e2[j])))
}
fn ood_pair(m: &[W; 1024], z: [Point<W>; 2]) -> [W; 2] {
    [encoder::eval_message(m, z[0]), encoder::eval_message(m, z[1])]
}
/// phi[k] = (round_polynomial(Q e_k, total) [7], fold_message(op.fold, Q e_k) [256])
/// for every natural coefficient unit e_k (Q = prover::quotient, column-wise).
fn unit_functionals(basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening) -> Vec<[W; NB - 1]> {
    let ks: Vec<usize> = (0..1024).collect();
    let chunk = ks.len().div_ceil(THREADS);
    std::thread::scope(|s| {
        let hs: Vec<_> = ks
            .chunks(chunk)
            .map(|part| {
                s.spawn(move || {
                    part.iter()
                        .map(|&k| {
                            let mut e = [W::ZERO; 1024];
                            e[k] = W::ONE;
                            let q = prover::quotient(basis, z, &e, ood_pair(&e, z))
                                .unwrap_or_else(|err| panic!("STOP quotient unit k={k} error={err:?}"));
                            let rp = prover::round_polynomial(&q, total);
                            let f = fold::fold_message(op.fold, &q);
                            let mut out = [W::ZERO; NB - 1];
                            out[..7].copy_from_slice(&rp);
                            out[7..].copy_from_slice(&f);
                            out
                        })
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
    })
}

struct Ctx {
    a: [QM31; 10],
    br: Vec<Vec<M31>>,
    gr: Vec<Vec<QM31>>,
    tail: Vec<Vec<QM31>>,
    beta: Vec<[W; NB]>, // row-indexed
    gpow: Vec<W>,       // gamma^lane, lane 0..28
}
impl Ctx {
    /// Batched payload of x at row r of physical lane `lane`.
    fn batched(&self, lane: usize, x: W, r: usize) -> Vec<W> {
        let g = self.gpow[lane].mul(x);
        self.beta[r].iter().map(|b| g.mul(*b)).collect()
    }
}
fn wflat(v: &[W]) -> Vec<M31> {
    v.iter().flat_map(|x| wlimbs(*x)).collect()
}
fn sub_vec<T: Copy>(a: &[T], b: &[T], f: impl Fn(T, T) -> T) -> Vec<T> {
    a.iter().zip(b).map(|(x, y)| f(*x, *y)).collect()
}

/// One lane's sources, eliminated on its own per-lane coordinates (as Z4c's
/// lane_eliminate does), carrying [batched (2112) | round (1084)] in M31.
/// Kernel carries are inserted into `global`; returns the carried particular
/// solution for each per-lane target (which must lie in the lane's coordinate span).
fn lane_stage(
    count: usize,
    mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>),
    targets: &[Vec<M31>],
    global: &mut Ech<M31>,
) -> Vec<Vec<M31>> {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => {
                global.insert(c);
            }
        }
    }
    targets
        .iter()
        .map(|t| {
            let mut v = t.clone();
            let mut out = vec![M31::ZERO; TW];
            for i in 0..v.len() {
                if v[i] == M31::ZERO {
                    continue;
                }
                let (b, bc) = piv[i].as_ref().expect("per-lane target outside lane coordinate span");
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    out[j] = out[j].add(s.mul(bc[j]));
                }
            }
            out
        })
        .collect()
}
fn carry(batched: Vec<W>, round: &[QM31]) -> Vec<M31> {
    let mut c = wflat(&batched);
    c.extend(flatten(round));
    debug_assert_eq!(c.len(), TW);
    c
}
fn scale(v: &[QM31], x: QM31) -> Vec<QM31> {
    v.iter().map(|y| y.mul(x)).collect()
}
/// Mask-only lanes (F, all rows), G (K4, all rows) and D (K4, all rows).
fn pure_sources(cx: &Ctx, global: &mut Ech<M31>) {
    let a = &cx.a;
    for c in 0..10 {
        let lane = 16 + c;
        lane_stage(N, |r| (cx.br[r][1..].to_vec(), carry(cx.batched(lane, W::ONE, r), &round_row(a, r, c))), &[], global);
    }
    for (lane, g) in [(27usize, true), (28, false)] {
        lane_stage(
            4 * N,
            |i| {
                let (r, k) = (i / 4, i % 4);
                let x = tower(k);
                let rr = if g { round_row(a, r, 10) } else { cx.tail[r].clone() };
                (flatten(&scale(&cx.gr[r][1..], x)), carry(cx.batched(lane, wq(x), r), &scale(&rr, x)))
            },
            &[],
            global,
        );
    }
}
/// Semantic eligible sources (balanced vs row 1023) and H1 padding (inactive
/// rows, balanced vs row 0), with the per-pair witness-difference targets.
fn conditioned_sources(cx: &Ctx, traces: &[Trace], pairs: usize, global: &mut Ech<M31>) -> Vec<Vec<M31>> {
    let a = &cx.a;
    let mut sol = vec![vec![M31::ZERO; TW]; pairs];
    for c in 0..16 {
        let rows: Vec<usize> = (0..N).filter(|&r| r != 1023 && eligible(c, r)).collect();
        let tg: Vec<Vec<M31>> = (0..pairs)
            .map(|p| {
                let d: Vec<M31> = (0..N).map(|r| traces[2 * p][c][r].c0.a.sub(traces[2 * p + 1][c][r].c0.a)).collect();
                (1..113).map(|i| (0..N).fold(M31::ZERO, |s, r| s.add(d[r].mul(cx.br[r][i])))).collect()
            })
            .collect();
        let rd = round_row(a, 1023, 38 + c);
        let bd = cx.batched(c, W::ONE, 1023);
        let s = lane_stage(
            rows.len(),
            |i| {
                let r = rows[i];
                let rr = round_row(a, r, 38 + c);
                let bb = cx.batched(c, W::ONE, r);
                if inactive(r) {
                    (
                        sub_vec(&cx.br[r][1..], &cx.br[1023][1..], |x, y| x.sub(y)),
                        carry(sub_vec(&bb, &bd, |x, y| x.sub(y)), &sub_vec(&rr, &rd, |x, y| x.sub(y))),
                    )
                } else {
                    (cx.br[r][1..].to_vec(), carry(bb, &rr))
                }
            },
            &tg,
            global,
        );
        for p in 0..pairs {
            for j in 0..TW {
                sol[p][j] = sol[p][j].add(s[p][j]);
            }
        }
    }
    let rows: Vec<usize> = (1..N).filter(|&r| inactive(r)).collect();
    let tg: Vec<Vec<M31>> = (0..pairs)
        .map(|p| {
            let d: Vec<QM31> = (0..N).map(|r| traces[2 * p][16][r].sub(traces[2 * p + 1][16][r])).collect();
            flatten(&(1..95).map(|i| (0..N).fold(QM31::ZERO, |s, r| s.add(d[r].mul(cx.gr[r][i])))).collect::<Vec<_>>())
        })
        .collect();
    let zero = vec![QM31::ZERO; 271];
    let s = lane_stage(
        4 * rows.len(),
        |i| {
            let (r, k) = (rows[i / 4], i % 4);
            let x = tower(k);
            let b = sub_vec(&cx.batched(26, wq(x), r), &cx.batched(26, wq(x), 0), |p, q| p.sub(q));
            (flatten(&scale(&sub_vec(&cx.gr[r][1..], &cx.gr[0][1..], |p, q| p.sub(q)), x)), carry(b, &zero))
        },
        &tg,
        global,
    );
    for p in 0..pairs {
        for j in 0..TW {
            sol[p][j] = sol[p][j].add(s[p][j]);
        }
    }
    sol
}
/// Rows of `e` with pivot >= from, sliced to the round part [BW..].
fn slice_image(e: &Ech<M31>, from: usize) -> Ech<M31> {
    let mut out = Ech::new(RW);
    for (i, row) in e.p.iter().enumerate() {
        if let Some(v) = row {
            if i >= from {
                out.insert(v[BW..].to_vec());
            }
        }
    }
    out
}
/// Reduce by pivots < BW only (the batched coordinates).
fn batched_reduce(e: &Ech<M31>, mut v: Vec<M31>) -> Vec<M31> {
    for i in 0..BW {
        if v[i] == M31::ZERO {
            continue;
        }
        if let Some(b) = &e.p[i] {
            let s = v[i];
            for j in i..v.len() {
                v[j] = v[j].sub(s.mul(b[j]));
            }
        }
    }
    v
}
fn report(label: &str, kind: &str, total: usize, p: &Proj) {
    println!(
        "Z8C_RANKS {label} kind={kind} total={total} round_full={:?} round_limb={:?}",
        p.full_ranks(),
        p.limb_ranks()
    );
}

/// Direct check of the column-wise decomposition: for random words on lanes
/// 16 (F) and 27, 28 (K4), the Rust pipeline on whole columns (quotient per
/// lane, gamma-batched, round_polynomial with total weights, fold_message,
/// v_honest-style inactive sum) equals the sum of per-row batched vectors.
fn decomposition_check(cx: &Ctx, basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening, seed: u64) {
    let mut rng = Rng(seed);
    let mut q = [W::ZERO; 1024];
    let mut inactive_sum = W::ZERO;
    let mut expected = vec![W::ZERO; NB];
    for lane in [16usize, 27, 28] {
        let rows: [W; 1024] = std::array::from_fn(|_| if lane == 16 { wq(QM31::from_m31(rng.m())) } else { wq(rng.q()) });
        let coeffs = aspis_core::r0::transport::to_coefficients(&rows);
        let ql = prover::quotient(basis, z, &coeffs, ood_pair(&coeffs, z)).expect("column quotient");
        for i in 0..1024 {
            q[i] = q[i].add(cx.gpow[lane].mul(ql[i]));
        }
        for r in 0..N {
            if inactive(r) {
                inactive_sum = inactive_sum.add(cx.gpow[lane].mul(rows[r]));
            }
            for (e, b) in expected.iter_mut().zip(cx.batched(lane, rows[r], r)) {
                *e = e.add(b);
            }
        }
    }
    let rp = prover::round_polynomial(&q, total);
    let f = fold::fold_message(op.fold, &q);
    let mut direct = vec![inactive_sum];
    direct.extend_from_slice(&rp);
    direct.extend_from_slice(&f);
    assert_eq!(direct, expected, "column-wise decomposition");
    println!("Z8C_CHECK decomposition lanes=[16,27,28] whole_column_pipeline_equals_rowwise_sum=true coordinates={NB}");
}


// ---- Z8b helpers ---- (copied verbatim from z8b.rs)
use aspis_core::r0::transport::COEFFICIENT_TO_ROW;

const DW: usize = 376; // D's own-silence functionals: 94 K4-valued = 376 M31 limbs
const SW: usize = BW + DW + RW; // [batched | D own | round]

/// [batched limbs | D-own limbs | round limbs].
fn gen3(batched: Vec<W>, down: Vec<M31>, round: &[QM31]) -> Vec<M31> {
    let mut v = wflat(&batched);
    v.extend(down);
    v.extend(flatten(round));
    assert_eq!(v.len(), SW);
    v
}
fn d_own(cx: &Ctx, r: usize, x: QM31) -> Vec<M31> {
    flatten(&scale(&cx.gr[r][1..], x))
}
/// z8.rs `lane_stage` with the carry width taken from the source and the
/// kernel carries handed to `sink` (no targets).
fn lane_kernel(count: usize, mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>), mut sink: impl FnMut(Vec<M31>)) {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..c.len() {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => sink(c),
        }
    }
}
fn slice_from(e: &Ech<M31>, from: usize, offset: usize, width: usize) -> Ech<M31> {
    let mut out = Ech::new(width);
    for (i, row) in e.p.iter().enumerate() {
        if let (Some(v), true) = (row, i >= from) {
            out.insert(v[offset..].to_vec());
        }
    }
    out
}
fn rank_of(width: usize, vs: impl Iterator<Item = Vec<M31>>) -> usize {
    let mut e = Ech::new(width);
    for v in vs {
        e.insert(v);
    }
    e.rank
}
fn g_lane_coords(cx: &Ctx, r: usize, x: QM31, with_inactive: bool) -> Vec<M31> {
    let mut v = d_own(cx, r, x);
    if with_inactive {
        v.extend(if inactive(r) { limbs(x) } else { [M31::ZERO; 4] });
    }
    v
}


// ---- Z8c ----


fn in_k2(x: QM31) -> bool {
    x.c1 == CM31::new(M31::ZERO, M31::ZERO)
}
/// Good3 (design §1.2): at least three of alpha_0..alpha_3 outside K2.
fn good3(a: &[QM31; 10]) -> bool {
    (0..4).filter(|&i| !in_k2(a[i])).count() >= 3
}
const LANES: usize = 12; // mask-only 0..9 (phys 16..25), G (27), D (28)
fn lane_name(li: usize) -> String {
    match li {
        0..=9 => format!("m{li}_e{}", EXP[li]),
        10 => "G".into(),
        _ => "D".into(),
    }
}
fn phys(li: usize) -> usize {
    match li {
        0..=9 => 16 + li,
        10 => 27,
        _ => 28,
    }
}
fn per_row(li: usize) -> usize {
    if li < 10 { 1 } else { 4 }
}
fn own_width(li: usize) -> usize {
    if li < 10 { 112 } else { DW }
}
/// Own-functional blocks in limbs (same boundaries for F and K4 lanes):
/// claim0, claim1, claim2, extra, ood(2), opened(88).
fn own_blocks(li: usize) -> [(&'static str, usize, usize); 6] {
    [("claim0", 0, 4), ("claim1", 4, 8), ("claim2", 8, 12), ("extra", 12, 16), ("ood", 16, 24), ("opened", 24, own_width(li))]
}
type Src = (Vec<M31>, Vec<W>, Vec<QM31>); // (own limbs, batched NB values, round 271)
struct Lanes<'a> {
    cx: &'a Ctx,
    rr: Vec<Vec<Vec<QM31>>>, // [lane][row] unscaled round vector (round_row / tail_row)
    zero: Vec<Vec<Src>>,     // raw source at row 0, per lane and limb
}
impl<'a> Lanes<'a> {
    fn new(cx: &'a Ctx) -> Self {
        let a = cx.a;
        let rr: Vec<Vec<Vec<QM31>>> = std::thread::scope(|s| {
            let hs: Vec<_> = (0..LANES)
                .map(|li| {
                    s.spawn(move || {
                        (0..N)
                            .map(|r| if li == 11 { tail_row(&a, r) } else { round_row(&a, r, li) })
                            .collect::<Vec<_>>()
                    })
                })
                .collect();
            hs.into_iter().map(|h| h.join().unwrap()).collect()
        });
        let mut l = Lanes { cx, rr, zero: vec![] };
        l.zero = (0..LANES).map(|li| (0..per_row(li)).map(|k| l.raw(li, 0, k)).collect()).collect();
        l
    }
    /// Unbalanced unit source: value x (1 for F lanes, tower(k) for K4 lanes) at row r.
    fn raw(&self, li: usize, r: usize, k: usize) -> Src {
        let cx = self.cx;
        if li < 10 {
            (cx.br[r][1..].to_vec(), cx.batched(phys(li), W::ONE, r), self.rr[li][r].clone())
        } else {
            let x = tower(k);
            (d_own(cx, r, x), cx.batched(phys(li), wq(x), r), scale(&self.rr[li][r], x))
        }
    }
    fn count(&self, li: usize) -> usize {
        (N - 1) * per_row(li)
    }
    /// Balanced source i: row r = i / per_row + 1, limb i % per_row;
    /// e_r for active r, e_r - e_0 for inactive r (Lean `balance 0`).
    fn row_of(&self, li: usize, i: usize) -> (usize, usize) {
        (i / per_row(li) + 1, i % per_row(li))
    }
    fn bal(&self, li: usize, i: usize) -> Src {
        let (r, k) = self.row_of(li, i);
        let s = self.raw(li, r, k);
        if !inactive(r) {
            return s;
        }
        let z = &self.zero[li][k];
        (
            sub_vec(&s.0, &z.0, |x, y| x.sub(y)),
            sub_vec(&s.1, &z.1, |x, y| x.sub(y)),
            sub_vec(&s.2, &z.2, |x, y| x.sub(y)),
        )
    }
}

/// z8b `lane_kernel`, additionally returning the pivot rows (an echelon basis
/// of the image of the eliminated coordinates v).
fn lane_elim(count: usize, mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>), mut sink: impl FnMut(Vec<M31>)) -> Vec<Vec<M31>> {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..c.len() {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => sink(c),
        }
    }
    piv.into_iter().flatten().map(|(v, _)| v).collect()
}
fn ech_rows(e: &Ech<M31>) -> Vec<Vec<M31>> {
    e.p.iter().flatten().cloned().collect()
}
fn block_ranks(li: usize, carries: &[Vec<M31>]) -> Vec<(String, usize)> {
    let mut out = vec![("all".to_string(), rank_of(own_width(li), carries.iter().cloned()))];
    for (n, s, e) in own_blocks(li) {
        out.push((n.to_string(), rank_of(e - s, carries.iter().map(|c| c[s..e].to_vec()))));
    }
    out
}
fn fmt_ranks(v: &[(String, usize)]) -> String {
    v.iter().map(|(n, r)| format!("{n}:{r}")).collect::<Vec<_>>().join(",")
}

// Batched coordinate index: 0 = .inactiveSum, 1..=7 = .openingCoeff 0..6, 8.. = .finalCoeff 0..255.
fn bat_label(i: usize) -> String {
    match i {
        0 => "ia".into(),
        1..=7 => format!("h{}", i - 1),
        _ => format!("f{}", i - 8),
    }
}
fn wunit(m: usize) -> W {
    let mut l = [0u32; 8];
    l[m] = 1;
    W::from_limbs(l).unwrap()
}
fn wvals(limbs: &[M31]) -> Vec<W> {
    limbs.chunks(8).map(|c| W::from_limbs(std::array::from_fn(|i| c[i].0)).unwrap()).collect()
}
/// A K-linear relation on the batched coordinates: sum_i c_i * y_i.
struct Rel {
    name: String,
    c: Vec<(usize, W)>,
}
impl Rel {
    fn eval(&self, y: &[W]) -> W {
        self.c.iter().fold(W::ZERO, |s, (i, c)| s.add(c.mul(y[*i])))
    }
    /// The 8 F-functionals limb_k(sum c_i y_i) on the BW limb coordinates.
    fn limb_functionals(&self) -> Vec<Vec<M31>> {
        (0..8)
            .map(|k| {
                let mut v = vec![M31::ZERO; BW];
                for (i, c) in &self.c {
                    for m in 0..8 {
                        v[8 * i + m] = v[8 * i + m].add(M31(c.mul(wunit(m)).to_limbs()[k]));
                    }
                }
                v
            })
            .collect()
    }
}
/// (S1) check_v2 / round_eval, (S2) round_boundary (balanced form h0 + h4),
/// (S2u) unbalanced form h0 + h4 - quarter*ia, (S3_u) check_v1 / fold_encoded
/// at each queried fibre on own-silent tapes, the 14 low fold coordinates, and ia.
struct Relations {
    ia: Rel,
    s1: Rel,
    s2: Rel,
    s2u: Rel,
    s3: Vec<Rel>,
    low: Vec<Rel>,
}
fn relations(total: &[W; 1024], op: &Opening, qs: &[usize]) -> Relations {
    let quarter = fold::quarter::<W>();
    let df = fold::dual_fold(op.fold, total);
    let mut s1 = vec![];
    let mut p = W::ONE;
    for i in 0..7 {
        s1.push((1 + i, p));
        p = p.mul(op.fold);
    }
    for d in 0..256 {
        s1.push((8 + d, W::ZERO.sub(quarter.mul(df[d]))));
    }
    let s3 = qs
        .iter()
        .map(|&u| {
            let fib = FibreIndex::new(u).unwrap();
            let c = (0..256)
                .map(|d| {
                    let mut e = [W::ZERO; 256];
                    e[d] = W::ONE;
                    (8 + d, encoder::exact_final_encoder(&e, fib))
                })
                .collect();
            Rel { name: format!("S3_u{u}"), c }
        })
        .collect();
    Relations {
        ia: Rel { name: "ia".into(), c: vec![(0, W::ONE)] },
        s1: Rel { name: "S1".into(), c: s1 },
        s2: Rel { name: "S2".into(), c: vec![(1, W::ONE), (5, W::ONE)] },
        s2u: Rel { name: "S2u".into(), c: vec![(1, W::ONE), (5, W::ONE), (0, W::ZERO.sub(quarter))] },
        s3,
        low: (0..14).map(|d| Rel { name: format!("f{d}"), c: vec![(8 + d, W::ONE)] }).collect(),
    }
}
/// Null space of the row space of `img` (width BW) via back-substitution.
fn null_space(img: &Ech<M31>) -> Vec<Vec<M31>> {
    let n = img.p.len();
    let mut rows: Vec<Option<Vec<M31>>> = img.p.clone();
    let pivots: Vec<usize> = (0..n).filter(|&i| rows[i].is_some()).collect();
    for (pi, &i) in pivots.iter().enumerate().rev() {
        let ri = rows[i].clone().unwrap();
        for &j in &pivots[..pi] {
            let rj = rows[j].as_mut().unwrap();
            let s = rj[i];
            if s != M31::ZERO {
                for t in i..n {
                    rj[t] = rj[t].sub(s.mul(ri[t]));
                }
            }
        }
    }
    (0..n)
        .filter(|&f| rows[f].is_none())
        .map(|f| {
            let mut v = vec![M31::ZERO; n];
            v[f] = M31::ONE;
            for &p in &pivots {
                v[p] = M31::ZERO.sub(rows[p].as_ref().unwrap()[f]);
            }
            v
        })
        .collect()
}
fn support_labels(v: &[M31]) -> Vec<String> {
    let mut out = vec![];
    for i in 0..NB {
        let ls: Vec<usize> = (0..8).filter(|&m| v[8 * i + m] != M31::ZERO).collect();
        if !ls.is_empty() {
            out.push(format!("{}{:?}", bat_label(i), ls));
        }
    }
    out
}
/// Batched coordinate indices as compressed label ranges.
fn ranges(cs: &[usize]) -> String {
    let mut out = vec![];
    let mut i = 0;
    while i < cs.len() {
        let mut j = i;
        while j + 1 < cs.len() && cs[j + 1] == cs[j] + 1 {
            j += 1;
        }
        out.push(if i == j { bat_label(cs[i]) } else { format!("{}..{}", bat_label(cs[i]), bat_label(cs[j])) });
        i = j + 1;
    }
    format!("[{}]", out.join(","))
}
/// Ranks of a batched image projected to h, to f, and to the f-prefixes f[0..m).
fn projection_ranks(label: &str, kind: &str, img: &Ech<M31>) {
    let rows: Vec<Vec<M31>> = ech_rows(img);
    let h = rank_of(56, rows.iter().map(|r| r[8..64].to_vec()));
    let f = rank_of(2048, rows.iter().map(|r| r[64..].to_vec()));
    let pre: Vec<(usize, usize)> = [1usize, 2, 4, 8, 12, 13, 14, 15, 16, 20, 24, 32, 64, 128, 256]
        .iter()
        .map(|&m| (m, rank_of(8 * m, rows.iter().map(|r| r[64..64 + 8 * m].to_vec()))))
        .collect();
    println!("Z8C_PROJ {label} kind={kind} rank={} h_rank={h} f_rank={f} f_prefix_ranks={pre:?}", img.rank);
}
/// Left kernel of a batched image (Ech over BW limbs): which candidate
/// relations annihilate it, how much of the annihilator they explain, and the
/// supports of an echelon basis of the unexplained remainder.
fn left_kernel_report(label: &str, kind: &str, img: &Ech<M31>, cands: &[&Rel]) {
    let rows: Vec<Vec<W>> = img.p.iter().flatten().map(|r| wvals(r)).collect();
    let ann = BW - img.rank;
    let mut holds = vec![];
    let mut fails = vec![];
    let mut expl = Ech::new(BW);
    for c in cands {
        if rows.iter().all(|y| c.eval(y) == W::ZERO) {
            holds.push(c.name.clone());
            for f in c.limb_functionals() {
                expl.insert(f);
            }
        } else {
            let bad = rows.iter().filter(|y| c.eval(y) != W::ZERO).count();
            fails.push(format!("{}({bad})", c.name));
        }
    }
    println!(
        "Z8C_LEFT_KERNEL {label} kind={kind} image_rank={} annihilator_dim={ann} candidates={} holding={} failing={} explained_dim={} unexplained_dim={} failing_names={fails:?}",
        img.rank,
        cands.len(),
        holds.len(),
        fails.len(),
        expl.rank,
        ann - expl.rank
    );
    if expl.rank < ann {
        let mut rest = Ech::new(BW);
        let mut rest_rows = vec![];
        for nv in null_space(img) {
            let r = expl.residual(nv);
            if r.iter().any(|x| *x != M31::ZERO) {
                if rest.insert(r.clone()).is_some() {
                    rest_rows.push(r);
                }
            }
        }
        // Fully reduce the remainder basis (back-substitution) and print
        // supports as batched-coordinate ranges.
        let mut piv: Vec<usize> = rest_rows.iter().map(|r| r.iter().position(|x| *x != M31::ZERO).unwrap()).collect();
        let mut order: Vec<usize> = (0..rest_rows.len()).collect();
        order.sort_by_key(|&i| piv[i]);
        rest_rows = order.iter().map(|&i| rest_rows[i].clone()).collect();
        piv = order.iter().map(|&i| piv[i]).collect();
        for i in (0..rest_rows.len()).rev() {
            let ri = rest_rows[i].clone();
            for j in 0..rest_rows.len() {
                if j != i && rest_rows[j][piv[i]] != M31::ZERO {
                    let sc = rest_rows[j][piv[i]];
                    for t in 0..BW {
                        rest_rows[j][t] = rest_rows[j][t].sub(sc.mul(ri[t]));
                    }
                }
            }
        }
        let mut union = std::collections::BTreeSet::new();
        for (n, r) in rest_rows.iter().enumerate() {
            let cs: Vec<usize> = (0..NB).filter(|&i| (0..8).any(|m| r[8 * i + m] != M31::ZERO)).collect();
            union.extend(cs.iter().copied());
            if n < 16 || n + 4 >= rest_rows.len() {
                println!(
                    "Z8C_LEFT_KERNEL_REST {label} kind={kind} index={n} pivot={}:{} support={}",
                    bat_label(piv[n] / 8),
                    piv[n] % 8,
                    ranges(&cs)
                );
            }
        }
        let _ = support_labels;
        println!("Z8C_LEFT_KERNEL_REST_UNION {label} kind={kind} rank={} support={}", rest.rank, ranges(&union.into_iter().collect::<Vec<_>>()));
    }
}
/// Ech whose pivot order is the round-j coefficients from degree 27 down to
/// 0, all four limbs per degree; returns pivot degrees (one entry per limb pivot).
fn leading_degrees(polys: &[[QM31; 28]]) -> Vec<usize> {
    let mut e = Ech::new(112);
    for p in polys {
        let v: Vec<M31> = (0..28).rev().flat_map(|d| limbs(p[d])).collect();
        e.insert(v);
    }
    (0..112).filter(|&i| e.p[i].is_some()).map(|i| 27 - i / 4).collect()
}

pub(super) fn main() {
    let args: Vec<_> = std::env::args().collect();
    let get = |k: &str| args.windows(2).find(|x| x[0] == k).map(|x| x[1].clone());
    let s = get("--structure").expect("--structure");
    let v: usize = get("--vector").expect("--vector").parse().unwrap();
    let preflight = args.iter().any(|x| x == "--preflight");
    let start = Instant::now();
    println!("Z8C_START structure={s} vector={v} preflight={preflight} transport=D13 batching=WideExact balanced=true proxy=false");
    let t = trial(v);
    let a = alpha_for(&s, v, &t.a);
    let label = format!("structure={s} vector={v}");
    let op = opening_challenges(v);
    println!(
        "Z8C_ALPHA {label} alpha={:?} lambda_dims={:?} good3={} outside_k2={:?}",
        a.map(l4),
        lambda_dims(&a),
        good3(&a),
        (0..10).map(|i| !in_k2(a[i]) as u8).collect::<Vec<_>>()
    );
    println!(
        "Z8C_OPENING {label} gamma={:?} kappa={:?} tau={:?} fold={:?}",
        op.gamma.to_limbs(),
        op.kappa.to_limbs(),
        op.tau.to_limbs(),
        op.fold.to_limbs()
    );
    let basis = NaturalBasis::new(BasisSize::Initial).expect("basis");
    let z = [wpt(t.z[0]), wpt(t.z[1])];
    let total = total_weights(&basis, &a, z, &op);
    let phi = unit_functionals(&basis, z, &total, &op);
    println!("Z8C_CHECK unit_quotients=1024 ok=true eq_orientation=true seconds={:.3}", start.elapsed().as_secs_f64());
    let beta: Vec<[W; NB]> = (0..N)
        .map(|r| {
            let mut b = [W::ZERO; NB];
            b[0] = if inactive(r) { W::ONE } else { W::ZERO };
            b[1..].copy_from_slice(&phi[usize::from(ROW_TO_COEFFICIENT[r])]);
            b
        })
        .collect();
    let gpow = (0..29).map(|l| op.gamma.pow(l as u64)).collect();
    let (br, gr) = raw_c(&a, &t.z, &t.qs);
    let tail: Vec<_> = (0..N).map(|r| tail_row(&a, r)).collect();
    let cx = Ctx { a, br, gr, tail, beta, gpow };
    decomposition_check(&cx, &basis, z, &total, &op, 0x5a38_c0de ^ v as u64);
    // Transport / layout facts used below.
    assert!(inactive(0), "row 0 must be copy-inactive (balance 0)");
    for r in 0..N {
        assert_eq!(usize::from(ROW_TO_COEFFICIENT[r]), usize::from(z5::transport()[r]), "transport tables agree");
    }
    let rows_lo: Vec<usize> = (0..56).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    let rows_hi: Vec<usize> = (56..1024).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    let n_inactive = (0..N).filter(|&r| inactive(r)).count();
    println!(
        "Z8C_LAYOUT {label} inactive_rows={n_inactive} row0_coefficient={} rows_lo_all_inactive={} row0_in_rows_lo={} coeff_lt_89_all_inactive={}",
        ROW_TO_COEFFICIENT[0],
        rows_lo.iter().all(|&r| inactive(r)),
        rows_lo.contains(&0),
        (0..89).all(|k| inactive(usize::from(COEFFICIENT_TO_ROW[k])))
    );
    let rel = relations(&total, &op, &t.qs);
    let ln = Lanes::new(&cx);
    println!("Z8C_SETUP {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Pass 1: per-lane own kernels, carrying [batched | round]; global gate Ech. ----
    let mut pure = Ech::new(TW);
    let mut rker: Vec<Ech<M31>> = vec![];
    let mut own_rank = vec![];
    let mut kernel_dims = vec![];
    let mut rel_viol = [0usize; 4]; // ia, S1, S2, S3 (any u)
    let mut carries_checked = 0usize;
    for li in 0..LANES {
        let mut rk = Ech::new(RW);
        let mut ker = 0;
        let n = ln.count(li);
        lane_kernel(
            n,
            |i| {
                let (o, b, r) = ln.bal(li, i);
                (o, carry(b, &r))
            },
            |c| {
                ker += 1;
                let y = wvals(&c[..BW]);
                carries_checked += 1;
                if y[0] != W::ZERO {
                    rel_viol[0] += 1;
                }
                if rel.s1.eval(&y) != W::ZERO {
                    rel_viol[1] += 1;
                }
                if rel.s2.eval(&y) != W::ZERO {
                    rel_viol[2] += 1;
                }
                if rel.s3.iter().any(|r| r.eval(&y) != W::ZERO) {
                    rel_viol[3] += 1;
                }
                rk.insert(c[BW..].to_vec());
                pure.insert(c);
            },
        );
        own_rank.push(n - ker);
        kernel_dims.push(ker);
        println!(
            "Z8C_LANE_OWN {label} lane={} sources={n} own_rank={} own_functionals={} round_image_of_own_kernel={} seconds={:.3}",
            lane_name(li),
            n - ker,
            own_width(li),
            rk.rank,
            start.elapsed().as_secs_f64()
        );
        rker.push(rk);
    }
    let ia_pivots = (0..8).filter(|&i| pure.p[i].is_some()).count();
    let batched_rank = (0..BW).filter(|&i| pure.p[i].is_some()).count();
    println!(
        "Z8C_RELATIONS {label} carries_checked={carries_checked} violations_ia={} violations_S1={} violations_S2={} violations_S3={} relations_annihilate_exactly={}",
        rel_viol[0],
        rel_viol[1],
        rel_viol[2],
        rel_viol[3],
        rel_viol.iter().all(|x| *x == 0)
    );
    if rel_viol.iter().any(|x| *x != 0) {
        println!("STOP reason=verifier_relation_not_annihilating {label} violations={rel_viol:?}");
    }
    let retained = slice_image(&pure, BW);
    let silent = slice_image(&pure, BW + 4);
    // (2) dim R(ker own) = sum of per-lane own-kernel round images.
    let mut rown = Ech::new(RW);
    for rk in &rker {
        for row in ech_rows(rk) {
            rown.insert(row);
        }
    }
    let rown_zero = initial_zero(copied_ech(&rown));
    println!(
        "Z8C_GATE_PURE {label} span_rank={} batched_pivots={batched_rank} ia_pivots={ia_pivots} initial_retained_rank={} silent_rank={} upper_bound=1076 seconds={:.3}",
        pure.rank,
        retained.rank,
        silent.rank,
        start.elapsed().as_secs_f64()
    );
    println!(
        "Z8C_QPRIME {label} round_image_of_ker_own_initial_retained={} initial_zero={} expect=1080",
        rown.rank, rown_zero.rank
    );
    println!(
        "Z8C_B {label} bat_rank_on_ker_own={} bat_rank_on_ker_own_and_ker_R={} expect=1912 (second = span_rank - dim R(ker own) = {} - {})",
        batched_rank - ia_pivots,
        pure.rank - rown.rank,
        pure.rank,
        rown.rank
    );
    let psil = Proj::of(&silent, &a);
    report(&label, "silent", silent.rank, &psil);
    report(&label, "silent_initial_retained", retained.rank, &Proj::of(&retained, &a));
    report(&label, "round_image_of_ker_own", rown.rank, &Proj::of(&rown, &a));
    if silent.rank < 1076 {
        println!("Z8C_FINDING {label} balanced_silent_rank={} below=1076 deficit={}", silent.rank, 1076 - silent.rank);
    }
    let chain0: Vec<Vec<M31>> = (4..RW)
        .map(|i| {
            let mut u = vec![M31::ZERO; RW];
            u[i] = M31::ONE;
            let q = unflat(&u);
            let phi = final_value(&q, &a);
            flatten(&normalize_d(&q, phi, &a).expect("alpha9=1/2"))
        })
        .collect();
    summarize(&format!("{label} chain0_basis"), &silent, &chain0);
    summarize(&format!("{label} qprime_chain0_basis"), &rown_zero, &chain0);
    // (5a) left kernel of bat on ker own.
    {
        let mut img = Ech::new(BW);
        for row in pure.p.iter().take(BW).flatten() {
            img.insert(row[..BW].to_vec());
        }
        let mut c: Vec<&Rel> = vec![&rel.ia, &rel.s1, &rel.s2];
        c.extend(rel.s3.iter());
        left_kernel_report(&label, "bat_on_ker_own", &img, &c);
    }
    println!("Z8C_PASS1_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Pass 2: per lane, rounds first: rank R_l, own on ker R_l (OT_l). ----
    let mut rall = Ech::new(RW);
    for li in 0..LANES {
        let mut ker = vec![];
        let piv = lane_elim(
            ln.count(li),
            |i| {
                let (o, _, r) = ln.bal(li, i);
                (flatten(&r), o)
            },
            |c| ker.push(c),
        );
        for p in &piv {
            rall.insert(p.clone());
        }
        println!(
            "Z8C_LANE_OT {label} lane={} rank_R={} ker_R_dim={} own_on_ker_R=[{}]",
            lane_name(li),
            piv.len(),
            ker.len(),
            fmt_ranks(&block_ranks(li, &ker))
        );
    }
    println!("Z8C_R_ALL {label} rank_R_M_bal={} initial_zero={} expect=1084", rall.rank, initial_zero(copied_ech(&rall)).rank);
    // F5: claim_2 on ker R_{l,6} (full round-6 polynomial).
    for li in 0..LANES {
        let mut ker = vec![];
        lane_elim(
            ln.count(li),
            |i| {
                let (o, _, r) = ln.bal(li, i);
                (flatten(&round_polys(&r, &a)[6]), o[8..12].to_vec())
            },
            |c| ker.push(c),
        );
        println!(
            "Z8C_F5 {label} lane={} claim2_rank_on_ker_R6={} claim2_in_rowspace_R6={}",
            lane_name(li),
            rank_of(4, ker.iter().cloned()),
            rank_of(4, ker.iter().cloned()) == 0
        );
    }
    // OT': own on R_l^{-1}(V_{!=l}), V_{!=l} = sum of the other lanes' own-kernel round images.
    {
        let bases: Vec<Vec<Vec<M31>>> = rker.iter().map(ech_rows).collect();
        let mut prefix = vec![Ech::new(RW)];
        for li in 0..LANES {
            let mut e = copied_ech(&prefix[li]);
            for b in &bases[li] {
                e.insert(b.clone());
            }
            prefix.push(e);
        }
        let mut suffix = vec![Ech::new(RW)];
        for li in (0..LANES).rev() {
            let mut e = copied_ech(suffix.last().unwrap());
            for b in &bases[li] {
                e.insert(b.clone());
            }
            suffix.push(e);
        }
        suffix.reverse(); // suffix[i] = lanes i..
        for li in 0..LANES {
            let mut vne = copied_ech(&prefix[li]);
            for b in ech_rows(&suffix[li + 1]) {
                vne.insert(b);
            }
            let mut ker = vec![];
            lane_elim(
                ln.count(li),
                |i| {
                    let (o, _, r) = ln.bal(li, i);
                    (vne.residual(flatten(&r)), o)
                },
                |c| ker.push(c),
            );
            println!(
                "Z8C_LANE_OTPRIME {label} lane={} dim_V_other={} preimage_dim={} own_on_preimage=[{}]",
                lane_name(li),
                vne.rank,
                ker.len(),
                fmt_ranks(&block_ranks(li, &ker))
            );
        }
    }
    println!("Z8C_PASS2_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- (5b) D-high_bal, and Z8b's unbalanced (P) block. ----
    let mut dhigh_img: Option<Ech<M31>> = None;
    {
        let s0 = *rows_hi.iter().find(|&&r| inactive(r)).expect("an inactive D-high row");
        for &r in &rows_hi {
            assert!(ln.rr[11][r].iter().all(|x| *x == QM31::ZERO), "D coefficient >= 56 has a round contribution");
        }
        let mut srcs: Vec<(usize, usize, bool)> = vec![]; // (row, limb, subtract s0)
        for &r in &rows_hi {
            if r == s0 {
                continue;
            }
            for k in 0..4 {
                srcs.push((r, k, inactive(r)));
            }
        }
        let mut cands: Vec<&Rel> = vec![&rel.ia, &rel.s1, &rel.s2];
        cands.extend(rel.s3.iter());
        cands.extend(rel.low.iter());
        let mut img = Ech::new(BW);
        let own_piv = lane_elim(
            srcs.len(),
            |i| {
                let (r, k, sub) = srcs[i];
                let (o, b, _) = ln.raw(11, r, k);
                if sub {
                    let (o0, b0, _) = ln.raw(11, s0, k);
                    (sub_vec(&o, &o0, |x, y| x.sub(y)), wflat(&sub_vec(&b, &b0, |x, y| x.sub(y))))
                } else {
                    (o, wflat(&b))
                }
            },
            |c| {
                img.insert(c);
            },
        );
        println!(
            "Z8C_DHIGH_BAL {label} sources={} base_row={s0} own_rank={} bat_rank_on_ker_own_D={} expect=1800 ia_pivots={}",
            srcs.len(),
            own_piv.len(),
            img.rank,
            (0..8).filter(|&i| img.p[i].is_some()).count()
        );
        projection_ranks(&label, "dhigh_bal", &img);
        left_kernel_report(&label, "dhigh_bal", &img, &cands);
        dhigh_img = Some(img);
        // Z8b (P) block, unbalanced: every D row with coefficient >= 56.
        let mut up = Ech::new(BW);
        let own_up = lane_elim(
            rows_hi.len() * 4,
            |i| {
                let (o, b, _) = ln.raw(11, rows_hi[i / 4], i % 4);
                (o, wflat(&b))
            },
            |c| {
                up.insert(c);
            },
        );
        println!(
            "Z8C_DHIGH_UNBAL {label} sources={} own_rank={} bat_rank_on_ker_own_D={} z8b=1812 ia_pivots={}",
            rows_hi.len() * 4,
            own_up.len(),
            up.rank,
            (0..8).filter(|&i| up.p[i].is_some()).count()
        );
        let mut cu: Vec<&Rel> = vec![&rel.ia, &rel.s1, &rel.s2, &rel.s2u];
        cu.extend(rel.s3.iter());
        cu.extend(rel.low.iter());
        projection_ranks(&label, "dhigh_unbal_z8b_P", &up);
        left_kernel_report(&label, "dhigh_unbal_z8b_P", &up, &cu);
    }
    println!("Z8C_PASS5_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- (6) G-low: restriction of ker R_G ∩ ker own_G to rows pi^-1(0..55), and the low folds;
    // variant without G's extra claim; assembly of (B) from D-high_bal and G (ker R_G ∩ ker own_G). ----
    for (variant, drop_extra) in [("own_all", false), ("own_without_extra", true)] {
        let mut ker = vec![];
        lane_elim(
            ln.count(10),
            |i| {
                let (r, k) = ln.row_of(10, i);
                let (o, b, rd) = ln.bal(10, i);
                let mut vv: Vec<M31> = if drop_extra { o[..12].iter().chain(&o[16..]).copied().collect() } else { o };
                vv.extend(flatten(&rd));
                let x = tower(k);
                let mut c = vec![];
                for &lr in &rows_lo {
                    let mut val = QM31::ZERO;
                    if lr == r {
                        val = val.add(x);
                    }
                    if lr == 0 && inactive(r) {
                        val = val.sub(x);
                    }
                    c.extend(limbs(val));
                }
                c.extend(wflat(&b));
                (vv, c)
            },
            |c| ker.push(c),
        );
        let assembled = if drop_extra {
            String::new()
        } else {
            let mut e = copied_ech(dhigh_img.as_ref().unwrap());
            for c in &ker {
                e.insert(c[224..].to_vec());
            }
            let mut gonly = Ech::new(BW);
            for c in &ker {
                gonly.insert(c[224..].to_vec());
            }
            projection_ranks(&label, "glow_bat", &gonly);
            format!(" g_bat_rank={} dhigh_plus_g_bat_rank={} expect_bat_on_ker_own={}", gonly.rank, e.rank, batched_rank - ia_pivots)
        };
        println!(
            "Z8C_GLOW {label} variant={variant} kernel_dim={} low_rows_rank={} expect=224 low_fold_rank={} expect=112 joint_rank={}{assembled}",
            ker.len(),
            rank_of(224, ker.iter().map(|c| c[..224].to_vec())),
            rank_of(112, ker.iter().map(|c| c[224 + 64..224 + 64 + 112].to_vec())),
            rank_of(336, ker.iter().map(|c| c[..224 + 64 + 112].iter().enumerate().filter(|(j, _)| *j < 224 || *j >= 288).map(|(_, x)| *x).collect()))
        );
    }

    // ---- (7) PR6 / PR7 on G (unbalanced words in one prefix block; local statements). ----
    {
        let block6: Vec<usize> = (16..32).collect(); // prefix l' = 1 (6 bits), suffix s in {0,1}^4
        let block7: Vec<usize> = (16..24).collect(); // prefix l' = 2 (7 bits), suffix s in {0,1}^3
        let polys = |r: usize, k: usize| round_polys(&scale(&ln.rr[10][r], tower(k)), &a);
        let claim = |r: usize, k: usize, j: usize| flatten(&[cx.gr[r][1 + j].mul(tower(k))]);
        // Fresh-at-6 (rounds 7..9 zero): round-6 leading degrees, and deg <= 22 part with claim_2.
        let mut fresh = vec![];
        lane_kernel(
            64,
            |i| {
                let (r, k) = (block6[i / 4], i % 4);
                let p = polys(r, k);
                let v: Vec<M31> = (7..10).flat_map(|j| flatten(&p[j])).collect();
                let mut c = flatten(&p[6]);
                c.extend(claim(r, k, 2));
                (v, c)
            },
            |c| fresh.push(c),
        );
        let fresh_polys: Vec<[QM31; 28]> = fresh.iter().map(|c| std::array::from_fn(|d| unflat(&c[4 * d..4 * d + 4])[0])).collect();
        let mut low6 = vec![];
        lane_kernel(
            fresh.len(),
            |i| {
                let c = &fresh[i];
                (c[4 * 23..112].to_vec(), c[112..116].to_vec())
            },
            |c| low6.push(c),
        );
        println!(
            "Z8C_PR6 {label} fresh6_dim={} round6_leading_degrees={:?} deg_le_22_dim={} claim2_rank_on_deg_le_22={} pr6_holds={}",
            fresh.len(),
            leading_degrees(&fresh_polys),
            low6.len(),
            rank_of(4, low6.iter().cloned()),
            rank_of(4, low6.iter().cloned()) > 0
        );
        let mut all7 = vec![];
        let mut src7 = vec![];
        for i in 0..32 {
            let (r, k) = (block7[i / 4], i % 4);
            let p = polys(r, k);
            all7.push(p[7]);
            let mut c = flatten(&p[7]);
            c.extend(claim(r, k, 0));
            src7.push(c);
        }
        let mut low7 = vec![];
        lane_kernel(32, |i| (src7[i][4 * 23..112].to_vec(), src7[i][112..116].to_vec()), |c| low7.push(c));
        println!(
            "Z8C_PR7 {label} round7_dim={} round7_leading_degrees={:?} deg_le_22_dim={} claim0_rank_on_deg_le_22={} pr7_holds={}",
            rank_of(112, all7.iter().map(|p| flatten(p))),
            leading_degrees(&all7),
            low7.len(),
            rank_of(4, low7.iter().cloned()),
            rank_of(4, low7.iter().cloned()) > 0
        );
    }
    println!("Z8C_ITEMS_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());
    if preflight {
        println!("Z8C_PREFLIGHT_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
        return;
    }
    // ---- (i') and (ii') as Z8 (copied from z8.rs main, tags renamed). ----
    let (pubdata, instances) = real::instances();
    let ch = t.ch;
    let traces: Vec<Trace> = instances
        .iter()
        .map(|w| {
            let mut tr: Trace = w
                .compilation
                .semantic_c1
                .c1
                .iter()
                .map(|col| col.iter().map(|x| QM31::from_m31(*x)).collect())
                .collect();
            match build_pool_v1_pair_forest_copy_helper_v1(
                &w.compilation.trace,
                w.compilation.public_statement.live_snapshot.next_pair_index,
                ch.lambda,
                ch.chi,
            ) {
                Ok(h) => tr.push(h),
                Err(error) => {
                    println!("STOP reason=helper_pole_or_helper_abort {label} error={error:?}");
                    std::process::exit(22);
                }
            }
            balance_trace(&mut tr);
            tr
        })
        .collect();
    let mut targets = vec![];
    for pair in 0..5 {
        let mut noise = t.tapes[pair].clone();
        balance_trace(&mut noise);
        let public = Public::Transfer(&pubdata, &instances[2 * pair].compilation.public_statement);
        let original = compute_targets(public, &a, &ch, &traces[2 * pair], &traces[2 * pair + 1], &noise, pair);
        println!(
            "Z8C_TERMINAL {label} pair={pair} pinned={:?} derivative={:?} ii={:?}",
            l4(original.terminal[0]),
            l4(original.terminal[1]),
            l4(original.terminal[2])
        );
        targets.push(normalized(&original, &a, &traces[2 * pair], &traces[2 * pair + 1], &ch, public));
    }
    let i: Vec<_> = targets.iter().map(|t| flatten(&t.pinned)).collect();
    let derivative: Vec<_> = targets.iter().map(|t| flatten(&t.derivative)).collect();
    summarize(&format!("{label} wide_i_prime"), &silent, &i);
    summarize(&format!("{label} wide_derivative_diagnostic"), &silent, &derivative);
    let mut full = Ech { p: pure.p.clone(), rank: pure.rank };
    let sol = conditioned_sources(&cx, &traces, 5, &mut full);
    let conditioned = slice_image(&full, BW);
    let mut ii = vec![];
    let mut batched_unmatched = vec![];
    for p in 0..5 {
        let mut b = vec![W::ZERO; NB];
        for c in 0..17 {
            let lane = if c == 16 { 26 } else { c };
            for r in 0..N {
                let d = traces[2 * p][c][r].sub(traces[2 * p + 1][c][r]);
                if d == QM31::ZERO {
                    continue;
                }
                for (e, x) in b.iter_mut().zip(cx.batched(lane, wq(d), r)) {
                    *e = e.add(x);
                }
            }
        }
        let target = carry(b, &targets[p].difference);
        let residual = batched_reduce(&full, sub_vec(&target, &sol[p], |x, y| x.sub(y)));
        let unmatched = residual[..BW].iter().filter(|x| **x != M31::ZERO).count();
        batched_unmatched.push(unmatched);
        ii.push(residual[BW..].to_vec());
    }
    println!("Z8C_II_BATCHED {label} batched_coordinates_unmatched_per_pair={batched_unmatched:?}");
    summarize(&format!("{label} wide_ii_prime"), &conditioned, &ii);
    let ip = pass_count(&silent, &i);
    let iip = (0..5).filter(|&p| batched_unmatched[p] == 0 && conditioned.residual(ii[p].clone()).iter().all(|x| *x == M31::ZERO)).count();
    println!(
        "Z8C_GATE {label} silent_rank={} initial_retained_rank={} full_span_rank={} full_conditioned_rank={} i_pass={ip} ii_pass={iip} attempted=5",
        silent.rank,
        retained.rank,
        full.rank,
        conditioned.rank
    );
    println!("Z8C_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
}

//! Z8d (LOG "Lead acceptance of Z8c (2026-10-15); D21", item D21.6): the
//! coefficient basis of the D word and the x^28 law of design §2.5.1.
//! Exact M31/QM31/WideExact arithmetic. Not a Lean proof.
//!
//! Lean and Rust index an initial message by NATURAL-basis coefficients:
//! p0 = sum_j c[2j] N_j(x), p1 = sum_j c[2j+1] N_j(x), N_j = prod_{b in bits(j)}
//! T_{2^b}(x) (basis::values / encoder::eval_pair; Lean initialP0/initialP1 via
//! naturalCoefficientPolynomial). The design's §2.5.1 reads c as MONOMIAL
//! coefficients (even index 2i <-> x^i in p0). This module reruns Z8c's D-high
//! block with "p0, p1 divisible by X^28" (monomial degrees < 28 zero) beside
//! the Z8c natural control, and G-low in the same monomial coordinates.
//!
//! Everything from `use super::*` up to and including pass 1 of `main` is
//! z8c.rs copied verbatim with print tags renamed Z8C_ -> Z8D_. Pass 2, PR6/PR7
//! and (i')/(ii') are not run. New code follows `// ---- Z8d (0)`.
#![allow(dead_code)]
use super::*;
use aspis_core::field::WideExact as W;
use aspis_core::r0::{
    basis::{BasisSize, NaturalBasis},
    chord::{self, FunctionalWeights, Secant},
    encoder, fold, opening, prover,
    transport::ROW_TO_COEFFICIENT,
};

const MASTER: u64 = 0x5348f0b9a87835d0;
const STRUCT_SEED: u64 = 0x5a38_d20b_2026_1013;
const OPEN_SEED: u64 = 0x5a38_0be0_2026_1013;
const STRUCTURES: [&str; 7] = ["A", "B", "I", "J", "K", "L", "M"];
const NB: usize = 264; // inactiveSum + 7 openingCoeff + 256 finalCoeff
const BW: usize = NB * 8; // batched M31 coordinates
const RW: usize = 1084; // round coordinates (Z4c layout)
const TW: usize = BW + RW;
const THREADS: usize = 4;

struct Trial {
    a: [QM31; 10],
    z: [Point<QM31>; 2],
    qs: Vec<usize>,
    ch: Challenges,
    tapes: Vec<Trace>,
}
/// Exact replay of z4c_main's RNG consumption (copied from z7.rs `trial`).
fn trial(trial: usize) -> Trial {
    let trial_seed = MASTER.wrapping_add((trial as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15));
    let mut rng = Rng(trial_seed);
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()), circle(rng.q())];
    let sets = query_sets(&mut rng);
    let ch = Challenges {
        lambda: rng.q(),
        chi: rng.q(),
        theta: rng.q(),
        zc: std::array::from_fn(|_| rng.q()),
        mu: rng.q(),
        eta: rng.q(),
    };
    println!("TRIAL_SEED trial={trial} seed={trial_seed:#x}");
    println!("CHALLENGE trial={trial} alpha={a:?} semantic={ch:?} circle={z:?} queries={:?}", sets[0].1);
    let tapes = (0..5)
        .map(|_| {
            (0..17)
                .map(|c| {
                    (0..N)
                        .map(|r| {
                            if c < 16 && eligible(c, r) {
                                QM31::from_m31(rng.m())
                            } else if c == 16 && inactive(r) {
                                rng.q()
                            } else {
                                QM31::ZERO
                            }
                        })
                        .collect()
                })
                .collect()
        })
        .collect();
    Trial { a, z, qs: sets[0].1.clone(), ch, tapes }
}

fn l4(x: QM31) -> [u32; 4] {
    limbs(x).map(|v| v.0)
}
fn unflat(v: &[M31]) -> Vec<QM31> {
    v.chunks(4)
        .map(|c| QM31 { c0: CM31::new(c[0], c[1]), c1: CM31::new(c[2], c[3]) })
        .collect()
}
fn half() -> QM31 {
    QM31::from_m31(M31(2).inv())
}
fn admissible(a: &[QM31; 10]) -> bool {
    a.iter().all(|x| *x != QM31::ZERO && *x != QM31::ONE) && a[9] != half()
}
fn f_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31::from_m31(rng.m());
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
fn k2_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31 { c0: CM31::new(rng.m(), rng.m()), c1: CM31::new(M31::ZERO, M31::ZERO) };
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
/// A: Z4c alpha. B: all alpha_i in F\{0,1}. I: all alpha_i in K2 = F(i)\{0,1}.
/// J: alpha_0 Z4c (uniform in QM31), alpha_1..6 in F\{0,1}, alpha_7..9 Z4c.
/// Z8c additions (seeds of A, B, I, J unchanged: new structures are appended):
/// K: alpha_2, alpha_3 in F\{0,1}, others Z4c.  L: alpha_0..5 in F\{0,1},
/// alpha_6..9 Z4c (alpha_6 checked outside K2).  M: alpha_3..6 in F\{0,1}, others Z4c.
fn alpha_for(s: &str, v: usize, base: &[QM31; 10]) -> [QM31; 10] {
    let si = STRUCTURES.iter().position(|x| *x == s).unwrap() as u64;
    let mut rng = Rng(STRUCT_SEED.wrapping_add((si * 64 + v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let mut a = *base;
    match s {
        "A" => {}
        "B" => (0..10).for_each(|i| a[i] = f_nontrivial(&mut rng, i == 9)),
        "I" => (0..10).for_each(|i| a[i] = k2_nontrivial(&mut rng, i == 9)),
        "J" => (1..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        "K" => (2..4).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        "L" => {
            (0..6).for_each(|i| a[i] = f_nontrivial(&mut rng, false));
            assert!(!in_k2(a[6]), "structure L needs alpha_6 outside K2");
        }
        "M" => (3..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        _ => panic!("unknown structure {s}"),
    }
    assert!(admissible(&a), "alpha admissibility");
    a
}
fn lambda_dims(a: &[QM31; 10]) -> Vec<usize> {
    (0..10)
        .map(|j| {
            let mut e = Ech::new(4);
            for l in 0..1usize << j {
                let x = (0..j).fold(QM31::ONE, |v, i| {
                    v.mul(if l >> i & 1 == 1 { a[i] } else { QM31::ONE.sub(a[i]) })
                });
                e.insert(limbs(x).to_vec());
            }
            e.rank
        })
        .collect()
}

/// `last_coeff`'s chain reconstruction, returning all ten polys (copied from z7.rs).
fn round_polys(v: &[QM31], a: &[QM31; 10]) -> Vec<[QM31; 28]> {
    let mut prev = v[0];
    let mut out = vec![];
    for j in 0..10 {
        let mut co = [QM31::ZERO; 28];
        co[0] = v[1 + 27 * j];
        co[2..].copy_from_slice(&v[2 + 27 * j..28 + 27 * j]);
        co[1] = prev
            .sub(co[0].add(co[0]))
            .sub(co[2..].iter().fold(QM31::ZERO, |v, x| v.add(*x)));
        prev = co.iter().rev().fold(QM31::ZERO, |v, x| v.mul(a[j]).add(*x));
        out.push(co);
    }
    out
}
/// Per-round projection ranks (copied from z7.rs).
struct Proj {
    full: Vec<Ech<M31>>,
    limb: Vec<Vec<Ech<M31>>>,
}
impl Proj {
    fn of(e: &Ech<M31>, a: &[QM31; 10]) -> Self {
        let mut p = Proj {
            full: (0..10).map(|_| Ech::new(112)).collect(),
            limb: (0..10).map(|_| (0..4).map(|_| Ech::new(28)).collect()).collect(),
        };
        for b in e.p.iter().flatten() {
            for (j, co) in round_polys(&unflat(b), a).iter().enumerate() {
                p.full[j].insert(flatten(co));
                for k in 0..4 {
                    p.limb[j][k].insert(co.iter().map(|x| limbs(*x)[k]).collect());
                }
            }
        }
        p
    }
    fn full_ranks(&self) -> Vec<usize> {
        self.full.iter().map(|e| e.rank).collect()
    }
    fn limb_ranks(&self) -> Vec<[usize; 4]> {
        self.limb.iter().map(|l| std::array::from_fn(|k| l[k].rank)).collect()
    }
}

fn wq(x: QM31) -> W {
    W::from_qm31(x)
}
fn wlimbs(x: W) -> [M31; 8] {
    x.to_limbs().map(M31)
}
fn wpt(p: Point<QM31>) -> Point<W> {
    Point { x: wq(p.x), y: wq(p.y) }
}
fn w_uniform(rng: &mut Rng) -> W {
    W::new(rng.q(), rng.q())
}
struct Opening {
    gamma: W,
    kappa: W,
    tau: W,
    fold: W,
}
/// ch.opening 0..3, uniform in WideExact; one stream per vector (shared by
/// all structures of that vector); gamma resampled at zero as the sampler does.
fn opening_challenges(v: usize) -> Opening {
    let mut rng = Rng(OPEN_SEED.wrapping_add((v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let gamma = loop {
        let g = w_uniform(&mut rng);
        if g != W::ZERO {
            break g;
        }
    };
    Opening { gamma, kappa: w_uniform(&mut rng), tau: w_uniform(&mut rng), fold: w_uniform(&mut rng) }
}

/// Lean `totalWeights` with Lean `weights` (Rust OpeningData::weights + kappa^4 libraWeight).
fn total_weights(basis: &NaturalBasis, a: &[QM31; 10], z: [Point<W>; 2], op: &Opening) -> [W; 1024] {
    let aw = a.map(wq);
    let pts = opening::points_from_alphas(&aw);
    // Orientation check: Rust row_eq_weight(points_from_alphas) == Z4c eq(points).
    let zp = points(a);
    for j in 0..3 {
        let rw = opening::row_eq_weight(&pts[j]);
        for r in 0..N {
            assert_eq!(rw[r], wq(eq(&zp[j], r)), "eq orientation j={j} r={r}");
        }
    }
    let eqs = pts.map(|p| opening::eq_weight(&p));
    let ind = opening::indicator();
    let k = opening::powers::<5>(op.kappa);
    let w: [W; 1024] = std::array::from_fn(|j| {
        ind[j]
            .add(k[1].mul(eqs[0][j]))
            .add(k[2].mul(eqs[1][j]))
            .add(k[3].mul(eqs[2][j]))
            .add(k[4].mul(wq(h_weight(a, j))))
    });
    let line = Secant::from_points(z[0], z[1]);
    let qw = chord::quotient_weights(basis, line, &w).expect("quotient_weights");
    let e1 = FunctionalWeights::e1::<W>(basis).expect("e1");
    let e2 = FunctionalWeights::e2(basis, line.b, line.c).expect("e2");
    std::array::from_fn(|j| qw[j].add(op.tau.mul(e1[j])).add(op.tau.mul(op.tau).mul(e2[j])))
}
fn ood_pair(m: &[W; 1024], z: [Point<W>; 2]) -> [W; 2] {
    [encoder::eval_message(m, z[0]), encoder::eval_message(m, z[1])]
}
/// phi[k] = (round_polynomial(Q e_k, total) [7], fold_message(op.fold, Q e_k) [256])
/// for every natural coefficient unit e_k (Q = prover::quotient, column-wise).
fn unit_functionals(basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening) -> Vec<[W; NB - 1]> {
    let ks: Vec<usize> = (0..1024).collect();
    let chunk = ks.len().div_ceil(THREADS);
    std::thread::scope(|s| {
        let hs: Vec<_> = ks
            .chunks(chunk)
            .map(|part| {
                s.spawn(move || {
                    part.iter()
                        .map(|&k| {
                            let mut e = [W::ZERO; 1024];
                            e[k] = W::ONE;
                            let q = prover::quotient(basis, z, &e, ood_pair(&e, z))
                                .unwrap_or_else(|err| panic!("STOP quotient unit k={k} error={err:?}"));
                            let rp = prover::round_polynomial(&q, total);
                            let f = fold::fold_message(op.fold, &q);
                            let mut out = [W::ZERO; NB - 1];
                            out[..7].copy_from_slice(&rp);
                            out[7..].copy_from_slice(&f);
                            out
                        })
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
    })
}

struct Ctx {
    a: [QM31; 10],
    br: Vec<Vec<M31>>,
    gr: Vec<Vec<QM31>>,
    tail: Vec<Vec<QM31>>,
    beta: Vec<[W; NB]>, // row-indexed
    gpow: Vec<W>,       // gamma^lane, lane 0..28
}
impl Ctx {
    /// Batched payload of x at row r of physical lane `lane`.
    fn batched(&self, lane: usize, x: W, r: usize) -> Vec<W> {
        let g = self.gpow[lane].mul(x);
        self.beta[r].iter().map(|b| g.mul(*b)).collect()
    }
}
fn wflat(v: &[W]) -> Vec<M31> {
    v.iter().flat_map(|x| wlimbs(*x)).collect()
}
fn sub_vec<T: Copy>(a: &[T], b: &[T], f: impl Fn(T, T) -> T) -> Vec<T> {
    a.iter().zip(b).map(|(x, y)| f(*x, *y)).collect()
}

/// One lane's sources, eliminated on its own per-lane coordinates (as Z4c's
/// lane_eliminate does), carrying [batched (2112) | round (1084)] in M31.
/// Kernel carries are inserted into `global`; returns the carried particular
/// solution for each per-lane target (which must lie in the lane's coordinate span).
fn lane_stage(
    count: usize,
    mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>),
    targets: &[Vec<M31>],
    global: &mut Ech<M31>,
) -> Vec<Vec<M31>> {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => {
                global.insert(c);
            }
        }
    }
    targets
        .iter()
        .map(|t| {
            let mut v = t.clone();
            let mut out = vec![M31::ZERO; TW];
            for i in 0..v.len() {
                if v[i] == M31::ZERO {
                    continue;
                }
                let (b, bc) = piv[i].as_ref().expect("per-lane target outside lane coordinate span");
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    out[j] = out[j].add(s.mul(bc[j]));
                }
            }
            out
        })
        .collect()
}
fn carry(batched: Vec<W>, round: &[QM31]) -> Vec<M31> {
    let mut c = wflat(&batched);
    c.extend(flatten(round));
    debug_assert_eq!(c.len(), TW);
    c
}
fn scale(v: &[QM31], x: QM31) -> Vec<QM31> {
    v.iter().map(|y| y.mul(x)).collect()
}
/// Mask-only lanes (F, all rows), G (K4, all rows) and D (K4, all rows).
fn pure_sources(cx: &Ctx, global: &mut Ech<M31>) {
    let a = &cx.a;
    for c in 0..10 {
        let lane = 16 + c;
        lane_stage(N, |r| (cx.br[r][1..].to_vec(), carry(cx.batched(lane, W::ONE, r), &round_row(a, r, c))), &[], global);
    }
    for (lane, g) in [(27usize, true), (28, false)] {
        lane_stage(
            4 * N,
            |i| {
                let (r, k) = (i / 4, i % 4);
                let x = tower(k);
                let rr = if g { round_row(a, r, 10) } else { cx.tail[r].clone() };
                (flatten(&scale(&cx.gr[r][1..], x)), carry(cx.batched(lane, wq(x), r), &scale(&rr, x)))
            },
            &[],
            global,
        );
    }
}
/// Semantic eligible sources (balanced vs row 1023) and H1 padding (inactive
/// rows, balanced vs row 0), with the per-pair witness-difference targets.
fn conditioned_sources(cx: &Ctx, traces: &[Trace], pairs: usize, global: &mut Ech<M31>) -> Vec<Vec<M31>> {
    let a = &cx.a;
    let mut sol = vec![vec![M31::ZERO; TW]; pairs];
    for c in 0..16 {
        let rows: Vec<usize> = (0..N).filter(|&r| r != 1023 && eligible(c, r)).collect();
        let tg: Vec<Vec<M31>> = (0..pairs)
            .map(|p| {
                let d: Vec<M31> = (0..N).map(|r| traces[2 * p][c][r].c0.a.sub(traces[2 * p + 1][c][r].c0.a)).collect();
                (1..113).map(|i| (0..N).fold(M31::ZERO, |s, r| s.add(d[r].mul(cx.br[r][i])))).collect()
            })
            .collect();
        let rd = round_row(a, 1023, 38 + c);
        let bd = cx.batched(c, W::ONE, 1023);
        let s = lane_stage(
            rows.len(),
            |i| {
                let r = rows[i];
                let rr = round_row(a, r, 38 + c);
                let bb = cx.batched(c, W::ONE, r);
                if inactive(r) {
                    (
                        sub_vec(&cx.br[r][1..], &cx.br[1023][1..], |x, y| x.sub(y)),
                        carry(sub_vec(&bb, &bd, |x, y| x.sub(y)), &sub_vec(&rr, &rd, |x, y| x.sub(y))),
                    )
                } else {
                    (cx.br[r][1..].to_vec(), carry(bb, &rr))
                }
            },
            &tg,
            global,
        );
        for p in 0..pairs {
            for j in 0..TW {
                sol[p][j] = sol[p][j].add(s[p][j]);
            }
        }
    }
    let rows: Vec<usize> = (1..N).filter(|&r| inactive(r)).collect();
    let tg: Vec<Vec<M31>> = (0..pairs)
        .map(|p| {
            let d: Vec<QM31> = (0..N).map(|r| traces[2 * p][16][r].sub(traces[2 * p + 1][16][r])).collect();
            flatten(&(1..95).map(|i| (0..N).fold(QM31::ZERO, |s, r| s.add(d[r].mul(cx.gr[r][i])))).collect::<Vec<_>>())
        })
        .collect();
    let zero = vec![QM31::ZERO; 271];
    let s = lane_stage(
        4 * rows.len(),
        |i| {
            let (r, k) = (rows[i / 4], i % 4);
            let x = tower(k);
            let b = sub_vec(&cx.batched(26, wq(x), r), &cx.batched(26, wq(x), 0), |p, q| p.sub(q));
            (flatten(&scale(&sub_vec(&cx.gr[r][1..], &cx.gr[0][1..], |p, q| p.sub(q)), x)), carry(b, &zero))
        },
        &tg,
        global,
    );
    for p in 0..pairs {
        for j in 0..TW {
            sol[p][j] = sol[p][j].add(s[p][j]);
        }
    }
    sol
}
/// Rows of `e` with pivot >= from, sliced to the round part [BW..].
fn slice_image(e: &Ech<M31>, from: usize) -> Ech<M31> {
    let mut out = Ech::new(RW);
    for (i, row) in e.p.iter().enumerate() {
        if let Some(v) = row {
            if i >= from {
                out.insert(v[BW..].to_vec());
            }
        }
    }
    out
}
/// Reduce by pivots < BW only (the batched coordinates).
fn batched_reduce(e: &Ech<M31>, mut v: Vec<M31>) -> Vec<M31> {
    for i in 0..BW {
        if v[i] == M31::ZERO {
            continue;
        }
        if let Some(b) = &e.p[i] {
            let s = v[i];
            for j in i..v.len() {
                v[j] = v[j].sub(s.mul(b[j]));
            }
        }
    }
    v
}
fn report(label: &str, kind: &str, total: usize, p: &Proj) {
    println!(
        "Z8D_RANKS {label} kind={kind} total={total} round_full={:?} round_limb={:?}",
        p.full_ranks(),
        p.limb_ranks()
    );
}

/// Direct check of the column-wise decomposition: for random words on lanes
/// 16 (F) and 27, 28 (K4), the Rust pipeline on whole columns (quotient per
/// lane, gamma-batched, round_polynomial with total weights, fold_message,
/// v_honest-style inactive sum) equals the sum of per-row batched vectors.
fn decomposition_check(cx: &Ctx, basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening, seed: u64) {
    let mut rng = Rng(seed);
    let mut q = [W::ZERO; 1024];
    let mut inactive_sum = W::ZERO;
    let mut expected = vec![W::ZERO; NB];
    for lane in [16usize, 27, 28] {
        let rows: [W; 1024] = std::array::from_fn(|_| if lane == 16 { wq(QM31::from_m31(rng.m())) } else { wq(rng.q()) });
        let coeffs = aspis_core::r0::transport::to_coefficients(&rows);
        let ql = prover::quotient(basis, z, &coeffs, ood_pair(&coeffs, z)).expect("column quotient");
        for i in 0..1024 {
            q[i] = q[i].add(cx.gpow[lane].mul(ql[i]));
        }
        for r in 0..N {
            if inactive(r) {
                inactive_sum = inactive_sum.add(cx.gpow[lane].mul(rows[r]));
            }
            for (e, b) in expected.iter_mut().zip(cx.batched(lane, rows[r], r)) {
                *e = e.add(b);
            }
        }
    }
    let rp = prover::round_polynomial(&q, total);
    let f = fold::fold_message(op.fold, &q);
    let mut direct = vec![inactive_sum];
    direct.extend_from_slice(&rp);
    direct.extend_from_slice(&f);
    assert_eq!(direct, expected, "column-wise decomposition");
    println!("Z8D_CHECK decomposition lanes=[16,27,28] whole_column_pipeline_equals_rowwise_sum=true coordinates={NB}");
}


// ---- Z8b helpers ---- (copied verbatim from z8b.rs)
use aspis_core::r0::transport::COEFFICIENT_TO_ROW;

const DW: usize = 376; // D's own-silence functionals: 94 K4-valued = 376 M31 limbs
const SW: usize = BW + DW + RW; // [batched | D own | round]

/// [batched limbs | D-own limbs | round limbs].
fn gen3(batched: Vec<W>, down: Vec<M31>, round: &[QM31]) -> Vec<M31> {
    let mut v = wflat(&batched);
    v.extend(down);
    v.extend(flatten(round));
    assert_eq!(v.len(), SW);
    v
}
fn d_own(cx: &Ctx, r: usize, x: QM31) -> Vec<M31> {
    flatten(&scale(&cx.gr[r][1..], x))
}
/// z8.rs `lane_stage` with the carry width taken from the source and the
/// kernel carries handed to `sink` (no targets).
fn lane_kernel(count: usize, mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>), mut sink: impl FnMut(Vec<M31>)) {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..c.len() {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => sink(c),
        }
    }
}
fn slice_from(e: &Ech<M31>, from: usize, offset: usize, width: usize) -> Ech<M31> {
    let mut out = Ech::new(width);
    for (i, row) in e.p.iter().enumerate() {
        if let (Some(v), true) = (row, i >= from) {
            out.insert(v[offset..].to_vec());
        }
    }
    out
}
fn rank_of(width: usize, vs: impl Iterator<Item = Vec<M31>>) -> usize {
    let mut e = Ech::new(width);
    for v in vs {
        e.insert(v);
    }
    e.rank
}
fn g_lane_coords(cx: &Ctx, r: usize, x: QM31, with_inactive: bool) -> Vec<M31> {
    let mut v = d_own(cx, r, x);
    if with_inactive {
        v.extend(if inactive(r) { limbs(x) } else { [M31::ZERO; 4] });
    }
    v
}


// ---- Z8c ----


fn in_k2(x: QM31) -> bool {
    x.c1 == CM31::new(M31::ZERO, M31::ZERO)
}
/// Good3 (design §1.2): at least three of alpha_0..alpha_3 outside K2.
fn good3(a: &[QM31; 10]) -> bool {
    (0..4).filter(|&i| !in_k2(a[i])).count() >= 3
}
const LANES: usize = 12; // mask-only 0..9 (phys 16..25), G (27), D (28)
fn lane_name(li: usize) -> String {
    match li {
        0..=9 => format!("m{li}_e{}", EXP[li]),
        10 => "G".into(),
        _ => "D".into(),
    }
}
fn phys(li: usize) -> usize {
    match li {
        0..=9 => 16 + li,
        10 => 27,
        _ => 28,
    }
}
fn per_row(li: usize) -> usize {
    if li < 10 { 1 } else { 4 }
}
fn own_width(li: usize) -> usize {
    if li < 10 { 112 } else { DW }
}
/// Own-functional blocks in limbs (same boundaries for F and K4 lanes):
/// claim0, claim1, claim2, extra, ood(2), opened(88).
fn own_blocks(li: usize) -> [(&'static str, usize, usize); 6] {
    [("claim0", 0, 4), ("claim1", 4, 8), ("claim2", 8, 12), ("extra", 12, 16), ("ood", 16, 24), ("opened", 24, own_width(li))]
}
type Src = (Vec<M31>, Vec<W>, Vec<QM31>); // (own limbs, batched NB values, round 271)
struct Lanes<'a> {
    cx: &'a Ctx,
    rr: Vec<Vec<Vec<QM31>>>, // [lane][row] unscaled round vector (round_row / tail_row)
    zero: Vec<Vec<Src>>,     // raw source at row 0, per lane and limb
}
impl<'a> Lanes<'a> {
    fn new(cx: &'a Ctx) -> Self {
        let a = cx.a;
        let rr: Vec<Vec<Vec<QM31>>> = std::thread::scope(|s| {
            let hs: Vec<_> = (0..LANES)
                .map(|li| {
                    s.spawn(move || {
                        (0..N)
                            .map(|r| if li == 11 { tail_row(&a, r) } else { round_row(&a, r, li) })
                            .collect::<Vec<_>>()
                    })
                })
                .collect();
            hs.into_iter().map(|h| h.join().unwrap()).collect()
        });
        let mut l = Lanes { cx, rr, zero: vec![] };
        l.zero = (0..LANES).map(|li| (0..per_row(li)).map(|k| l.raw(li, 0, k)).collect()).collect();
        l
    }
    /// Unbalanced unit source: value x (1 for F lanes, tower(k) for K4 lanes) at row r.
    fn raw(&self, li: usize, r: usize, k: usize) -> Src {
        let cx = self.cx;
        if li < 10 {
            (cx.br[r][1..].to_vec(), cx.batched(phys(li), W::ONE, r), self.rr[li][r].clone())
        } else {
            let x = tower(k);
            (d_own(cx, r, x), cx.batched(phys(li), wq(x), r), scale(&self.rr[li][r], x))
        }
    }
    fn count(&self, li: usize) -> usize {
        (N - 1) * per_row(li)
    }
    /// Balanced source i: row r = i / per_row + 1, limb i % per_row;
    /// e_r for active r, e_r - e_0 for inactive r (Lean `balance 0`).
    fn row_of(&self, li: usize, i: usize) -> (usize, usize) {
        (i / per_row(li) + 1, i % per_row(li))
    }
    fn bal(&self, li: usize, i: usize) -> Src {
        let (r, k) = self.row_of(li, i);
        let s = self.raw(li, r, k);
        if !inactive(r) {
            return s;
        }
        let z = &self.zero[li][k];
        (
            sub_vec(&s.0, &z.0, |x, y| x.sub(y)),
            sub_vec(&s.1, &z.1, |x, y| x.sub(y)),
            sub_vec(&s.2, &z.2, |x, y| x.sub(y)),
        )
    }
}

/// z8b `lane_kernel`, additionally returning the pivot rows (an echelon basis
/// of the image of the eliminated coordinates v).
fn lane_elim(count: usize, mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>), mut sink: impl FnMut(Vec<M31>)) -> Vec<Vec<M31>> {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..c.len() {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => sink(c),
        }
    }
    piv.into_iter().flatten().map(|(v, _)| v).collect()
}
fn ech_rows(e: &Ech<M31>) -> Vec<Vec<M31>> {
    e.p.iter().flatten().cloned().collect()
}
fn block_ranks(li: usize, carries: &[Vec<M31>]) -> Vec<(String, usize)> {
    let mut out = vec![("all".to_string(), rank_of(own_width(li), carries.iter().cloned()))];
    for (n, s, e) in own_blocks(li) {
        out.push((n.to_string(), rank_of(e - s, carries.iter().map(|c| c[s..e].to_vec()))));
    }
    out
}
fn fmt_ranks(v: &[(String, usize)]) -> String {
    v.iter().map(|(n, r)| format!("{n}:{r}")).collect::<Vec<_>>().join(",")
}

// Batched coordinate index: 0 = .inactiveSum, 1..=7 = .openingCoeff 0..6, 8.. = .finalCoeff 0..255.
fn bat_label(i: usize) -> String {
    match i {
        0 => "ia".into(),
        1..=7 => format!("h{}", i - 1),
        _ => format!("f{}", i - 8),
    }
}
fn wunit(m: usize) -> W {
    let mut l = [0u32; 8];
    l[m] = 1;
    W::from_limbs(l).unwrap()
}
fn wvals(limbs: &[M31]) -> Vec<W> {
    limbs.chunks(8).map(|c| W::from_limbs(std::array::from_fn(|i| c[i].0)).unwrap()).collect()
}
/// A K-linear relation on the batched coordinates: sum_i c_i * y_i.
struct Rel {
    name: String,
    c: Vec<(usize, W)>,
}
impl Rel {
    fn eval(&self, y: &[W]) -> W {
        self.c.iter().fold(W::ZERO, |s, (i, c)| s.add(c.mul(y[*i])))
    }
    /// The 8 F-functionals limb_k(sum c_i y_i) on the BW limb coordinates.
    fn limb_functionals(&self) -> Vec<Vec<M31>> {
        (0..8)
            .map(|k| {
                let mut v = vec![M31::ZERO; BW];
                for (i, c) in &self.c {
                    for m in 0..8 {
                        v[8 * i + m] = v[8 * i + m].add(M31(c.mul(wunit(m)).to_limbs()[k]));
                    }
                }
                v
            })
            .collect()
    }
}
/// (S1) check_v2 / round_eval, (S2) round_boundary (balanced form h0 + h4),
/// (S2u) unbalanced form h0 + h4 - quarter*ia, (S3_u) check_v1 / fold_encoded
/// at each queried fibre on own-silent tapes, the 14 low fold coordinates, and ia.
struct Relations {
    ia: Rel,
    s1: Rel,
    s2: Rel,
    s2u: Rel,
    s3: Vec<Rel>,
    low: Vec<Rel>,
}
fn relations(total: &[W; 1024], op: &Opening, qs: &[usize]) -> Relations {
    let quarter = fold::quarter::<W>();
    let df = fold::dual_fold(op.fold, total);
    let mut s1 = vec![];
    let mut p = W::ONE;
    for i in 0..7 {
        s1.push((1 + i, p));
        p = p.mul(op.fold);
    }
    for d in 0..256 {
        s1.push((8 + d, W::ZERO.sub(quarter.mul(df[d]))));
    }
    let s3 = qs
        .iter()
        .map(|&u| {
            let fib = FibreIndex::new(u).unwrap();
            let c = (0..256)
                .map(|d| {
                    let mut e = [W::ZERO; 256];
                    e[d] = W::ONE;
                    (8 + d, encoder::exact_final_encoder(&e, fib))
                })
                .collect();
            Rel { name: format!("S3_u{u}"), c }
        })
        .collect();
    Relations {
        ia: Rel { name: "ia".into(), c: vec![(0, W::ONE)] },
        s1: Rel { name: "S1".into(), c: s1 },
        s2: Rel { name: "S2".into(), c: vec![(1, W::ONE), (5, W::ONE)] },
        s2u: Rel { name: "S2u".into(), c: vec![(1, W::ONE), (5, W::ONE), (0, W::ZERO.sub(quarter))] },
        s3,
        low: (0..14).map(|d| Rel { name: format!("f{d}"), c: vec![(8 + d, W::ONE)] }).collect(),
    }
}
/// Null space of the row space of `img` (width BW) via back-substitution.
fn null_space(img: &Ech<M31>) -> Vec<Vec<M31>> {
    let n = img.p.len();
    let mut rows: Vec<Option<Vec<M31>>> = img.p.clone();
    let pivots: Vec<usize> = (0..n).filter(|&i| rows[i].is_some()).collect();
    for (pi, &i) in pivots.iter().enumerate().rev() {
        let ri = rows[i].clone().unwrap();
        for &j in &pivots[..pi] {
            let rj = rows[j].as_mut().unwrap();
            let s = rj[i];
            if s != M31::ZERO {
                for t in i..n {
                    rj[t] = rj[t].sub(s.mul(ri[t]));
                }
            }
        }
    }
    (0..n)
        .filter(|&f| rows[f].is_none())
        .map(|f| {
            let mut v = vec![M31::ZERO; n];
            v[f] = M31::ONE;
            for &p in &pivots {
                v[p] = M31::ZERO.sub(rows[p].as_ref().unwrap()[f]);
            }
            v
        })
        .collect()
}
fn support_labels(v: &[M31]) -> Vec<String> {
    let mut out = vec![];
    for i in 0..NB {
        let ls: Vec<usize> = (0..8).filter(|&m| v[8 * i + m] != M31::ZERO).collect();
        if !ls.is_empty() {
            out.push(format!("{}{:?}", bat_label(i), ls));
        }
    }
    out
}
/// Batched coordinate indices as compressed label ranges.
fn ranges(cs: &[usize]) -> String {
    let mut out = vec![];
    let mut i = 0;
    while i < cs.len() {
        let mut j = i;
        while j + 1 < cs.len() && cs[j + 1] == cs[j] + 1 {
            j += 1;
        }
        out.push(if i == j { bat_label(cs[i]) } else { format!("{}..{}", bat_label(cs[i]), bat_label(cs[j])) });
        i = j + 1;
    }
    format!("[{}]", out.join(","))
}
/// Ranks of a batched image projected to h, to f, and to the f-prefixes f[0..m).
fn projection_ranks(label: &str, kind: &str, img: &Ech<M31>) {
    let rows: Vec<Vec<M31>> = ech_rows(img);
    let h = rank_of(56, rows.iter().map(|r| r[8..64].to_vec()));
    let f = rank_of(2048, rows.iter().map(|r| r[64..].to_vec()));
    let pre: Vec<(usize, usize)> = [1usize, 2, 4, 8, 12, 13, 14, 15, 16, 20, 24, 32, 64, 128, 256]
        .iter()
        .map(|&m| (m, rank_of(8 * m, rows.iter().map(|r| r[64..64 + 8 * m].to_vec()))))
        .collect();
    println!("Z8D_PROJ {label} kind={kind} rank={} h_rank={h} f_rank={f} f_prefix_ranks={pre:?}", img.rank);
}
/// Left kernel of a batched image (Ech over BW limbs): which candidate
/// relations annihilate it, how much of the annihilator they explain, and the
/// supports of an echelon basis of the unexplained remainder.
fn left_kernel_report(label: &str, kind: &str, img: &Ech<M31>, cands: &[&Rel]) {
    let rows: Vec<Vec<W>> = img.p.iter().flatten().map(|r| wvals(r)).collect();
    let ann = BW - img.rank;
    let mut holds = vec![];
    let mut fails = vec![];
    let mut expl = Ech::new(BW);
    for c in cands {
        if rows.iter().all(|y| c.eval(y) == W::ZERO) {
            holds.push(c.name.clone());
            for f in c.limb_functionals() {
                expl.insert(f);
            }
        } else {
            let bad = rows.iter().filter(|y| c.eval(y) != W::ZERO).count();
            fails.push(format!("{}({bad})", c.name));
        }
    }
    println!(
        "Z8D_LEFT_KERNEL {label} kind={kind} image_rank={} annihilator_dim={ann} candidates={} holding={} failing={} explained_dim={} unexplained_dim={} failing_names={fails:?}",
        img.rank,
        cands.len(),
        holds.len(),
        fails.len(),
        expl.rank,
        ann - expl.rank
    );
    if expl.rank < ann {
        let mut rest = Ech::new(BW);
        let mut rest_rows = vec![];
        for nv in null_space(img) {
            let r = expl.residual(nv);
            if r.iter().any(|x| *x != M31::ZERO) {
                if rest.insert(r.clone()).is_some() {
                    rest_rows.push(r);
                }
            }
        }
        // Fully reduce the remainder basis (back-substitution) and print
        // supports as batched-coordinate ranges.
        let mut piv: Vec<usize> = rest_rows.iter().map(|r| r.iter().position(|x| *x != M31::ZERO).unwrap()).collect();
        let mut order: Vec<usize> = (0..rest_rows.len()).collect();
        order.sort_by_key(|&i| piv[i]);
        rest_rows = order.iter().map(|&i| rest_rows[i].clone()).collect();
        piv = order.iter().map(|&i| piv[i]).collect();
        for i in (0..rest_rows.len()).rev() {
            let ri = rest_rows[i].clone();
            for j in 0..rest_rows.len() {
                if j != i && rest_rows[j][piv[i]] != M31::ZERO {
                    let sc = rest_rows[j][piv[i]];
                    for t in 0..BW {
                        rest_rows[j][t] = rest_rows[j][t].sub(sc.mul(ri[t]));
                    }
                }
            }
        }
        let mut union = std::collections::BTreeSet::new();
        for (n, r) in rest_rows.iter().enumerate() {
            let cs: Vec<usize> = (0..NB).filter(|&i| (0..8).any(|m| r[8 * i + m] != M31::ZERO)).collect();
            union.extend(cs.iter().copied());
            if n < 16 || n + 4 >= rest_rows.len() {
                println!(
                    "Z8D_LEFT_KERNEL_REST {label} kind={kind} index={n} pivot={}:{} support={}",
                    bat_label(piv[n] / 8),
                    piv[n] % 8,
                    ranges(&cs)
                );
            }
        }
        let _ = support_labels;
        println!("Z8D_LEFT_KERNEL_REST_UNION {label} kind={kind} rank={} support={}", rest.rank, ranges(&union.into_iter().collect::<Vec<_>>()));
    }
}
/// Ech whose pivot order is the round-j coefficients from degree 27 down to
/// 0, all four limbs per degree; returns pivot degrees (one entry per limb pivot).
fn leading_degrees(polys: &[[QM31; 28]]) -> Vec<usize> {
    let mut e = Ech::new(112);
    for p in polys {
        let v: Vec<M31> = (0..28).rev().flat_map(|d| limbs(p[d])).collect();
        e.insert(v);
    }
    (0..112).filter(|&i| e.p[i].is_some()).map(|i| 27 - i / 4).collect()
}

pub(super) fn main() {
    let args: Vec<_> = std::env::args().collect();
    let get = |k: &str| args.windows(2).find(|x| x[0] == k).map(|x| x[1].clone());
    let s = get("--structure").expect("--structure");
    let v: usize = get("--vector").expect("--vector").parse().unwrap();
    let preflight = args.iter().any(|x| x == "--preflight");
    let start = Instant::now();
    println!("Z8D_START structure={s} vector={v} preflight={preflight} transport=D13 batching=WideExact balanced=true proxy=false");
    let t = trial(v);
    let a = alpha_for(&s, v, &t.a);
    let label = format!("structure={s} vector={v}");
    let op = opening_challenges(v);
    println!(
        "Z8D_ALPHA {label} alpha={:?} lambda_dims={:?} good3={} outside_k2={:?}",
        a.map(l4),
        lambda_dims(&a),
        good3(&a),
        (0..10).map(|i| !in_k2(a[i]) as u8).collect::<Vec<_>>()
    );
    println!(
        "Z8D_OPENING {label} gamma={:?} kappa={:?} tau={:?} fold={:?}",
        op.gamma.to_limbs(),
        op.kappa.to_limbs(),
        op.tau.to_limbs(),
        op.fold.to_limbs()
    );
    let basis = NaturalBasis::new(BasisSize::Initial).expect("basis");
    let z = [wpt(t.z[0]), wpt(t.z[1])];
    let total = total_weights(&basis, &a, z, &op);
    let phi = unit_functionals(&basis, z, &total, &op);
    println!("Z8D_CHECK unit_quotients=1024 ok=true eq_orientation=true seconds={:.3}", start.elapsed().as_secs_f64());
    let beta: Vec<[W; NB]> = (0..N)
        .map(|r| {
            let mut b = [W::ZERO; NB];
            b[0] = if inactive(r) { W::ONE } else { W::ZERO };
            b[1..].copy_from_slice(&phi[usize::from(ROW_TO_COEFFICIENT[r])]);
            b
        })
        .collect();
    let gpow = (0..29).map(|l| op.gamma.pow(l as u64)).collect();
    let (br, gr) = raw_c(&a, &t.z, &t.qs);
    let tail: Vec<_> = (0..N).map(|r| tail_row(&a, r)).collect();
    let cx = Ctx { a, br, gr, tail, beta, gpow };
    decomposition_check(&cx, &basis, z, &total, &op, 0x5a38_c0de ^ v as u64);
    // Transport / layout facts used below.
    assert!(inactive(0), "row 0 must be copy-inactive (balance 0)");
    for r in 0..N {
        assert_eq!(usize::from(ROW_TO_COEFFICIENT[r]), usize::from(z5::transport()[r]), "transport tables agree");
    }
    let rows_lo: Vec<usize> = (0..56).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    let rows_hi: Vec<usize> = (56..1024).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    let n_inactive = (0..N).filter(|&r| inactive(r)).count();
    println!(
        "Z8D_LAYOUT {label} inactive_rows={n_inactive} row0_coefficient={} rows_lo_all_inactive={} row0_in_rows_lo={} coeff_lt_89_all_inactive={}",
        ROW_TO_COEFFICIENT[0],
        rows_lo.iter().all(|&r| inactive(r)),
        rows_lo.contains(&0),
        (0..89).all(|k| inactive(usize::from(COEFFICIENT_TO_ROW[k])))
    );
    let rel = relations(&total, &op, &t.qs);
    let ln = Lanes::new(&cx);
    println!("Z8D_SETUP {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Pass 1: per-lane own kernels, carrying [batched | round]; global gate Ech. ----
    let mut pure = Ech::new(TW);
    let mut rker: Vec<Ech<M31>> = vec![];
    let mut own_rank = vec![];
    let mut kernel_dims = vec![];
    let mut rel_viol = [0usize; 4]; // ia, S1, S2, S3 (any u)
    let mut carries_checked = 0usize;
    for li in 0..LANES {
        let mut rk = Ech::new(RW);
        let mut ker = 0;
        let n = ln.count(li);
        lane_kernel(
            n,
            |i| {
                let (o, b, r) = ln.bal(li, i);
                (o, carry(b, &r))
            },
            |c| {
                ker += 1;
                let y = wvals(&c[..BW]);
                carries_checked += 1;
                if y[0] != W::ZERO {
                    rel_viol[0] += 1;
                }
                if rel.s1.eval(&y) != W::ZERO {
                    rel_viol[1] += 1;
                }
                if rel.s2.eval(&y) != W::ZERO {
                    rel_viol[2] += 1;
                }
                if rel.s3.iter().any(|r| r.eval(&y) != W::ZERO) {
                    rel_viol[3] += 1;
                }
                rk.insert(c[BW..].to_vec());
                pure.insert(c);
            },
        );
        own_rank.push(n - ker);
        kernel_dims.push(ker);
        println!(
            "Z8D_LANE_OWN {label} lane={} sources={n} own_rank={} own_functionals={} round_image_of_own_kernel={} seconds={:.3}",
            lane_name(li),
            n - ker,
            own_width(li),
            rk.rank,
            start.elapsed().as_secs_f64()
        );
        rker.push(rk);
    }
    let ia_pivots = (0..8).filter(|&i| pure.p[i].is_some()).count();
    let batched_rank = (0..BW).filter(|&i| pure.p[i].is_some()).count();
    println!(
        "Z8D_RELATIONS {label} carries_checked={carries_checked} violations_ia={} violations_S1={} violations_S2={} violations_S3={} relations_annihilate_exactly={}",
        rel_viol[0],
        rel_viol[1],
        rel_viol[2],
        rel_viol[3],
        rel_viol.iter().all(|x| *x == 0)
    );
    if rel_viol.iter().any(|x| *x != 0) {
        println!("STOP reason=verifier_relation_not_annihilating {label} violations={rel_viol:?}");
    }
    let retained = slice_image(&pure, BW);
    let silent = slice_image(&pure, BW + 4);
    // (2) dim R(ker own) = sum of per-lane own-kernel round images.
    let mut rown = Ech::new(RW);
    for rk in &rker {
        for row in ech_rows(rk) {
            rown.insert(row);
        }
    }
    let rown_zero = initial_zero(copied_ech(&rown));
    println!(
        "Z8D_GATE_PURE {label} span_rank={} batched_pivots={batched_rank} ia_pivots={ia_pivots} initial_retained_rank={} silent_rank={} upper_bound=1076 seconds={:.3}",
        pure.rank,
        retained.rank,
        silent.rank,
        start.elapsed().as_secs_f64()
    );
    println!(
        "Z8D_QPRIME {label} round_image_of_ker_own_initial_retained={} initial_zero={} expect=1080",
        rown.rank, rown_zero.rank
    );
    println!(
        "Z8D_B {label} bat_rank_on_ker_own={} bat_rank_on_ker_own_and_ker_R={} expect=1912 (second = span_rank - dim R(ker own) = {} - {})",
        batched_rank - ia_pivots,
        pure.rank - rown.rank,
        pure.rank,
        rown.rank
    );
    let psil = Proj::of(&silent, &a);
    report(&label, "silent", silent.rank, &psil);
    report(&label, "silent_initial_retained", retained.rank, &Proj::of(&retained, &a));
    report(&label, "round_image_of_ker_own", rown.rank, &Proj::of(&rown, &a));
    if silent.rank < 1076 {
        println!("Z8D_FINDING {label} balanced_silent_rank={} below=1076 deficit={}", silent.rank, 1076 - silent.rank);
    }
    let chain0: Vec<Vec<M31>> = (4..RW)
        .map(|i| {
            let mut u = vec![M31::ZERO; RW];
            u[i] = M31::ONE;
            let q = unflat(&u);
            let phi = final_value(&q, &a);
            flatten(&normalize_d(&q, phi, &a).expect("alpha9=1/2"))
        })
        .collect();
    summarize(&format!("{label} chain0_basis"), &silent, &chain0);
    summarize(&format!("{label} qprime_chain0_basis"), &rown_zero, &chain0);
    // (5a) left kernel of bat on ker own.
    {
        let mut img = Ech::new(BW);
        for row in pure.p.iter().take(BW).flatten() {
            img.insert(row[..BW].to_vec());
        }
        let mut c: Vec<&Rel> = vec![&rel.ia, &rel.s1, &rel.s2];
        c.extend(rel.s3.iter());
        left_kernel_report(&label, "bat_on_ker_own", &img, &c);
    }
    println!("Z8D_PASS1_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Z8d (0): the basis facts, checked directly on the quotient. ----
    let mono = basis.matrix(); // row-major, mono[d * 512 + j] = [X^d] N_j (SPEC §3 M_512)
    {
        let mut e = [M31::ZERO; 512];
        e[28] = M31::ONE;
        let mut nat = [M31::ZERO; 512];
        basis.monomial_to_natural(&e, &mut nat).expect("monomial_to_natural");
        let sup: Vec<usize> = (0..512).filter(|&j| nat[j] != M31::ZERO).collect();
        let n28: Vec<usize> = (0..512).filter(|&d| mono[d * 512 + 28] != M31::ZERO).collect();
        println!("Z8D_X28 {label} natural_support_of_x28={sup:?} monomial_support_of_N28={n28:?}");
    }
    law_check(&label, &basis, z, &op, 0x5a38_d8d0 ^ v as u64);

    // ---- Z8d (2): D-high under three conditions, plus the Z8c control verbatim. ----
    // Low-coordinate functionals of a balanced source (row r, limb k): x at
    // coefficient pi(r), and -x at coefficient pi(0) = 89 when r is inactive.
    let low_of = |r: usize, k: usize, monomial: bool| -> Vec<M31> {
        let x = tower(k);
        let mut out = [QM31::ZERO; 56];
        let mut put = |kappa: usize, val: QM31| {
            if monomial {
                let (p, j) = (kappa % 2, kappa / 2);
                for d in 0..28 {
                    let m = mono[d * 512 + j];
                    if m != M31::ZERO {
                        out[2 * d + p] = out[2 * d + p].add(val.mul(QM31::from_m31(m)));
                    }
                }
            } else if kappa < 56 {
                out[kappa] = out[kappa].add(val);
            }
        };
        put(usize::from(ROW_TO_COEFFICIENT[r]), x);
        if inactive(r) {
            put(usize::from(ROW_TO_COEFFICIENT[0]), QM31::ZERO.sub(x));
        }
        flatten(&out)
    };
    let mut cands: Vec<&Rel> = vec![&rel.ia, &rel.s1, &rel.s2];
    cands.extend(rel.s3.iter());
    cands.extend(rel.low.iter());
    // Control 1: Z8c's D-high_bal block, verbatim.
    let dhigh_ctrl = {
        let s0 = *rows_hi.iter().find(|&&r| inactive(r)).expect("an inactive D-high row");
        for &r in &rows_hi {
            assert!(ln.rr[11][r].iter().all(|x| *x == QM31::ZERO), "D coefficient >= 56 has a round contribution");
        }
        let mut srcs: Vec<(usize, usize, bool)> = vec![]; // (row, limb, subtract s0)
        for &r in &rows_hi {
            if r == s0 {
                continue;
            }
            for k in 0..4 {
                srcs.push((r, k, inactive(r)));
            }
        }
        let mut img = Ech::new(BW);
        let own_piv = lane_elim(
            srcs.len(),
            |i| {
                let (r, k, sub) = srcs[i];
                let (o, b, _) = ln.raw(11, r, k);
                if sub {
                    let (o0, b0, _) = ln.raw(11, s0, k);
                    (sub_vec(&o, &o0, |x, y| x.sub(y)), wflat(&sub_vec(&b, &b0, |x, y| x.sub(y))))
                } else {
                    (o, wflat(&b))
                }
            },
            |c| {
                img.insert(c);
            },
        );
        println!(
            "Z8D_DHIGH {label} kind=control_z8c_natural sources={} base_row={s0} own_rank={} bat_rank={} z8c=1808 ia_pivots={}",
            srcs.len(),
            own_piv.len(),
            img.rank,
            (0..8).filter(|&i| img.p[i].is_some()).count()
        );
        projection_ranks(&label, "control_z8c_natural", &img);
        left_kernel_report(&label, "control_z8c_natural", &img, &cands);
        img
    };
    // Generic route: all 4,092 balanced D sources (Lean `balance 0`), constraints
    // [low (224) | own_D (376) | optionally R_D (1,084)], carry batched.
    let mut dimgs: Vec<(&str, Ech<M31>)> = vec![("control_z8c_natural", dhigh_ctrl)];
    for (kind, monomial, with_r) in [
        ("natural_generic_kerR", false, true),
        ("monomial_x28", true, false),
        ("monomial_x28_kerR", true, true),
    ] {
        let mut img = Ech::new(BW);
        let piv = lane_elim(
            ln.count(11),
            |i| {
                let (r, k) = ln.row_of(11, i);
                let (o, b, rd) = ln.bal(11, i);
                let mut v = low_of(r, k, monomial);
                v.extend(o);
                if with_r {
                    v.extend(flatten(&rd));
                }
                (v, wflat(&b))
            },
            |c| {
                img.insert(c);
            },
        );
        let lead = |p: &Vec<M31>| p.iter().position(|x| *x != M31::ZERO).unwrap();
        let low_rank = piv.iter().filter(|p| lead(p) < 224).count();
        let own_rank = piv.iter().filter(|p| (224..224 + DW).contains(&lead(p))).count();
        let r_rank = piv.iter().filter(|p| lead(p) >= 224 + DW).count();
        println!(
            "Z8D_DHIGH {label} kind={kind} sources={} low_rank={low_rank} own_rank_on_high={own_rank} R_rank_on_high_ker_own={r_rank} with_R={with_r} bat_rank={} ia_pivots={} design_expect=1800",
            ln.count(11),
            img.rank,
            (0..8).filter(|&i| img.p[i].is_some()).count()
        );
        projection_ranks(&label, kind, &img);
        left_kernel_report(&label, kind, &img, &cands);
        dimgs.push((kind, img));
    }
    println!("Z8D_DHIGH_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Z8d (3): G-low on ker R_G ∩ ker own_G, natural rows pi^-1(0..55) (Z8c control)
    // and monomial degrees < 28 of (p0, p1); with and without G's extra claim. ----
    for (variant, drop_extra) in [("own_all", false), ("own_without_extra", true)] {
        let mut ker = vec![];
        lane_elim(
            ln.count(10),
            |i| {
                let (r, k) = ln.row_of(10, i);
                let (o, b, rd) = ln.bal(10, i);
                let mut vv: Vec<M31> = if drop_extra { o[..12].iter().chain(&o[16..]).copied().collect() } else { o };
                vv.extend(flatten(&rd));
                let x = tower(k);
                let mut c = vec![];
                for &lr in &rows_lo {
                    let mut val = QM31::ZERO;
                    if lr == r {
                        val = val.add(x);
                    }
                    if lr == 0 && inactive(r) {
                        val = val.sub(x);
                    }
                    c.extend(limbs(val));
                }
                c.extend(low_of(r, k, true));
                c.extend(wflat(&b));
                (vv, c)
            },
            |c| ker.push(c),
        );
        const OFF: usize = 448;
        let nat_low = rank_of(224, ker.iter().map(|c| c[..224].to_vec()));
        let mono_low = rank_of(224, ker.iter().map(|c| c[224..448].to_vec()));
        let fold_low = rank_of(112, ker.iter().map(|c| c[OFF + 64..OFF + 64 + 112].to_vec()));
        let joint_nat = rank_of(336, ker.iter().map(|c| c[..224].iter().chain(&c[OFF + 64..OFF + 176]).copied().collect()));
        let joint_mono = rank_of(336, ker.iter().map(|c| c[224..448].iter().chain(&c[OFF + 64..OFF + 176]).copied().collect()));
        let mut assembled = String::new();
        if !drop_extra {
            let mut gonly = Ech::new(BW);
            for c in &ker {
                gonly.insert(c[OFF..].to_vec());
            }
            projection_ranks(&label, "glow_bat", &gonly);
            assembled.push_str(&format!(" g_bat_rank={}", gonly.rank));
            for (kind, img) in &dimgs {
                let mut e = copied_ech(img);
                for c in &ker {
                    e.insert(c[OFF..].to_vec());
                }
                assembled.push_str(&format!(" dhigh_{kind}_plus_g_bat_rank={}", e.rank));
            }
            assembled.push_str(&format!(" bat_rank_on_ker_own={}", batched_rank - ia_pivots));
        }
        println!(
            "Z8D_GLOW {label} variant={variant} kernel_dim={} natural_low_rows_rank={nat_low} z8c={} monomial_low_rank={mono_low} expect=224 low_fold_rank={fold_low} joint_natural={joint_nat} joint_monomial={joint_mono}{assembled}",
            ker.len(),
            if drop_extra { 224 } else { 220 }
        );
    }
    println!("Z8D_ITEMS_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());
    if preflight {
        println!("Z8D_PREFLIGHT_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
        return;
    }
    println!("Z8D_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
}

/// §2.5.1 checked directly: build random "high" messages in the natural basis
/// (natural coefficients k < 56 zero) and in the monomial basis (p0, p1
/// divisible by X^28), project to OOD-zero, apply prover::quotient, and count
/// the nonzero low coordinates of the quotient in both bases and its low folds.
fn law_check(label: &str, basis: &NaturalBasis, z: [Point<W>; 2], op: &Opening, seed: u64) {
    let mut rng = Rng(seed);
    let to_mono = |m: &[W; 1024]| -> [W; 1024] {
        let mut out = [W::ZERO; 1024];
        for p in 0..2 {
            let a: Vec<W> = (0..512).map(|j| m[2 * j + p]).collect();
            let mut o = vec![W::ZERO; 512];
            basis.natural_to_monomial(&a, &mut o).expect("natural_to_monomial");
            for d in 0..512 {
                out[2 * d + p] = o[d];
            }
        }
        out
    };
    let from_mono = |m: &[W; 1024]| -> [W; 1024] {
        let mut out = [W::ZERO; 1024];
        for p in 0..2 {
            let a: Vec<W> = (0..512).map(|d| m[2 * d + p]).collect();
            let mut o = vec![W::ZERO; 512];
            basis.monomial_to_natural(&a, &mut o).expect("monomial_to_natural");
            for j in 0..512 {
                out[2 * j + p] = o[j];
            }
        }
        out
    };
    let nz = |v: &[W]| v.iter().filter(|x| **x != W::ZERO).count();
    for (bname, monomial) in [("natural", false), ("monomial", true)] {
        for trial in 0..3 {
            let ms: Vec<[W; 1024]> = (0..3)
                .map(|_| {
                    let mut m = [W::ZERO; 1024];
                    for k in 56..1024 {
                        m[k] = w_uniform(&mut rng);
                    }
                    if monomial { from_mono(&m) } else { m }
                })
                .collect();
            let o: Vec<[W; 2]> = ms.iter().map(|m| ood_pair(m, z)).collect();
            let det = o[1][0].mul(o[2][1]).sub(o[2][0].mul(o[1][1]));
            let inv = <W as CodeField>::try_inv(det).expect("OOD 2x2 invertible");
            let a = o[2][0].mul(o[0][1]).sub(o[0][0].mul(o[2][1])).mul(inv);
            let b = o[0][0].mul(o[1][1]).sub(o[1][0].mul(o[0][1])).mul(inv);
            let c: [W; 1024] = std::array::from_fn(|k| ms[0][k].add(a.mul(ms[1][k])).add(b.mul(ms[2][k])));
            let oc = ood_pair(&c, z);
            assert!(oc[0] == W::ZERO && oc[1] == W::ZERO, "OOD projection");
            let q = prover::quotient(basis, z, &c, oc).expect("quotient");
            let qm = to_mono(&q);
            let cm = to_mono(&c);
            let f = fold::fold_message(op.fold, &q);
            // Q(c) * L = c check on the monomial side is implied by prover::quotient; report counts.
            println!(
                "Z8D_LAW {label} basis={bname} trial={trial} input_natural_low_nonzero={} input_monomial_low_nonzero={} quotient_natural_low_nonzero={} quotient_monomial_low_nonzero={} quotient_fold_f0_13_nonzero={}",
                nz(&c[..56]),
                nz(&cm[..56]),
                nz(&q[..56]),
                nz(&qm[..56]),
                nz(&f[..14])
            );
        }
    }
}

//! Z8e (T2b-2b-D′, LOG D22.5): the natural-basis structure of the (B) half.
//! Exact M31/QM31/WideExact arithmetic. Not a Lean proof.
//!
//! Checks, on the balanced Lean model of Z8c/Z8d (structure A by default):
//!  (1) the wrap set X of the chord line in natural coordinates, rank C_ll,
//!      W_z = {q_lo : e1 q = e2 q = 0, (L q)_lo = 0} and the low shadow
//!      gamma^28 * Fold_lo(W_z), with its K-span;
//!  (2) the left kernel of V_D = bat(D-high ∩ ker own_D) against the 25
//!      verifier relations, Psi_lo (annihilator of the low shadow on f_0..13)
//!      and the conjugate relation eta_D; the same for V_G with eta_G;
//!  (3) the G premise: rank of T = [Psi_lo; eta_D] on V_G, its query-free
//!      split (T on ker R_G ∩ ker Rw_G; E_G on that ∩ ker T), G-low, the K-part
//!      reduction to G's low rows (identity (★)) and the 24-limb remainder.
//!
//! Everything from `use super::*` up to and including pass 1 of `main` is
//! z8d.rs lines 17-1195 copied verbatim with print tags renamed Z8D_ -> Z8E_.
//! New code follows `// ---- Z8e`.
#![allow(dead_code)]
use super::*;
use aspis_core::field::WideExact as W;
use aspis_core::r0::{
    basis::{BasisSize, NaturalBasis},
    chord::{self, FunctionalWeights, Secant},
    encoder, fold, opening, prover,
    transport::ROW_TO_COEFFICIENT,
};

const MASTER: u64 = 0x5348f0b9a87835d0;
const STRUCT_SEED: u64 = 0x5a38_d20b_2026_1013;
const OPEN_SEED: u64 = 0x5a38_0be0_2026_1013;
const STRUCTURES: [&str; 7] = ["A", "B", "I", "J", "K", "L", "M"];
const NB: usize = 264; // inactiveSum + 7 openingCoeff + 256 finalCoeff
const BW: usize = NB * 8; // batched M31 coordinates
const RW: usize = 1084; // round coordinates (Z4c layout)
const TW: usize = BW + RW;
const THREADS: usize = 4;

struct Trial {
    a: [QM31; 10],
    z: [Point<QM31>; 2],
    qs: Vec<usize>,
    ch: Challenges,
    tapes: Vec<Trace>,
}
/// Exact replay of z4c_main's RNG consumption (copied from z7.rs `trial`).
fn trial(trial: usize) -> Trial {
    let trial_seed = MASTER.wrapping_add((trial as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15));
    let mut rng = Rng(trial_seed);
    let a = std::array::from_fn(|_| rng.q());
    let z = [circle(rng.q()), circle(rng.q())];
    let sets = query_sets(&mut rng);
    let ch = Challenges {
        lambda: rng.q(),
        chi: rng.q(),
        theta: rng.q(),
        zc: std::array::from_fn(|_| rng.q()),
        mu: rng.q(),
        eta: rng.q(),
    };
    println!("TRIAL_SEED trial={trial} seed={trial_seed:#x}");
    println!("CHALLENGE trial={trial} alpha={a:?} semantic={ch:?} circle={z:?} queries={:?}", sets[0].1);
    let tapes = (0..5)
        .map(|_| {
            (0..17)
                .map(|c| {
                    (0..N)
                        .map(|r| {
                            if c < 16 && eligible(c, r) {
                                QM31::from_m31(rng.m())
                            } else if c == 16 && inactive(r) {
                                rng.q()
                            } else {
                                QM31::ZERO
                            }
                        })
                        .collect()
                })
                .collect()
        })
        .collect();
    Trial { a, z, qs: sets[0].1.clone(), ch, tapes }
}

fn l4(x: QM31) -> [u32; 4] {
    limbs(x).map(|v| v.0)
}
fn unflat(v: &[M31]) -> Vec<QM31> {
    v.chunks(4)
        .map(|c| QM31 { c0: CM31::new(c[0], c[1]), c1: CM31::new(c[2], c[3]) })
        .collect()
}
fn half() -> QM31 {
    QM31::from_m31(M31(2).inv())
}
fn admissible(a: &[QM31; 10]) -> bool {
    a.iter().all(|x| *x != QM31::ZERO && *x != QM31::ONE) && a[9] != half()
}
fn f_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31::from_m31(rng.m());
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
fn k2_nontrivial(rng: &mut Rng, last: bool) -> QM31 {
    loop {
        let x = QM31 { c0: CM31::new(rng.m(), rng.m()), c1: CM31::new(M31::ZERO, M31::ZERO) };
        if x != QM31::ZERO && x != QM31::ONE && !(last && x == half()) {
            return x;
        }
    }
}
/// A: Z4c alpha. B: all alpha_i in F\{0,1}. I: all alpha_i in K2 = F(i)\{0,1}.
/// J: alpha_0 Z4c (uniform in QM31), alpha_1..6 in F\{0,1}, alpha_7..9 Z4c.
/// Z8c additions (seeds of A, B, I, J unchanged: new structures are appended):
/// K: alpha_2, alpha_3 in F\{0,1}, others Z4c.  L: alpha_0..5 in F\{0,1},
/// alpha_6..9 Z4c (alpha_6 checked outside K2).  M: alpha_3..6 in F\{0,1}, others Z4c.
fn alpha_for(s: &str, v: usize, base: &[QM31; 10]) -> [QM31; 10] {
    let si = STRUCTURES.iter().position(|x| *x == s).unwrap() as u64;
    let mut rng = Rng(STRUCT_SEED.wrapping_add((si * 64 + v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let mut a = *base;
    match s {
        "A" => {}
        "B" => (0..10).for_each(|i| a[i] = f_nontrivial(&mut rng, i == 9)),
        "I" => (0..10).for_each(|i| a[i] = k2_nontrivial(&mut rng, i == 9)),
        "J" => (1..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        "K" => (2..4).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        "L" => {
            (0..6).for_each(|i| a[i] = f_nontrivial(&mut rng, false));
            assert!(!in_k2(a[6]), "structure L needs alpha_6 outside K2");
        }
        "M" => (3..7).for_each(|i| a[i] = f_nontrivial(&mut rng, false)),
        _ => panic!("unknown structure {s}"),
    }
    assert!(admissible(&a), "alpha admissibility");
    a
}
fn lambda_dims(a: &[QM31; 10]) -> Vec<usize> {
    (0..10)
        .map(|j| {
            let mut e = Ech::new(4);
            for l in 0..1usize << j {
                let x = (0..j).fold(QM31::ONE, |v, i| {
                    v.mul(if l >> i & 1 == 1 { a[i] } else { QM31::ONE.sub(a[i]) })
                });
                e.insert(limbs(x).to_vec());
            }
            e.rank
        })
        .collect()
}

/// `last_coeff`'s chain reconstruction, returning all ten polys (copied from z7.rs).
fn round_polys(v: &[QM31], a: &[QM31; 10]) -> Vec<[QM31; 28]> {
    let mut prev = v[0];
    let mut out = vec![];
    for j in 0..10 {
        let mut co = [QM31::ZERO; 28];
        co[0] = v[1 + 27 * j];
        co[2..].copy_from_slice(&v[2 + 27 * j..28 + 27 * j]);
        co[1] = prev
            .sub(co[0].add(co[0]))
            .sub(co[2..].iter().fold(QM31::ZERO, |v, x| v.add(*x)));
        prev = co.iter().rev().fold(QM31::ZERO, |v, x| v.mul(a[j]).add(*x));
        out.push(co);
    }
    out
}
/// Per-round projection ranks (copied from z7.rs).
struct Proj {
    full: Vec<Ech<M31>>,
    limb: Vec<Vec<Ech<M31>>>,
}
impl Proj {
    fn of(e: &Ech<M31>, a: &[QM31; 10]) -> Self {
        let mut p = Proj {
            full: (0..10).map(|_| Ech::new(112)).collect(),
            limb: (0..10).map(|_| (0..4).map(|_| Ech::new(28)).collect()).collect(),
        };
        for b in e.p.iter().flatten() {
            for (j, co) in round_polys(&unflat(b), a).iter().enumerate() {
                p.full[j].insert(flatten(co));
                for k in 0..4 {
                    p.limb[j][k].insert(co.iter().map(|x| limbs(*x)[k]).collect());
                }
            }
        }
        p
    }
    fn full_ranks(&self) -> Vec<usize> {
        self.full.iter().map(|e| e.rank).collect()
    }
    fn limb_ranks(&self) -> Vec<[usize; 4]> {
        self.limb.iter().map(|l| std::array::from_fn(|k| l[k].rank)).collect()
    }
}

fn wq(x: QM31) -> W {
    W::from_qm31(x)
}
fn wlimbs(x: W) -> [M31; 8] {
    x.to_limbs().map(M31)
}
fn wpt(p: Point<QM31>) -> Point<W> {
    Point { x: wq(p.x), y: wq(p.y) }
}
fn w_uniform(rng: &mut Rng) -> W {
    W::new(rng.q(), rng.q())
}
struct Opening {
    gamma: W,
    kappa: W,
    tau: W,
    fold: W,
}
/// ch.opening 0..3, uniform in WideExact; one stream per vector (shared by
/// all structures of that vector); gamma resampled at zero as the sampler does.
fn opening_challenges(v: usize) -> Opening {
    let mut rng = Rng(OPEN_SEED.wrapping_add((v as u64 + 1).wrapping_mul(0x9e3779b97f4a7c15)));
    let gamma = loop {
        let g = w_uniform(&mut rng);
        if g != W::ZERO {
            break g;
        }
    };
    Opening { gamma, kappa: w_uniform(&mut rng), tau: w_uniform(&mut rng), fold: w_uniform(&mut rng) }
}

/// Lean `totalWeights` with Lean `weights` (Rust OpeningData::weights + kappa^4 libraWeight).
fn total_weights(basis: &NaturalBasis, a: &[QM31; 10], z: [Point<W>; 2], op: &Opening) -> [W; 1024] {
    let aw = a.map(wq);
    let pts = opening::points_from_alphas(&aw);
    // Orientation check: Rust row_eq_weight(points_from_alphas) == Z4c eq(points).
    let zp = points(a);
    for j in 0..3 {
        let rw = opening::row_eq_weight(&pts[j]);
        for r in 0..N {
            assert_eq!(rw[r], wq(eq(&zp[j], r)), "eq orientation j={j} r={r}");
        }
    }
    let eqs = pts.map(|p| opening::eq_weight(&p));
    let ind = opening::indicator();
    let k = opening::powers::<5>(op.kappa);
    let w: [W; 1024] = std::array::from_fn(|j| {
        ind[j]
            .add(k[1].mul(eqs[0][j]))
            .add(k[2].mul(eqs[1][j]))
            .add(k[3].mul(eqs[2][j]))
            .add(k[4].mul(wq(h_weight(a, j))))
    });
    let line = Secant::from_points(z[0], z[1]);
    let qw = chord::quotient_weights(basis, line, &w).expect("quotient_weights");
    let e1 = FunctionalWeights::e1::<W>(basis).expect("e1");
    let e2 = FunctionalWeights::e2(basis, line.b, line.c).expect("e2");
    std::array::from_fn(|j| qw[j].add(op.tau.mul(e1[j])).add(op.tau.mul(op.tau).mul(e2[j])))
}
fn ood_pair(m: &[W; 1024], z: [Point<W>; 2]) -> [W; 2] {
    [encoder::eval_message(m, z[0]), encoder::eval_message(m, z[1])]
}
/// phi[k] = (round_polynomial(Q e_k, total) [7], fold_message(op.fold, Q e_k) [256])
/// for every natural coefficient unit e_k (Q = prover::quotient, column-wise).
fn unit_functionals(basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening) -> Vec<[W; NB - 1]> {
    let ks: Vec<usize> = (0..1024).collect();
    let chunk = ks.len().div_ceil(THREADS);
    std::thread::scope(|s| {
        let hs: Vec<_> = ks
            .chunks(chunk)
            .map(|part| {
                s.spawn(move || {
                    part.iter()
                        .map(|&k| {
                            let mut e = [W::ZERO; 1024];
                            e[k] = W::ONE;
                            let q = prover::quotient(basis, z, &e, ood_pair(&e, z))
                                .unwrap_or_else(|err| panic!("STOP quotient unit k={k} error={err:?}"));
                            let rp = prover::round_polynomial(&q, total);
                            let f = fold::fold_message(op.fold, &q);
                            let mut out = [W::ZERO; NB - 1];
                            out[..7].copy_from_slice(&rp);
                            out[7..].copy_from_slice(&f);
                            out
                        })
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
    })
}

struct Ctx {
    a: [QM31; 10],
    br: Vec<Vec<M31>>,
    gr: Vec<Vec<QM31>>,
    tail: Vec<Vec<QM31>>,
    beta: Vec<[W; NB]>, // row-indexed
    gpow: Vec<W>,       // gamma^lane, lane 0..28
}
impl Ctx {
    /// Batched payload of x at row r of physical lane `lane`.
    fn batched(&self, lane: usize, x: W, r: usize) -> Vec<W> {
        let g = self.gpow[lane].mul(x);
        self.beta[r].iter().map(|b| g.mul(*b)).collect()
    }
}
fn wflat(v: &[W]) -> Vec<M31> {
    v.iter().flat_map(|x| wlimbs(*x)).collect()
}
fn sub_vec<T: Copy>(a: &[T], b: &[T], f: impl Fn(T, T) -> T) -> Vec<T> {
    a.iter().zip(b).map(|(x, y)| f(*x, *y)).collect()
}

/// One lane's sources, eliminated on its own per-lane coordinates (as Z4c's
/// lane_eliminate does), carrying [batched (2112) | round (1084)] in M31.
/// Kernel carries are inserted into `global`; returns the carried particular
/// solution for each per-lane target (which must lie in the lane's coordinate span).
fn lane_stage(
    count: usize,
    mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>),
    targets: &[Vec<M31>],
    global: &mut Ech<M31>,
) -> Vec<Vec<M31>> {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => {
                global.insert(c);
            }
        }
    }
    targets
        .iter()
        .map(|t| {
            let mut v = t.clone();
            let mut out = vec![M31::ZERO; TW];
            for i in 0..v.len() {
                if v[i] == M31::ZERO {
                    continue;
                }
                let (b, bc) = piv[i].as_ref().expect("per-lane target outside lane coordinate span");
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..TW {
                    out[j] = out[j].add(s.mul(bc[j]));
                }
            }
            out
        })
        .collect()
}
fn carry(batched: Vec<W>, round: &[QM31]) -> Vec<M31> {
    let mut c = wflat(&batched);
    c.extend(flatten(round));
    debug_assert_eq!(c.len(), TW);
    c
}
fn scale(v: &[QM31], x: QM31) -> Vec<QM31> {
    v.iter().map(|y| y.mul(x)).collect()
}
/// Mask-only lanes (F, all rows), G (K4, all rows) and D (K4, all rows).
fn pure_sources(cx: &Ctx, global: &mut Ech<M31>) {
    let a = &cx.a;
    for c in 0..10 {
        let lane = 16 + c;
        lane_stage(N, |r| (cx.br[r][1..].to_vec(), carry(cx.batched(lane, W::ONE, r), &round_row(a, r, c))), &[], global);
    }
    for (lane, g) in [(27usize, true), (28, false)] {
        lane_stage(
            4 * N,
            |i| {
                let (r, k) = (i / 4, i % 4);
                let x = tower(k);
                let rr = if g { round_row(a, r, 10) } else { cx.tail[r].clone() };
                (flatten(&scale(&cx.gr[r][1..], x)), carry(cx.batched(lane, wq(x), r), &scale(&rr, x)))
            },
            &[],
            global,
        );
    }
}
/// Semantic eligible sources (balanced vs row 1023) and H1 padding (inactive
/// rows, balanced vs row 0), with the per-pair witness-difference targets.
fn conditioned_sources(cx: &Ctx, traces: &[Trace], pairs: usize, global: &mut Ech<M31>) -> Vec<Vec<M31>> {
    let a = &cx.a;
    let mut sol = vec![vec![M31::ZERO; TW]; pairs];
    for c in 0..16 {
        let rows: Vec<usize> = (0..N).filter(|&r| r != 1023 && eligible(c, r)).collect();
        let tg: Vec<Vec<M31>> = (0..pairs)
            .map(|p| {
                let d: Vec<M31> = (0..N).map(|r| traces[2 * p][c][r].c0.a.sub(traces[2 * p + 1][c][r].c0.a)).collect();
                (1..113).map(|i| (0..N).fold(M31::ZERO, |s, r| s.add(d[r].mul(cx.br[r][i])))).collect()
            })
            .collect();
        let rd = round_row(a, 1023, 38 + c);
        let bd = cx.batched(c, W::ONE, 1023);
        let s = lane_stage(
            rows.len(),
            |i| {
                let r = rows[i];
                let rr = round_row(a, r, 38 + c);
                let bb = cx.batched(c, W::ONE, r);
                if inactive(r) {
                    (
                        sub_vec(&cx.br[r][1..], &cx.br[1023][1..], |x, y| x.sub(y)),
                        carry(sub_vec(&bb, &bd, |x, y| x.sub(y)), &sub_vec(&rr, &rd, |x, y| x.sub(y))),
                    )
                } else {
                    (cx.br[r][1..].to_vec(), carry(bb, &rr))
                }
            },
            &tg,
            global,
        );
        for p in 0..pairs {
            for j in 0..TW {
                sol[p][j] = sol[p][j].add(s[p][j]);
            }
        }
    }
    let rows: Vec<usize> = (1..N).filter(|&r| inactive(r)).collect();
    let tg: Vec<Vec<M31>> = (0..pairs)
        .map(|p| {
            let d: Vec<QM31> = (0..N).map(|r| traces[2 * p][16][r].sub(traces[2 * p + 1][16][r])).collect();
            flatten(&(1..95).map(|i| (0..N).fold(QM31::ZERO, |s, r| s.add(d[r].mul(cx.gr[r][i])))).collect::<Vec<_>>())
        })
        .collect();
    let zero = vec![QM31::ZERO; 271];
    let s = lane_stage(
        4 * rows.len(),
        |i| {
            let (r, k) = (rows[i / 4], i % 4);
            let x = tower(k);
            let b = sub_vec(&cx.batched(26, wq(x), r), &cx.batched(26, wq(x), 0), |p, q| p.sub(q));
            (flatten(&scale(&sub_vec(&cx.gr[r][1..], &cx.gr[0][1..], |p, q| p.sub(q)), x)), carry(b, &zero))
        },
        &tg,
        global,
    );
    for p in 0..pairs {
        for j in 0..TW {
            sol[p][j] = sol[p][j].add(s[p][j]);
        }
    }
    sol
}
/// Rows of `e` with pivot >= from, sliced to the round part [BW..].
fn slice_image(e: &Ech<M31>, from: usize) -> Ech<M31> {
    let mut out = Ech::new(RW);
    for (i, row) in e.p.iter().enumerate() {
        if let Some(v) = row {
            if i >= from {
                out.insert(v[BW..].to_vec());
            }
        }
    }
    out
}
/// Reduce by pivots < BW only (the batched coordinates).
fn batched_reduce(e: &Ech<M31>, mut v: Vec<M31>) -> Vec<M31> {
    for i in 0..BW {
        if v[i] == M31::ZERO {
            continue;
        }
        if let Some(b) = &e.p[i] {
            let s = v[i];
            for j in i..v.len() {
                v[j] = v[j].sub(s.mul(b[j]));
            }
        }
    }
    v
}
fn report(label: &str, kind: &str, total: usize, p: &Proj) {
    println!(
        "Z8E_RANKS {label} kind={kind} total={total} round_full={:?} round_limb={:?}",
        p.full_ranks(),
        p.limb_ranks()
    );
}

/// Direct check of the column-wise decomposition: for random words on lanes
/// 16 (F) and 27, 28 (K4), the Rust pipeline on whole columns (quotient per
/// lane, gamma-batched, round_polynomial with total weights, fold_message,
/// v_honest-style inactive sum) equals the sum of per-row batched vectors.
fn decomposition_check(cx: &Ctx, basis: &NaturalBasis, z: [Point<W>; 2], total: &[W; 1024], op: &Opening, seed: u64) {
    let mut rng = Rng(seed);
    let mut q = [W::ZERO; 1024];
    let mut inactive_sum = W::ZERO;
    let mut expected = vec![W::ZERO; NB];
    for lane in [16usize, 27, 28] {
        let rows: [W; 1024] = std::array::from_fn(|_| if lane == 16 { wq(QM31::from_m31(rng.m())) } else { wq(rng.q()) });
        let coeffs = aspis_core::r0::transport::to_coefficients(&rows);
        let ql = prover::quotient(basis, z, &coeffs, ood_pair(&coeffs, z)).expect("column quotient");
        for i in 0..1024 {
            q[i] = q[i].add(cx.gpow[lane].mul(ql[i]));
        }
        for r in 0..N {
            if inactive(r) {
                inactive_sum = inactive_sum.add(cx.gpow[lane].mul(rows[r]));
            }
            for (e, b) in expected.iter_mut().zip(cx.batched(lane, rows[r], r)) {
                *e = e.add(b);
            }
        }
    }
    let rp = prover::round_polynomial(&q, total);
    let f = fold::fold_message(op.fold, &q);
    let mut direct = vec![inactive_sum];
    direct.extend_from_slice(&rp);
    direct.extend_from_slice(&f);
    assert_eq!(direct, expected, "column-wise decomposition");
    println!("Z8E_CHECK decomposition lanes=[16,27,28] whole_column_pipeline_equals_rowwise_sum=true coordinates={NB}");
}


// ---- Z8b helpers ---- (copied verbatim from z8b.rs)
use aspis_core::r0::transport::COEFFICIENT_TO_ROW;

const DW: usize = 376; // D's own-silence functionals: 94 K4-valued = 376 M31 limbs
const SW: usize = BW + DW + RW; // [batched | D own | round]

/// [batched limbs | D-own limbs | round limbs].
fn gen3(batched: Vec<W>, down: Vec<M31>, round: &[QM31]) -> Vec<M31> {
    let mut v = wflat(&batched);
    v.extend(down);
    v.extend(flatten(round));
    assert_eq!(v.len(), SW);
    v
}
fn d_own(cx: &Ctx, r: usize, x: QM31) -> Vec<M31> {
    flatten(&scale(&cx.gr[r][1..], x))
}
/// z8.rs `lane_stage` with the carry width taken from the source and the
/// kernel carries handed to `sink` (no targets).
fn lane_kernel(count: usize, mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>), mut sink: impl FnMut(Vec<M31>)) {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..c.len() {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => sink(c),
        }
    }
}
fn slice_from(e: &Ech<M31>, from: usize, offset: usize, width: usize) -> Ech<M31> {
    let mut out = Ech::new(width);
    for (i, row) in e.p.iter().enumerate() {
        if let (Some(v), true) = (row, i >= from) {
            out.insert(v[offset..].to_vec());
        }
    }
    out
}
fn rank_of(width: usize, vs: impl Iterator<Item = Vec<M31>>) -> usize {
    let mut e = Ech::new(width);
    for v in vs {
        e.insert(v);
    }
    e.rank
}
fn g_lane_coords(cx: &Ctx, r: usize, x: QM31, with_inactive: bool) -> Vec<M31> {
    let mut v = d_own(cx, r, x);
    if with_inactive {
        v.extend(if inactive(r) { limbs(x) } else { [M31::ZERO; 4] });
    }
    v
}


// ---- Z8c ----


fn in_k2(x: QM31) -> bool {
    x.c1 == CM31::new(M31::ZERO, M31::ZERO)
}
/// Good3 (design §1.2): at least three of alpha_0..alpha_3 outside K2.
fn good3(a: &[QM31; 10]) -> bool {
    (0..4).filter(|&i| !in_k2(a[i])).count() >= 3
}
const LANES: usize = 12; // mask-only 0..9 (phys 16..25), G (27), D (28)
fn lane_name(li: usize) -> String {
    match li {
        0..=9 => format!("m{li}_e{}", EXP[li]),
        10 => "G".into(),
        _ => "D".into(),
    }
}
fn phys(li: usize) -> usize {
    match li {
        0..=9 => 16 + li,
        10 => 27,
        _ => 28,
    }
}
fn per_row(li: usize) -> usize {
    if li < 10 { 1 } else { 4 }
}
fn own_width(li: usize) -> usize {
    if li < 10 { 112 } else { DW }
}
/// Own-functional blocks in limbs (same boundaries for F and K4 lanes):
/// claim0, claim1, claim2, extra, ood(2), opened(88).
fn own_blocks(li: usize) -> [(&'static str, usize, usize); 6] {
    [("claim0", 0, 4), ("claim1", 4, 8), ("claim2", 8, 12), ("extra", 12, 16), ("ood", 16, 24), ("opened", 24, own_width(li))]
}
type Src = (Vec<M31>, Vec<W>, Vec<QM31>); // (own limbs, batched NB values, round 271)
struct Lanes<'a> {
    cx: &'a Ctx,
    rr: Vec<Vec<Vec<QM31>>>, // [lane][row] unscaled round vector (round_row / tail_row)
    zero: Vec<Vec<Src>>,     // raw source at row 0, per lane and limb
}
impl<'a> Lanes<'a> {
    fn new(cx: &'a Ctx) -> Self {
        let a = cx.a;
        let rr: Vec<Vec<Vec<QM31>>> = std::thread::scope(|s| {
            let hs: Vec<_> = (0..LANES)
                .map(|li| {
                    s.spawn(move || {
                        (0..N)
                            .map(|r| if li == 11 { tail_row(&a, r) } else { round_row(&a, r, li) })
                            .collect::<Vec<_>>()
                    })
                })
                .collect();
            hs.into_iter().map(|h| h.join().unwrap()).collect()
        });
        let mut l = Lanes { cx, rr, zero: vec![] };
        l.zero = (0..LANES).map(|li| (0..per_row(li)).map(|k| l.raw(li, 0, k)).collect()).collect();
        l
    }
    /// Unbalanced unit source: value x (1 for F lanes, tower(k) for K4 lanes) at row r.
    fn raw(&self, li: usize, r: usize, k: usize) -> Src {
        let cx = self.cx;
        if li < 10 {
            (cx.br[r][1..].to_vec(), cx.batched(phys(li), W::ONE, r), self.rr[li][r].clone())
        } else {
            let x = tower(k);
            (d_own(cx, r, x), cx.batched(phys(li), wq(x), r), scale(&self.rr[li][r], x))
        }
    }
    fn count(&self, li: usize) -> usize {
        (N - 1) * per_row(li)
    }
    /// Balanced source i: row r = i / per_row + 1, limb i % per_row;
    /// e_r for active r, e_r - e_0 for inactive r (Lean `balance 0`).
    fn row_of(&self, li: usize, i: usize) -> (usize, usize) {
        (i / per_row(li) + 1, i % per_row(li))
    }
    fn bal(&self, li: usize, i: usize) -> Src {
        let (r, k) = self.row_of(li, i);
        let s = self.raw(li, r, k);
        if !inactive(r) {
            return s;
        }
        let z = &self.zero[li][k];
        (
            sub_vec(&s.0, &z.0, |x, y| x.sub(y)),
            sub_vec(&s.1, &z.1, |x, y| x.sub(y)),
            sub_vec(&s.2, &z.2, |x, y| x.sub(y)),
        )
    }
}

/// z8b `lane_kernel`, additionally returning the pivot rows (an echelon basis
/// of the image of the eliminated coordinates v).
fn lane_elim(count: usize, mut source: impl FnMut(usize) -> (Vec<M31>, Vec<M31>), mut sink: impl FnMut(Vec<M31>)) -> Vec<Vec<M31>> {
    let mut piv: Vec<Option<(Vec<M31>, Vec<M31>)>> = vec![];
    for i in 0..count {
        let (mut v, mut c) = source(i);
        if piv.is_empty() {
            piv = vec![None; v.len()];
        }
        let mut pivot = None;
        for i in 0..v.len() {
            if v[i] == M31::ZERO {
                continue;
            }
            if let Some((b, bc)) = &piv[i] {
                let s = v[i];
                for j in i..v.len() {
                    v[j] = v[j].sub(s.mul(b[j]));
                }
                for j in 0..c.len() {
                    c[j] = c[j].sub(s.mul(bc[j]));
                }
            } else {
                let inv = v[i].inv();
                for x in &mut v[i..] {
                    *x = x.mul(inv);
                }
                for x in &mut c {
                    *x = x.mul(inv);
                }
                pivot = Some(i);
                break;
            }
        }
        match pivot {
            Some(i) => piv[i] = Some((v, c)),
            None => sink(c),
        }
    }
    piv.into_iter().flatten().map(|(v, _)| v).collect()
}
fn ech_rows(e: &Ech<M31>) -> Vec<Vec<M31>> {
    e.p.iter().flatten().cloned().collect()
}
fn block_ranks(li: usize, carries: &[Vec<M31>]) -> Vec<(String, usize)> {
    let mut out = vec![("all".to_string(), rank_of(own_width(li), carries.iter().cloned()))];
    for (n, s, e) in own_blocks(li) {
        out.push((n.to_string(), rank_of(e - s, carries.iter().map(|c| c[s..e].to_vec()))));
    }
    out
}
fn fmt_ranks(v: &[(String, usize)]) -> String {
    v.iter().map(|(n, r)| format!("{n}:{r}")).collect::<Vec<_>>().join(",")
}

// Batched coordinate index: 0 = .inactiveSum, 1..=7 = .openingCoeff 0..6, 8.. = .finalCoeff 0..255.
fn bat_label(i: usize) -> String {
    match i {
        0 => "ia".into(),
        1..=7 => format!("h{}", i - 1),
        _ => format!("f{}", i - 8),
    }
}
fn wunit(m: usize) -> W {
    let mut l = [0u32; 8];
    l[m] = 1;
    W::from_limbs(l).unwrap()
}
fn wvals(limbs: &[M31]) -> Vec<W> {
    limbs.chunks(8).map(|c| W::from_limbs(std::array::from_fn(|i| c[i].0)).unwrap()).collect()
}
/// A K-linear relation on the batched coordinates: sum_i c_i * y_i.
struct Rel {
    name: String,
    c: Vec<(usize, W)>,
}
impl Rel {
    fn eval(&self, y: &[W]) -> W {
        self.c.iter().fold(W::ZERO, |s, (i, c)| s.add(c.mul(y[*i])))
    }
    /// The 8 F-functionals limb_k(sum c_i y_i) on the BW limb coordinates.
    fn limb_functionals(&self) -> Vec<Vec<M31>> {
        (0..8)
            .map(|k| {
                let mut v = vec![M31::ZERO; BW];
                for (i, c) in &self.c {
                    for m in 0..8 {
                        v[8 * i + m] = v[8 * i + m].add(M31(c.mul(wunit(m)).to_limbs()[k]));
                    }
                }
                v
            })
            .collect()
    }
}
/// (S1) check_v2 / round_eval, (S2) round_boundary (balanced form h0 + h4),
/// (S2u) unbalanced form h0 + h4 - quarter*ia, (S3_u) check_v1 / fold_encoded
/// at each queried fibre on own-silent tapes, the 14 low fold coordinates, and ia.
struct Relations {
    ia: Rel,
    s1: Rel,
    s2: Rel,
    s2u: Rel,
    s3: Vec<Rel>,
    low: Vec<Rel>,
}
fn relations(total: &[W; 1024], op: &Opening, qs: &[usize]) -> Relations {
    let quarter = fold::quarter::<W>();
    let df = fold::dual_fold(op.fold, total);
    let mut s1 = vec![];
    let mut p = W::ONE;
    for i in 0..7 {
        s1.push((1 + i, p));
        p = p.mul(op.fold);
    }
    for d in 0..256 {
        s1.push((8 + d, W::ZERO.sub(quarter.mul(df[d]))));
    }
    let s3 = qs
        .iter()
        .map(|&u| {
            let fib = FibreIndex::new(u).unwrap();
            let c = (0..256)
                .map(|d| {
                    let mut e = [W::ZERO; 256];
                    e[d] = W::ONE;
                    (8 + d, encoder::exact_final_encoder(&e, fib))
                })
                .collect();
            Rel { name: format!("S3_u{u}"), c }
        })
        .collect();
    Relations {
        ia: Rel { name: "ia".into(), c: vec![(0, W::ONE)] },
        s1: Rel { name: "S1".into(), c: s1 },
        s2: Rel { name: "S2".into(), c: vec![(1, W::ONE), (5, W::ONE)] },
        s2u: Rel { name: "S2u".into(), c: vec![(1, W::ONE), (5, W::ONE), (0, W::ZERO.sub(quarter))] },
        s3,
        low: (0..14).map(|d| Rel { name: format!("f{d}"), c: vec![(8 + d, W::ONE)] }).collect(),
    }
}
/// Null space of the row space of `img` (width BW) via back-substitution.
fn null_space(img: &Ech<M31>) -> Vec<Vec<M31>> {
    let n = img.p.len();
    let mut rows: Vec<Option<Vec<M31>>> = img.p.clone();
    let pivots: Vec<usize> = (0..n).filter(|&i| rows[i].is_some()).collect();
    for (pi, &i) in pivots.iter().enumerate().rev() {
        let ri = rows[i].clone().unwrap();
        for &j in &pivots[..pi] {
            let rj = rows[j].as_mut().unwrap();
            let s = rj[i];
            if s != M31::ZERO {
                for t in i..n {
                    rj[t] = rj[t].sub(s.mul(ri[t]));
                }
            }
        }
    }
    (0..n)
        .filter(|&f| rows[f].is_none())
        .map(|f| {
            let mut v = vec![M31::ZERO; n];
            v[f] = M31::ONE;
            for &p in &pivots {
                v[p] = M31::ZERO.sub(rows[p].as_ref().unwrap()[f]);
            }
            v
        })
        .collect()
}
fn support_labels(v: &[M31]) -> Vec<String> {
    let mut out = vec![];
    for i in 0..NB {
        let ls: Vec<usize> = (0..8).filter(|&m| v[8 * i + m] != M31::ZERO).collect();
        if !ls.is_empty() {
            out.push(format!("{}{:?}", bat_label(i), ls));
        }
    }
    out
}
/// Batched coordinate indices as compressed label ranges.
fn ranges(cs: &[usize]) -> String {
    let mut out = vec![];
    let mut i = 0;
    while i < cs.len() {
        let mut j = i;
        while j + 1 < cs.len() && cs[j + 1] == cs[j] + 1 {
            j += 1;
        }
        out.push(if i == j { bat_label(cs[i]) } else { format!("{}..{}", bat_label(cs[i]), bat_label(cs[j])) });
        i = j + 1;
    }
    format!("[{}]", out.join(","))
}
/// Ranks of a batched image projected to h, to f, and to the f-prefixes f[0..m).
fn projection_ranks(label: &str, kind: &str, img: &Ech<M31>) {
    let rows: Vec<Vec<M31>> = ech_rows(img);
    let h = rank_of(56, rows.iter().map(|r| r[8..64].to_vec()));
    let f = rank_of(2048, rows.iter().map(|r| r[64..].to_vec()));
    let pre: Vec<(usize, usize)> = [1usize, 2, 4, 8, 12, 13, 14, 15, 16, 20, 24, 32, 64, 128, 256]
        .iter()
        .map(|&m| (m, rank_of(8 * m, rows.iter().map(|r| r[64..64 + 8 * m].to_vec()))))
        .collect();
    println!("Z8E_PROJ {label} kind={kind} rank={} h_rank={h} f_rank={f} f_prefix_ranks={pre:?}", img.rank);
}
/// Left kernel of a batched image (Ech over BW limbs): which candidate
/// relations annihilate it, how much of the annihilator they explain, and the
/// supports of an echelon basis of the unexplained remainder.
fn left_kernel_report(label: &str, kind: &str, img: &Ech<M31>, cands: &[&Rel]) {
    let rows: Vec<Vec<W>> = img.p.iter().flatten().map(|r| wvals(r)).collect();
    let ann = BW - img.rank;
    let mut holds = vec![];
    let mut fails = vec![];
    let mut expl = Ech::new(BW);
    for c in cands {
        if rows.iter().all(|y| c.eval(y) == W::ZERO) {
            holds.push(c.name.clone());
            for f in c.limb_functionals() {
                expl.insert(f);
            }
        } else {
            let bad = rows.iter().filter(|y| c.eval(y) != W::ZERO).count();
            fails.push(format!("{}({bad})", c.name));
        }
    }
    println!(
        "Z8E_LEFT_KERNEL {label} kind={kind} image_rank={} annihilator_dim={ann} candidates={} holding={} failing={} explained_dim={} unexplained_dim={} failing_names={fails:?}",
        img.rank,
        cands.len(),
        holds.len(),
        fails.len(),
        expl.rank,
        ann - expl.rank
    );
    if expl.rank < ann {
        let mut rest = Ech::new(BW);
        let mut rest_rows = vec![];
        for nv in null_space(img) {
            let r = expl.residual(nv);
            if r.iter().any(|x| *x != M31::ZERO) {
                if rest.insert(r.clone()).is_some() {
                    rest_rows.push(r);
                }
            }
        }
        // Fully reduce the remainder basis (back-substitution) and print
        // supports as batched-coordinate ranges.
        let mut piv: Vec<usize> = rest_rows.iter().map(|r| r.iter().position(|x| *x != M31::ZERO).unwrap()).collect();
        let mut order: Vec<usize> = (0..rest_rows.len()).collect();
        order.sort_by_key(|&i| piv[i]);
        rest_rows = order.iter().map(|&i| rest_rows[i].clone()).collect();
        piv = order.iter().map(|&i| piv[i]).collect();
        for i in (0..rest_rows.len()).rev() {
            let ri = rest_rows[i].clone();
            for j in 0..rest_rows.len() {
                if j != i && rest_rows[j][piv[i]] != M31::ZERO {
                    let sc = rest_rows[j][piv[i]];
                    for t in 0..BW {
                        rest_rows[j][t] = rest_rows[j][t].sub(sc.mul(ri[t]));
                    }
                }
            }
        }
        let mut union = std::collections::BTreeSet::new();
        for (n, r) in rest_rows.iter().enumerate() {
            let cs: Vec<usize> = (0..NB).filter(|&i| (0..8).any(|m| r[8 * i + m] != M31::ZERO)).collect();
            union.extend(cs.iter().copied());
            if n < 16 || n + 4 >= rest_rows.len() {
                println!(
                    "Z8E_LEFT_KERNEL_REST {label} kind={kind} index={n} pivot={}:{} support={}",
                    bat_label(piv[n] / 8),
                    piv[n] % 8,
                    ranges(&cs)
                );
            }
        }
        let _ = support_labels;
        println!("Z8E_LEFT_KERNEL_REST_UNION {label} kind={kind} rank={} support={}", rest.rank, ranges(&union.into_iter().collect::<Vec<_>>()));
    }
}
/// Ech whose pivot order is the round-j coefficients from degree 27 down to
/// 0, all four limbs per degree; returns pivot degrees (one entry per limb pivot).
fn leading_degrees(polys: &[[QM31; 28]]) -> Vec<usize> {
    let mut e = Ech::new(112);
    for p in polys {
        let v: Vec<M31> = (0..28).rev().flat_map(|d| limbs(p[d])).collect();
        e.insert(v);
    }
    (0..112).filter(|&i| e.p[i].is_some()).map(|i| 27 - i / 4).collect()
}

pub(super) fn main() {
    let args: Vec<_> = std::env::args().collect();
    let get = |k: &str| args.windows(2).find(|x| x[0] == k).map(|x| x[1].clone());
    let s = get("--structure").expect("--structure");
    let v: usize = get("--vector").expect("--vector").parse().unwrap();
    let preflight = args.iter().any(|x| x == "--preflight");
    let start = Instant::now();
    println!("Z8E_START structure={s} vector={v} preflight={preflight} transport=D13 batching=WideExact balanced=true proxy=false");
    let t = trial(v);
    let a = alpha_for(&s, v, &t.a);
    let label = format!("structure={s} vector={v}");
    let op = opening_challenges(v);
    println!(
        "Z8E_ALPHA {label} alpha={:?} lambda_dims={:?} good3={} outside_k2={:?}",
        a.map(l4),
        lambda_dims(&a),
        good3(&a),
        (0..10).map(|i| !in_k2(a[i]) as u8).collect::<Vec<_>>()
    );
    println!(
        "Z8E_OPENING {label} gamma={:?} kappa={:?} tau={:?} fold={:?}",
        op.gamma.to_limbs(),
        op.kappa.to_limbs(),
        op.tau.to_limbs(),
        op.fold.to_limbs()
    );
    let basis = NaturalBasis::new(BasisSize::Initial).expect("basis");
    let z = [wpt(t.z[0]), wpt(t.z[1])];
    let total = total_weights(&basis, &a, z, &op);
    let phi = unit_functionals(&basis, z, &total, &op);
    println!("Z8E_CHECK unit_quotients=1024 ok=true eq_orientation=true seconds={:.3}", start.elapsed().as_secs_f64());
    let beta: Vec<[W; NB]> = (0..N)
        .map(|r| {
            let mut b = [W::ZERO; NB];
            b[0] = if inactive(r) { W::ONE } else { W::ZERO };
            b[1..].copy_from_slice(&phi[usize::from(ROW_TO_COEFFICIENT[r])]);
            b
        })
        .collect();
    let gpow = (0..29).map(|l| op.gamma.pow(l as u64)).collect();
    let (br, gr) = raw_c(&a, &t.z, &t.qs);
    let tail: Vec<_> = (0..N).map(|r| tail_row(&a, r)).collect();
    let cx = Ctx { a, br, gr, tail, beta, gpow };
    decomposition_check(&cx, &basis, z, &total, &op, 0x5a38_c0de ^ v as u64);
    // Transport / layout facts used below.
    assert!(inactive(0), "row 0 must be copy-inactive (balance 0)");
    for r in 0..N {
        assert_eq!(usize::from(ROW_TO_COEFFICIENT[r]), usize::from(z5::transport()[r]), "transport tables agree");
    }
    let rows_lo: Vec<usize> = (0..56).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    let rows_hi: Vec<usize> = (56..1024).map(|k| usize::from(COEFFICIENT_TO_ROW[k])).collect();
    let n_inactive = (0..N).filter(|&r| inactive(r)).count();
    println!(
        "Z8E_LAYOUT {label} inactive_rows={n_inactive} row0_coefficient={} rows_lo_all_inactive={} row0_in_rows_lo={} coeff_lt_89_all_inactive={}",
        ROW_TO_COEFFICIENT[0],
        rows_lo.iter().all(|&r| inactive(r)),
        rows_lo.contains(&0),
        (0..89).all(|k| inactive(usize::from(COEFFICIENT_TO_ROW[k])))
    );
    let rel = relations(&total, &op, &t.qs);
    let ln = Lanes::new(&cx);
    println!("Z8E_SETUP {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Pass 1: per-lane own kernels, carrying [batched | round]; global gate Ech. ----
    let mut pure = Ech::new(TW);
    let mut rker: Vec<Ech<M31>> = vec![];
    let mut own_rank = vec![];
    let mut kernel_dims = vec![];
    let mut rel_viol = [0usize; 4]; // ia, S1, S2, S3 (any u)
    let mut carries_checked = 0usize;
    for li in 0..LANES {
        let mut rk = Ech::new(RW);
        let mut ker = 0;
        let n = ln.count(li);
        lane_kernel(
            n,
            |i| {
                let (o, b, r) = ln.bal(li, i);
                (o, carry(b, &r))
            },
            |c| {
                ker += 1;
                let y = wvals(&c[..BW]);
                carries_checked += 1;
                if y[0] != W::ZERO {
                    rel_viol[0] += 1;
                }
                if rel.s1.eval(&y) != W::ZERO {
                    rel_viol[1] += 1;
                }
                if rel.s2.eval(&y) != W::ZERO {
                    rel_viol[2] += 1;
                }
                if rel.s3.iter().any(|r| r.eval(&y) != W::ZERO) {
                    rel_viol[3] += 1;
                }
                rk.insert(c[BW..].to_vec());
                pure.insert(c);
            },
        );
        own_rank.push(n - ker);
        kernel_dims.push(ker);
        println!(
            "Z8E_LANE_OWN {label} lane={} sources={n} own_rank={} own_functionals={} round_image_of_own_kernel={} seconds={:.3}",
            lane_name(li),
            n - ker,
            own_width(li),
            rk.rank,
            start.elapsed().as_secs_f64()
        );
        rker.push(rk);
    }
    let ia_pivots = (0..8).filter(|&i| pure.p[i].is_some()).count();
    let batched_rank = (0..BW).filter(|&i| pure.p[i].is_some()).count();
    println!(
        "Z8E_RELATIONS {label} carries_checked={carries_checked} violations_ia={} violations_S1={} violations_S2={} violations_S3={} relations_annihilate_exactly={}",
        rel_viol[0],
        rel_viol[1],
        rel_viol[2],
        rel_viol[3],
        rel_viol.iter().all(|x| *x == 0)
    );
    if rel_viol.iter().any(|x| *x != 0) {
        println!("STOP reason=verifier_relation_not_annihilating {label} violations={rel_viol:?}");
    }
    let retained = slice_image(&pure, BW);
    let silent = slice_image(&pure, BW + 4);
    // (2) dim R(ker own) = sum of per-lane own-kernel round images.
    let mut rown = Ech::new(RW);
    for rk in &rker {
        for row in ech_rows(rk) {
            rown.insert(row);
        }
    }
    let rown_zero = initial_zero(copied_ech(&rown));
    println!(
        "Z8E_GATE_PURE {label} span_rank={} batched_pivots={batched_rank} ia_pivots={ia_pivots} initial_retained_rank={} silent_rank={} upper_bound=1076 seconds={:.3}",
        pure.rank,
        retained.rank,
        silent.rank,
        start.elapsed().as_secs_f64()
    );
    println!(
        "Z8E_QPRIME {label} round_image_of_ker_own_initial_retained={} initial_zero={} expect=1080",
        rown.rank, rown_zero.rank
    );
    println!(
        "Z8E_B {label} bat_rank_on_ker_own={} bat_rank_on_ker_own_and_ker_R={} expect=1912 (second = span_rank - dim R(ker own) = {} - {})",
        batched_rank - ia_pivots,
        pure.rank - rown.rank,
        pure.rank,
        rown.rank
    );
    let psil = Proj::of(&silent, &a);
    report(&label, "silent", silent.rank, &psil);
    report(&label, "silent_initial_retained", retained.rank, &Proj::of(&retained, &a));
    report(&label, "round_image_of_ker_own", rown.rank, &Proj::of(&rown, &a));
    if silent.rank < 1076 {
        println!("Z8E_FINDING {label} balanced_silent_rank={} below=1076 deficit={}", silent.rank, 1076 - silent.rank);
    }
    let chain0: Vec<Vec<M31>> = (4..RW)
        .map(|i| {
            let mut u = vec![M31::ZERO; RW];
            u[i] = M31::ONE;
            let q = unflat(&u);
            let phi = final_value(&q, &a);
            flatten(&normalize_d(&q, phi, &a).expect("alpha9=1/2"))
        })
        .collect();
    summarize(&format!("{label} chain0_basis"), &silent, &chain0);
    summarize(&format!("{label} qprime_chain0_basis"), &rown_zero, &chain0);
    // (5a) left kernel of bat on ker own.
    {
        let mut img = Ech::new(BW);
        for row in pure.p.iter().take(BW).flatten() {
            img.insert(row[..BW].to_vec());
        }
        let mut c: Vec<&Rel> = vec![&rel.ia, &rel.s1, &rel.s2];
        c.extend(rel.s3.iter());
        left_kernel_report(&label, "bat_on_ker_own", &img, &c);
    }
    println!("Z8E_PASS1_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Z8e (1): wrap set X, C_ll, W_z, low shadow (Facts 1-2 of the design). ----
    let lineq = Secant::from_points(t.z[0], t.z[1]); // QM31 coefficients (z in K4)
    let lcols: Vec<Vec<QM31>> = {
        let ms: Vec<usize> = (0..1024).collect();
        let chunk = ms.len().div_ceil(THREADS);
        let basis_ref = &basis;
        std::thread::scope(|s| {
            let hs: Vec<_> = ms
                .chunks(chunk)
                .map(|part| {
                    s.spawn(move || {
                        part.iter()
                            .map(|&m| {
                                let mut e = [QM31::ZERO; 1024];
                                e[m] = QM31::ONE;
                                let le = chord::chord_message(basis_ref, lineq, &e).expect("chord_message");
                                le[..56].to_vec()
                            })
                            .collect::<Vec<_>>()
                    })
                })
                .collect();
            hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
        })
    };
    let xset: Vec<usize> = (56..1024).filter(|&m| lcols[m].iter().any(|x| *x != QM31::ZERO)).collect();
    const XPRED: [usize; 15] = [61, 62, 63, 125, 126, 127, 253, 254, 255, 509, 510, 511, 1021, 1022, 1023];
    let e1q = FunctionalWeights::e1::<QM31>(&basis).expect("e1");
    let e2q = FunctionalWeights::e2(&basis, lineq.b, lineq.c).expect("e2");
    let e_outside_x = (0..1024).filter(|m| !XPRED.contains(m) && (e1q[*m] != QM31::ZERO || e2q[*m] != QM31::ZERO)).count();
    // C_ll and its inverse.
    let cll: Vec<Vec<QM31>> = (0..56).map(|k| (0..56).map(|m| lcols[m][k]).collect()).collect();
    let (cll_rank, cinv) = {
        let aug: Vec<Vec<QM31>> = (0..56)
            .map(|k| {
                let mut row = cll[k].clone();
                row.extend((0..56).map(|j| if j == k { QM31::ONE } else { QM31::ZERO }));
                row
            })
            .collect();
        let (r, piv) = rref_q(aug, 112);
        let rank = piv.iter().filter(|&&c| c < 56).count();
        let inv: Option<Vec<Vec<QM31>>> = if rank == 56 { Some(r.iter().map(|row| row[56..].to_vec()).collect()) } else { None };
        (rank, inv)
    };
    // W_z: unknowns on lo ∪ X; equations (L q)_lo = 0, e1, e2.
    let cols: Vec<usize> = (0..56).chain(XPRED.iter().copied()).collect();
    let mut eqs: Vec<Vec<QM31>> = (0..56).map(|k| cols.iter().map(|&m| lcols[m][k]).collect()).collect();
    eqs.push(cols.iter().map(|&m| e1q[m]).collect());
    eqs.push(cols.iter().map(|&m| e2q[m]).collect());
    let sol = null_space_q(eqs, cols.len());
    let (wbasis, _) = rref_q(sol.iter().map(|v| v[..56].to_vec()).collect(), 56);
    // Low shadow gamma^28 * Fold_lo(W) as an F-space in the 112 f_lo limbs, and its K-span.
    let fold_lo = |ql: &[QM31], g: W| -> Vec<M31> {
        let mut out = vec![];
        for d in 0..14 {
            let mut acc = W::ZERO;
            let mut p = W::ONE;
            for s in 0..4 {
                acc = acc.add(p.mul(wq(ql[4 * d + s])));
                p = p.mul(op.fold);
            }
            out.extend(wlimbs(g.mul(acc)));
        }
        out
    };
    let g28 = cx.gpow[28];
    let g27 = cx.gpow[27];
    let mut shadow = Ech::new(112);
    let mut shadow_k = Ech::new(112);
    for w in &wbasis {
        for k in 0..4 {
            let tw: Vec<QM31> = w.iter().map(|x| x.mul(tower(k))).collect();
            shadow.insert(fold_lo(&tw, g28));
        }
        for m in 0..8 {
            shadow_k.insert(fold_lo(w, wunit(m).mul(g28)));
        }
    }
    println!(
        "Z8E_WRAP {label} x_set={xset:?} x_set_matches_fact2={} e1e2_outside_x={e_outside_x} cll_rank_k4={cll_rank} wz_solution_dim_k4={} wz_dim_k4={} low_shadow_rank={} low_shadow_kspan_rank={} expect=13,4,16,32",
        xset == XPRED.to_vec(),
        sol.len(),
        wbasis.len(),
        shadow.rank,
        shadow_k.rank
    );
    let cinv = cinv.expect("STOP C_ll singular");
    let emb = |v: Vec<M31>| -> Vec<M31> {
        let mut out = vec![M31::ZERO; BW];
        out[64..176].copy_from_slice(&v);
        out
    };
    let psi_lo: Vec<Vec<M31>> = null_space(&shadow).into_iter().map(emb).collect();
    let psi_k_raw: Vec<Vec<M31>> = null_space(&shadow_k);
    let psi_k: Vec<Vec<M31>> = psi_k_raw.iter().cloned().map(emb).collect();
    // Conjugate relations eta_l (Fact 3), as 8 F-functionals each.
    let quarter = fold::quarter::<W>();
    let abar = sigma(op.fold);
    let dfb = fold::dual_fold(abar, &total);
    let eta = |l: usize| -> Vec<Vec<M31>> {
        let g = cx.gpow[l];
        let gi = <W as CodeField>::try_inv(g).expect("gamma != 0");
        let mut f = vec![vec![M31::ZERO; BW]; 8];
        for i in 8..BW {
            let (idx, limb) = (i / 8, i % 8);
            let y = wunit(limb);
            let val = if idx <= 7 {
                abar.pow((idx - 1) as u64).mul(y)
            } else {
                W::ZERO.sub(g.mul(quarter).mul(sigma(gi.mul(y))).mul(dfb[idx - 8]))
            };
            let ls = val.to_limbs();
            for m in 0..8 {
                f[m][i] = M31(ls[m]);
            }
        }
        f
    };
    let eta_d = eta(28);
    let eta_g = eta(27);
    let mut groups: Vec<(String, Vec<Vec<M31>>)> = vec![
        ("ia".into(), rel.ia.limb_functionals()),
        ("S1".into(), rel.s1.limb_functionals()),
        ("S2".into(), rel.s2.limb_functionals()),
        ("S3".into(), rel.s3.iter().flat_map(|r| r.limb_functionals()).collect()),
    ];
    groups.push(("Psi_lo".into(), psi_lo.clone()));
    groups.push(("eta_D".into(), eta_d.clone()));
    groups.push(("eta_G".into(), eta_g.clone()));
    let tfun: Vec<Vec<M31>> = psi_lo.iter().chain(eta_d.iter()).cloned().collect();
    println!("Z8E_FUNCTIONALS {label} psi_lo={} psi_k={} eta_d={} eta_g={} t={}", psi_lo.len(), psi_k.len(), eta_d.len(), eta_g.len(), tfun.len());
    // Sanity: on bat(ker own) (= B0, pass 1) the 25 relations hold and T has full rank 104.
    {
        let mut img = Ech::new(BW);
        for row in pure.p.iter().take(BW).flatten() {
            img.insert(row[..BW].to_vec());
        }
        explain(&label, "bat_on_ker_own", &img, &groups);
        println!("Z8E_T_RANK {label} kind=bat_on_ker_own t_rank={} expect=104", t_rank(&img, &tfun));
    }
    println!("Z8E_ITEM1_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Z8e (2): V_D (Z8c control block, verbatim) and its left kernel. ----
    let img_d = {
        let s0 = *rows_hi.iter().find(|&&r| inactive(r)).expect("an inactive D-high row");
        for &r in &rows_hi {
            assert!(ln.rr[11][r].iter().all(|x| *x == QM31::ZERO), "D coefficient >= 56 has a round contribution");
        }
        let mut srcs: Vec<(usize, usize, bool)> = vec![];
        for &r in &rows_hi {
            if r == s0 {
                continue;
            }
            for k in 0..4 {
                srcs.push((r, k, inactive(r)));
            }
        }
        let mut img = Ech::new(BW);
        lane_elim(
            srcs.len(),
            |i| {
                let (r, k, sub) = srcs[i];
                let (o, b, _) = ln.raw(11, r, k);
                if sub {
                    let (o0, b0, _) = ln.raw(11, s0, k);
                    (sub_vec(&o, &o0, |x, y| x.sub(y)), wflat(&sub_vec(&b, &b0, |x, y| x.sub(y))))
                } else {
                    (o, wflat(&b))
                }
            },
            |c| {
                img.insert(c);
            },
        );
        img
    };
    println!("Z8E_VD {label} bat_rank={} z8c=1808", img_d.rank);
    explain(&label, "V_D", &img_d, &groups);
    {
        let rows = ech_rows(&img_d);
        let flo = rank_of(112, rows.iter().map(|r| r[64..176].to_vec()));
        let mut joint = copied_ech(&shadow);
        for r in &rows {
            joint.insert(r[64..176].to_vec());
        }
        println!("Z8E_VD_LOW {label} f_lo_rank={flo} low_shadow_rank={} joint_rank={} (f_lo(V_D) = low shadow iff all three equal)", shadow.rank, joint.rank);
    }
    println!("Z8E_ITEM2_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());

    // ---- Z8e (3): G. ----
    assert_eq!(usize::from(ROW_TO_COEFFICIENT[0]), 89, "row 0 coefficient");
    let clo_of = |r: usize, k: usize| -> Vec<M31> {
        let mut out = [QM31::ZERO; 56];
        let co = usize::from(ROW_TO_COEFFICIENT[r]);
        if co < 56 {
            out[co] = tower(k);
        }
        flatten(&out) // e_0's coefficient is 89: the balancing term has no low part
    };
    // (3a) ker R_G ∩ ker own_G, carrying [c_lo (224) | bat (2112)].
    let mut ga = vec![];
    lane_elim(
        ln.count(10),
        |i| {
            let (r, k) = ln.row_of(10, i);
            let (o, b, rd) = ln.bal(10, i);
            let mut v = o;
            v.extend(flatten(&rd));
            let mut c = clo_of(r, k);
            c.extend(wflat(&b));
            (v, c)
        },
        |c| ga.push(c),
    );
    let mut img_g = Ech::new(BW);
    for c in &ga {
        img_g.insert(c[224..].to_vec());
    }
    let glow = rank_of(224, ga.iter().map(|c| c[..224].to_vec()));
    let mut asm = copied_ech(&img_d);
    for row in ech_rows(&img_g) {
        asm.insert(row);
    }
    println!(
        "Z8E_VG {label} kernel_dim={} bat_rank={} z8c=1904 g_low_rank={glow} z8c=220 assembly_rank={} expect=1912 t_rank_on_V_G={} expect=104",
        ga.len(),
        img_g.rank,
        asm.rank,
        t_rank(&img_g, &tfun)
    );
    explain(&label, "V_G", &img_g, &groups);
    // (★) K-part identity on own-silent G words: Psi_K f_lo(bat) = Psi_K gamma^27 Fold_lo(C_ll^-1 c_lo).
    {
        let (mut bad, mut nonzero) = (0usize, 0usize);
        for c in &ga {
            let clo: Vec<QM31> = unflat(&c[..224]);
            let qlo: Vec<QM31> = (0..56).map(|i| (0..56).fold(QM31::ZERO, |s, j| s.add(cinv[i][j].mul(clo[j])))).collect();
            let pred = fold_lo(&qlo, g27);
            let act = &c[224 + 64..224 + 176];
            for f in &psi_k_raw {
                let a1 = dotm(f, act);
                let a2 = dotm(f, &pred);
                if a1 != a2 {
                    bad += 1;
                }
                if a1 != M31::ZERO {
                    nonzero += 1;
                }
            }
        }
        println!("Z8E_STAR {label} carriers={} psi_k_checks={} mismatches={bad} nonzero_values={nonzero}", ga.len(), ga.len() * psi_k_raw.len());
    }
    // (3b) G3: ker R_G ∩ ker own_G ∩ {c_lo = 0}; rank of T on its batched image.
    {
        let mut img = Ech::new(BW);
        let mut n = 0;
        lane_elim(
            ln.count(10),
            |i| {
                let (r, k) = ln.row_of(10, i);
                let (o, b, rd) = ln.bal(10, i);
                let mut v = o;
                v.extend(flatten(&rd));
                v.extend(clo_of(r, k));
                (v, wflat(&b))
            },
            |c| {
                n += 1;
                img.insert(c);
            },
        );
        println!("Z8E_G3 {label} kernel_dim={n} bat_rank={} t_rank={} expect=24 psi_lo_rank={} eta_d_rank={}", img.rank, t_rank(&img, &tfun), t_rank(&img, &psi_lo), t_rank(&img, &eta_d));
    }
    // (3c) query-free split: on ker R_G ∩ ker Rw_G carry [T∘bat (104) | E_G (360)].
    {
        let mut cs = vec![];
        lane_elim(
            ln.count(10),
            |i| {
                let (o, b, rd) = ln.bal(10, i);
                let mut v = o[..16].to_vec();
                v.extend(flatten(&rd));
                let bl = wflat(&b);
                let mut c: Vec<M31> = tfun.iter().map(|f| dotm(f, &bl)).collect();
                c.extend_from_slice(&o[16..]);
                (v, c)
            },
            |c| cs.push(c),
        );
        let ta = rank_of(104, cs.iter().map(|c| c[..104].to_vec()));
        let joint = rank_of(464, cs.iter().cloned());
        let ea = rank_of(360, cs.iter().map(|c| c[104..].to_vec()));
        println!(
            "Z8E_SPLIT {label} kernel_dim={} t_rank_query_free={ta} expect=104 e_rank={ea} expect=360 joint_rank={joint} e_rank_on_ker_t={} expect=360",
            cs.len(),
            joint - ta
        );
    }
    // (3d) G2: Psi_K gamma^27 Fold_lo C_ll^-1 on {t in K4^56 : extra(t) = 0}.
    {
        let mut cs = vec![];
        lane_elim(
            224,
            |i| {
                let (j, k) = (i / 4, i % 4);
                let x = tower(k);
                let v = limbs(h_weight(&a, j).mul(x)).to_vec();
                let qlo: Vec<QM31> = (0..56).map(|ii| cinv[ii][j].mul(x)).collect();
                let pred = fold_lo(&qlo, g27);
                (v, psi_k_raw.iter().map(|f| dotm(f, &pred)).collect())
            },
            |c| cs.push(c),
        );
        println!("Z8E_G2 {label} ker_extra_dim={} rank={} expect=80", cs.len(), rank_of(80, cs.iter().cloned()));
    }
    println!("Z8E_ITEMS_DONE {label} seconds={:.3}", start.elapsed().as_secs_f64());
    if preflight {
        println!("Z8E_PREFLIGHT_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
        return;
    }
    println!("Z8E_DONE {label} wall_seconds={:.3}", start.elapsed().as_secs_f64());
}

// ---- Z8e helpers ----
fn sigma(x: W) -> W {
    W::new(x.c0(), QM31::ZERO.sub(x.c1()))
}
fn dotm(a: &[M31], b: &[M31]) -> M31 {
    a.iter().zip(b).fold(M31::ZERO, |s, (x, y)| s.add(x.mul(*y)))
}
/// Dense reduced row echelon form over QM31; returns (nonzero rows, pivot columns).
fn rref_q(mut a: Vec<Vec<QM31>>, ncols: usize) -> (Vec<Vec<QM31>>, Vec<usize>) {
    let mut piv = vec![];
    let mut r = 0;
    for c in 0..ncols {
        if r == a.len() {
            break;
        }
        let Some(k) = (r..a.len()).find(|&i| a[i][c] != QM31::ZERO) else { continue };
        a.swap(r, k);
        let inv = a[r][c].inv();
        for x in a[r].iter_mut() {
            *x = x.mul(inv);
        }
        let pr = a[r].clone();
        for i in 0..a.len() {
            if i != r && a[i][c] != QM31::ZERO {
                let s = a[i][c];
                for j in 0..ncols {
                    a[i][j] = a[i][j].sub(s.mul(pr[j]));
                }
            }
        }
        piv.push(c);
        r += 1;
    }
    a.truncate(r);
    (a, piv)
}
/// Basis of {y : A y = 0} over QM31.
fn null_space_q(a: Vec<Vec<QM31>>, ncols: usize) -> Vec<Vec<QM31>> {
    let (r, piv) = rref_q(a, ncols);
    (0..ncols)
        .filter(|c| !piv.contains(c))
        .map(|f| {
            let mut v = vec![QM31::ZERO; ncols];
            v[f] = QM31::ONE;
            for (i, &p) in piv.iter().enumerate() {
                v[p] = QM31::ZERO.sub(r[i][f]);
            }
            v
        })
        .collect()
}
/// Rank of the functionals `fs` restricted to the image `img` (rows of the echelon basis).
fn t_rank(img: &Ech<M31>, fs: &[Vec<M31>]) -> usize {
    let rows = ech_rows(img);
    rank_of(fs.len(), rows.iter().map(|r| fs.iter().map(|f| dotm(f, r)).collect()))
}
/// Left kernel of a batched image against named groups of F-functionals.
fn explain(label: &str, kind: &str, img: &Ech<M31>, groups: &[(String, Vec<Vec<M31>>)]) {
    let rows = ech_rows(img);
    let ann = BW - img.rank;
    let mut expl = Ech::new(BW);
    let mut hold = vec![];
    let mut fail = vec![];
    for (name, fs) in groups {
        if fs.iter().all(|f| rows.iter().all(|r| dotm(f, r) == M31::ZERO)) {
            hold.push(name.clone());
            for f in fs {
                expl.insert(f.clone());
            }
        } else {
            fail.push(name.clone());
        }
    }
    println!(
        "Z8E_EXPLAIN {label} kind={kind} image_rank={} annihilator_dim={ann} holding={} failing={} explained_dim={} unexplained_dim={}",
        img.rank,
        hold.join(","),
        if fail.is_empty() { "-".to_string() } else { fail.join(",") },
        expl.rank,
        ann - expl.rank
    );
}

