/// One round column: the 271 entries' four limbs.
pub fn round_col(out: Vec<u32>, al: &[u32], tr: &[u32], inact: &[u32], c: usize, r: usize, k: usize) -> Vec<u32> {
    let mut out = out;
    let mut p: usize = 0;
    while p < 271 {
        let v = src_ent(al, tr, inact, c, r, k, p);
        out.push(v[0]);
        out.push(v[1]);
        out.push(v[2]);
        out.push(v[3]);
