pub fn fill_round(al: &[u32], tr: &[u32], inact: &[u32], kind: &[u32], srow: &[u32], slimb: &[u32], n: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut t: usize = 0;
    while t < n {
        out = round_col(out, al, tr, inact, kind[t] as usize, srow[t] as usize, slimb[t] as usize);
        t += 1;
    }
    out
}

