/// One G batched column: the 78 + nf cells' eight limbs.
pub fn gbat_col(out: Vec<u32>, al: &[u32], zz: &[u32], tr: &[u32], inact: &[u32], ti: &[u32], op: &[u32], x18: &[u32], nf: usize, r: usize, k: usize) -> Vec<u32> {
    let mut out = out;
    let mut c: usize = 0;
    while c < 78 + nf {
        let v = gbat_cell(al, zz, tr, inact, ti, op, x18, nf, r, k, c);
        out.push(v[0]);
        out.push(v[1]);
        out.push(v[2]);
        out.push(v[3]);
        out.push(v[4]);
        out.push(v[5]);
        out.push(v[6]);
        out.push(v[7]);
        c += 1;
    }
    out
}
/// The G batched columns of n referenced G sources (pb.gbat), column t at 8 (78 + nf) t.
pub fn fill_gbat(al: &[u32], zz: &[u32], tr: &[u32], inact: &[u32], ti: &[u32], op: &[u32], x18: &[u32], srow: &[u32], slimb: &[u32], n: usize, nf: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut t: usize = 0;
    while t < n {
        out = gbat_col(out, al, zz, tr, inact, ti, op, x18, nf, srow[t] as usize, slimb[t] as usize);
        t += 1;
    }
    out
}

//! Actual shipped Drop, no stubs. Its owned Vec buffers are part of the footprint.
//! The small harness covers arbitrary lengths 0..=2 in every column. The fixed
//! harness covers the admitted 16 x 1024 shape, with arbitrary stored words.
use aspis_core::field::M31;
use aspis_statement::state_only_trace::StateOnlyTraceFoundation;

fn check_drop(trace: StateOnlyTraceFoundation) {
    // A separately owned allocation models retained output bytes. Rust's
    // unique ownership excludes aliases to the trace's owned buffers.
    let output: u64 = kani::any();
    let retained = Box::new(output);
    let result: () = drop(trace);
    assert_eq!(result, ());
    assert_eq!(*retained, output);
}

#[kani::proof]
#[kani::unwind(18)]
fn trace_drop_small() {
    let mut trace = StateOnlyTraceFoundation::default();
    for i in 0..16 {
        let n: usize = kani::any();
        kani::assume(n <= 2);
        for _ in 0..n {
            // All storage words, including non-canonical ones, are allowed.
            trace.c1[i].push(M31(kani::any()));
        }
    }
    check_drop(trace);
}

#[kani::proof]
#[kani::unwind(1026)]
fn trace_drop_full() {
    let mut trace = StateOnlyTraceFoundation::default();
    for i in 0..16 {
        let words: [u32; 1024] = kani::any();
        trace.c1[i] = words.into_iter().map(M31).collect();
    }
    check_drop(trace);
}

