        // (prefund lamports, expected System CPI count): none -> one
        // CreateAccountWithSeed; partial -> Transfer + AllocateWithSeed +
        // AssignWithSeed; full rent -> AllocateWithSeed + AssignWithSeed.
        for (prefund, expected_calls) in [
            (0u64, 1usize),
            (1, 3),
